  SELECT count(*) INTO matched FROM public.words w
  JOIN jsonb_array_elements($payload$[{"id":724,"quiz":{"q":"100만 원을 연 10% 복리로 2년간 맡겼어요. 세금이 없다면 얼마가 되나요?","options":["121만 원","120만 원","110만 원"],"answer":0,"explanation":"둘째 해에는 원금과 첫해 이자를 합한 110만 원에 10%가 붙어요.","type":"quiz","lessonCheck":true},"before":[{"body":"이자에도 이자가 붙는 방식이에요.\n작년에 받은 이자가 원금에 더해져 올해는 더 큰 돈에 이자가 붙어요.","type":"text","title":"쉽게 설명"},{"body":"72의 법칙: 72 ÷ 연 수익률 = 돈이 2배가 되는 대략의 햇수\n연 6%면 72 ÷ 6 = 약 12년, 연 8%면 약 9년이에요.","type":"text","title":"쉽게 계산하는 법"},{"x":["0년","1년","2년","3년","4년","5년","6년","7년","8년","9년","10년"],"type":"line","unit":"만 원","title":"100만 원을 연 10%로 10년 맡기면","series":[{"name":"복리","values":[100,110,121,133.1,146.4,161.1,177.2,194.9,214.4,235.8,259.4]},{"name":"단리","values":[100,110,120,130,140,150,160,170,180,190,200]}],"caption":"단리: 처음 넣은 100만 원에만 이자가 붙어요.\n1년 +10만 → 2년 +10만 → 3년 +10만\n\n복리: 통장에 있는 돈 전체에 이자가 붙어요.\n1년 +10만 → 2년 +11만 → 3년 +12.1만\n작년 이자도 올해 이자를 만들어요.\n\n10년째 한 해 이자는 단리 10만 원, 복리 23.6만 원이에요.\n(세금·수수료 제외 예시)"},{"rows":[["이자가 붙는 곳","원금에만","원금 + 쌓인 이자"],["10년 뒤 (100만 원, 연 10%)","200만 원","약 259만 원"],["시간이 지날수록","일정하게 증가","점점 빠르게 증가"]],"type":"table","title":"단리와 복리 비교","columns":["구분","단리","복리"]}]},{"id":1011,"quiz":{"q":"다른 조건은 같고 사과 가격만 올랐어요. 수요의 법칙에 따른 변화는?","options":["수요곡선 자체가 오른쪽 이동","사려는 양 감소","사려는 양 증가"],"answer":1,"explanation":"가격 자체의 변화는 같은 수요곡선 위에서 수요량을 바꿔요.","type":"quiz","lessonCheck":true},"before":[{"body":"붕어빵이 비싸지면 덜 사고 싸지면 더 사요.\n소득, 유행처럼 가격 말고 다른 조건은 멈춰두고 본다는 게 전제예요.","type":"text","title":"쉽게 설명"},{"rows":[["100원","5개"],["50원","10개"]],"type":"table","title":"가격과 수요량","columns":["가격","사려는 양"]},{"body":"\"다른 조건이 같다면\"이 핵심이에요.\n소득이 늘어 더 사는 건 수요의 법칙이 아니라 수요의 변화예요.","type":"text","title":"왜 중요할까?"}]},{"id":1026,"quiz":{"q":"한 가격에서 손님은 100개를 사고 가게도 100개를 팔려 해요. 이 상태는?","options":["초과수요","초과공급","시장균형"],"answer":2,"explanation":"그 가격에서 수요량과 공급량이 같아 부족분이나 남는 물량이 없어요.","type":"quiz","lessonCheck":true},"before":[{"body":"경매장에서 사려는 사람이 많으면 값이 오르고 적으면 내려요.\n그러다 사려는 양과 팔려는 양이 같아지는 곳에서 멈춰요.","type":"text","title":"쉽게 설명"},{"rows":[["수요 증가","상승","증가"],["수요 감소","하락","감소"],["공급 증가","하락","증가"],["공급 감소","상승","감소"]],"type":"table","title":"한 곡선만 움직일 때","columns":["변화","균형가격","균형거래량"]},{"rows":[["증가","증가","증가","알 수 없음"],["감소","감소","감소","알 수 없음"],["증가","감소","알 수 없음","상승"],["감소","증가","알 수 없음","하락"]],"type":"table","title":"두 곡선이 같이 움직일 때","columns":["수요","공급","균형거래량","균형가격"]}]},{"id":1029,"quiz":{"q":"같은 가격에서 손님은 100개를 원하지만 가게는 60개만 팔려 해요. 부족한 양은?","options":["40개","60개","160개"],"answer":0,"explanation":"수요량 100개에서 공급량 60개를 빼면 초과수요는 40개예요.","type":"quiz","lessonCheck":true},"before":[{"body":"인기 공연 표가 정가가 너무 싸서 금방 동나는 상황이에요.\n모자라니 웃돈을 붙인 암표가 등장해요.","type":"text","title":"쉽게 설명"},{"rows":[["가격 위치","균형보다 쌈","균형보다 비쌈"],["상황","물건이 모자람","물건이 남음"],["가격 변화","상승","하락"],["규제 사례","최고가격제","최저가격제"]],"type":"table","title":"초과수요 vs 초과공급","columns":["구분","초과수요","초과공급"]}]},{"id":1,"quiz":{"q":"한 달 수입이 300만 원, 지출이 250만 원이에요. 가계수지는?","options":["550만 원 흑자","50만 원 흑자","50만 원 적자"],"answer":1,"explanation":"수입에서 지출을 빼면 50만 원이 남아요.","type":"quiz","lessonCheck":true},"before":null},{"id":224,"quiz":{"q":"새 아파트 100가구를 분양했지만 20가구가 계약되지 않았어요. 이 20가구는?","options":["전세주택","기존 중고주택","미분양주택"],"answer":2,"explanation":"분양했으나 팔리지 않은 새 주택을 미분양주택이라 해요.","type":"quiz","lessonCheck":true},"before":null},{"id":578,"quiz":{"q":"연소득 5천만 원, 모든 대출의 연간 원리금이 1천만 원이면 단순 계산한 DSR은?","options":["20%","5%","50%"],"answer":0,"explanation":"연간 원리금 1천만 원을 연소득 5천만 원으로 나눠요. 실제 심사에서는 대출별 산정 규칙도 적용돼요.","type":"quiz","lessonCheck":true},"before":null},{"id":945,"quiz":{"q":"새 소파를 산 뒤 어울리는 탁자와 조명까지 샀어요. 이 연쇄 소비는?","options":["기저효과","디드로 효과","립스틱 효과"],"answer":1,"explanation":"한 물건의 구매가 주변 물건의 추가 구매를 유발한 사례예요.","type":"quiz","lessonCheck":true},"before":null},{"id":901,"quiz":{"q":"과자 가격은 2천 원인데 내용량이 100g에서 80g으로 줄었어요. 해석은?","options":["단위 무게당 가격 하락","실질 가격 불변","단위 무게당 가격 상승"],"answer":2,"explanation":"1g당 가격이 20원에서 25원으로 올라요.","type":"quiz","lessonCheck":true},"before":null},{"id":1174,"quiz":{"q":"매년 6%로 꾸준히 성장한다고 가정해요. 72의 법칙으로 두 배까지 걸리는 기간은?","options":["약 12년","약 6년","약 72년"],"answer":0,"explanation":"72를 성장률 숫자 6으로 나눈 12년으로 어림해요. 정확한 복리 계산값은 아니에요.","type":"quiz","lessonCheck":true},"before":[{"body":"연 4%씩 크면 72 ÷ 4 = 18년 뒤에 두 배가 돼요.\n이자율 6%짜리 예금이면 약 12년 뒤 원금이 두 배예요.","type":"text","title":"쉽게 설명"},{"rows":[["3%","약 24년","약 23.4년"],["4%","약 18년","약 17.7년"],["7%","약 10년","약 10.2년"]],"type":"table","title":"72의 법칙 vs 실제 계산","columns":["성장률","72의 법칙","실제"]}]},{"id":364,"quiz":{"q":"명목임금은 그대로인데 물가가 10% 올랐어요. 실질임금은?","options":["변하지 않는다","하락한다","상승한다"],"answer":1,"explanation":"같은 임금으로 살 수 있는 양이 줄어 구매력 기준 임금이 낮아져요.","type":"quiz","lessonCheck":true},"before":null},{"id":573,"quiz":{"q":"청년 경제활동인구 100명 중 취업자 90명, 실업자 10명이에요. 청년실업률은?","options":["약 11.1%","90%","10%"],"answer":2,"explanation":"실업자를 취업자만이 아니라 전체 경제활동인구로 나눠요.","type":"quiz","lessonCheck":true},"before":null},{"id":721,"quiz":{"q":"15세 이상 200명 중 취업자 100명, 실업자 20명이에요. 경제활동참가율은?","options":["60%","50%","10%"],"answer":0,"explanation":"취업자와 실업자를 합친 120명을 15세 이상 인구 200명으로 나눠요.","type":"quiz","lessonCheck":true},"before":null},{"id":1009,"quiz":{"q":"빵집이 제빵사를 채용하고 오븐을 빌려요. 무엇을 거래하는 시장인가요?","options":["외환시장","생산요소 시장","최종 소비재 시장"],"answer":1,"explanation":"노동과 생산 설비는 빵을 만드는 데 투입되는 생산요소예요.","type":"quiz","lessonCheck":true},"before":[{"body":"내가 회사에 노동을 팔고 월급을 받는 곳이에요.\n이때는 가계가 파는 쪽, 기업이 사는 쪽이에요.","type":"text","title":"쉽게 설명"},{"type":"flow","steps":["가계가 노동·자본·토지 제공","기업이 생산에 사용","가계가 임금·이자·지대 받음","그 소득으로 생산물 시장에서 소비"],"title":"돈과 생산요소의 흐름"}]},{"id":749,"quiz":{"q":"고정 이자를 주는 기존 채권의 거래 가격이 떨어졌어요. 다른 조건이 같다면 수익률은?","options":["내린다","항상 그대로다","오른다"],"answer":2,"explanation":"같은 미래 지급액을 더 싼 가격에 사므로 수익률은 높아져요.","type":"quiz","lessonCheck":true},"before":[{"body":"기준금리는 한국은행이 정하는 금리이고, 시장금리는 시장에서 사고파는 사람들이 만드는 금리예요.\n그래서 기준금리가 그대로여도 시장금리는 매일 조금씩 움직여요.","type":"text","title":"쉽게 설명"},{"body":"내 대출 이자와 예금 이자는 기준금리보다 시장금리를 더 직접 따라가요.","type":"text","title":"왜 중요할까?"},{"type":"flow","steps":["기준금리 ↑","은행끼리 빌리는 단기금리 ↑","국고채·CD 같은 시장금리 ↑","은행 대출·예금 금리 ↑"],"title":"기준금리가 시장금리로 이어지는 길","caption":"시장이 앞으로 금리가 오를 거라 예상하면 기준금리가 오르기 전에 시장금리가 먼저 오르기도 해요."},{"item":"0101000","stat":"722Y001","type":"ecos","unit":"%","cycle":"M","title":"기준금리와 시장금리(국고채 3년)","months":60,"series":[{"item":"0101000","name":"기준금리","stat":"722Y001"},{"item":"5020000","name":"국고채 3년","stat":"721Y001"}],"caption":"시장금리는 기준금리를 따라 움직이지만, 앞으로의 금리 예상을 먼저 반영해 미리 오르거나 내리기도 해요."}]},{"id":905,"quiz":{"q":"기준금리가 3.0%에서 3.5%로 올랐어요. 인상 폭은?","options":["0.5%포인트","0.5%","3.5%포인트"],"answer":0,"explanation":"두 금리의 차이는 0.5%포인트이며, 이런 폭의 조정을 빅스텝이라고 불러요.","type":"quiz","lessonCheck":true},"before":null},{"id":820,"quiz":{"q":"주식 1주를 5주로 액면분할해요. 분할만으로 기존 10주는 몇 주가 되나요?","options":["10주","50주","2주"],"answer":1,"explanation":"주식 수가 5배가 되지만 분할 자체로 기업 가치나 보유 지분율이 늘지는 않아요.","type":"quiz","lessonCheck":true},"before":null},{"id":849,"quiz":{"q":"회사가 새 주식을 발행해 투자자에게 돈을 받고 팔았어요. 어떤 자금 조달인가요?","options":["무상증자","액면분할","유상증자"],"answer":2,"explanation":"유상증자는 새 주식의 대금을 받아 회사 자본을 늘리는 방식이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":867,"quiz":{"q":"투자자가 악재를 보고 가치 검토 없이 급히 주식을 모두 팔았어요. 가까운 표현은?","options":["패닉 셀","리밸런싱","유상증자"],"answer":0,"explanation":"공포에 휩쓸려 급하게 매도하는 행동을 패닉 셀이라 해요.","type":"quiz","lessonCheck":true},"before":null},{"id":893,"quiz":{"q":"집값이 더 오를까 불안해 예산 검토도 없이 매수를 서둘러요. 가까운 표현은?","options":["차익실현","패닉 바잉","분산투자"],"answer":1,"explanation":"가격 상승을 놓칠 것이라는 불안이 성급한 매수로 이어진 상황이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":928,"quiz":{"q":"100주 주문에 0을 더 입력해 1,000주를 주문했어요. 어떤 위험의 사례인가요?","options":["환율 위험","배당 감소","팻 핑거"],"answer":2,"explanation":"입력 실수로 의도와 다른 주문이 나간 사례예요.","type":"quiz","lessonCheck":true},"before":null},{"id":996,"quiz":{"q":"회사가 번 이익 일부를 주주에게 정기적으로 나눠 줘요. 이 현금 흐름은?","options":["배당","대출 원금 상환","신주 청약 대금"],"answer":0,"explanation":"배당은 이익의 일부를 주주에게 분배하는 것이며 금액과 지급 여부는 변할 수 있어요.","type":"quiz","lessonCheck":true},"before":null},{"id":847,"quiz":{"q":"펀드가 특정 주가지수와 비슷한 구성과 수익률을 목표로 운용돼요. 가까운 유형은?","options":["정기예금","패시브펀드","개별 종목 직접투자"],"answer":1,"explanation":"지수를 따라가는 운용은 시장 초과 수익을 적극 추구하는 운용과 구분돼요.","type":"quiz","lessonCheck":true},"before":null},{"id":879,"quiz":{"q":"목표는 주식 60%, 채권 40%인데 주가 상승으로 80:20이 됐어요. 목표 비중으로 되돌리는 일은?","options":["공매도","액면분할","리밸런싱"],"answer":2,"explanation":"자산 가격 변화로 달라진 비중을 정해 둔 목표에 맞추는 조정이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":964,"quiz":{"q":"초기 투자자가 보유한 스타트업 지분을 팔아 투자금을 회수했어요. 이 과정은?","options":["엑시트","신규 출자","유상증자 참여"],"answer":0,"explanation":"기존 투자에서 지분 매각 등으로 빠져나와 자금을 회수한 것이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":993,"quiz":{"q":"개인이 창업 초기 기업에 자기 돈을 투자하고 지분을 받아요. 가까운 유형은?","options":["국채 매입","엔젤투자","주택담보대출"],"answer":1,"explanation":"개인이 초기 기업의 성장 가능성을 보고 위험을 부담하며 투자하는 방식이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":751,"quiz":{"q":"1달러 가격이 1,200원에서 1,300원이 됐어요. 100달러 구매 비용은 얼마나 늘었나요?","options":["100원","10만 원","1만 원"],"answer":2,"explanation":"달러당 100원씩 더 필요하므로 100달러에는 1만 원이 더 들어요.","type":"quiz","lessonCheck":true},"before":[{"body":"환율이 오르면 달러가 비싸진 것, 원화가 싸진 것이에요.\n해외여행과 수입품은 비싸지고, 수출 기업은 같은 달러를 벌어도 원화로 더 많이 받아요.","type":"text","title":"쉽게 설명"},{"rows":[["수출 기업","원화로 바꾼 매출 ↑"],["수입 기업·소비자","수입품 가격 ↑"],["해외여행","비용 ↑"],["물가","수입물가를 통해 ↑"]],"type":"table","title":"환율이 오르면 누가 웃고 누가 울까","columns":["누구","영향"]},{"type":"flow","steps":["원·달러 환율 ↑","수입 원자재·에너지 값 ↑","기업 생산비 ↑","소비자 물가 ↑"],"title":"환율이 물가로 이어지는 길","caption":"환율이 내리면 반대로 수입물가가 내려 물가 부담이 줄어요."}]},{"id":883,"quiz":{"q":"한 기간 상품 수출액이 120억 달러, 수입액이 100억 달러예요. 무역수지는?","options":["20억 달러 흑자","20억 달러 적자","220억 달러 흑자"],"answer":0,"explanation":"수출액에서 수입액을 뺀 차이가 양수이므로 흑자예요.","type":"quiz","lessonCheck":true},"before":null},{"id":1186,"quiz":{"q":"한 지역이 기회비용이 낮은 과일 생산에 자원을 집중하고 옷은 다른 지역과 교환해요. 이 생산 방식은?","options":["가격통제","특화","자급자족"],"answer":1,"explanation":"비교적 유리한 생산에 집중하는 것이 특화이며 교환과 함께 활용돼요.","type":"quiz","lessonCheck":true},"before":[{"body":"요리 잘하는 사람은 요리만, 청소 잘하는 사람은 청소만 하면 둘 다 일이 빨리 끝나요.\n나라끼리도 같은 원리로 이득을 봐요.","type":"text","title":"쉽게 설명"},{"rows":[["무역 전 소비","X 5, Y 5","X 5, Y 5"],["특화 생산","X 15","Y 15"],["7개씩 교환 뒤 소비","X 8, Y 7","X 7, Y 8"]],"type":"table","title":"특화하면 얼마나 늘까 (예시)","caption":"두 나라 모두 무역 전보다 소비가 늘어요.","columns":["구분","한국","일본"]}]},{"id":491,"quiz":{"q":"정부가 경기 부양을 위해 공공사업 지출을 늘려요. 어떤 정책인가요?","options":["긴축 통화정책","기업의 배당정책","확장 재정정책"],"answer":2,"explanation":"정부 지출 확대는 총수요를 늘리려는 재정정책 수단이에요.","type":"quiz","lessonCheck":true},"before":[{"body":"정부가 세금을 걷고 돈을 쓰는 방식으로 경기를 조절하는 거예요.\n경기가 나쁘면 더 쓰고 세금을 깎고, 과열되면 덜 써요.","type":"text","title":"쉽게 설명"},{"body":"통화정책은 한국은행이 금리로, 재정정책은 정부가 예산으로 경기를 조절해요.","type":"text","title":"통화정책과 무엇이 다를까?"},{"rows":[["불황 (일손·설비가 놀고 있음)","큼","정부가 쓴 돈이 새 생산과 고용으로 이어져요"],["금리가 0 근처","큼","정부 지출이 늘어도 금리가 올라 민간 투자를 밀어내지 않아요"],["완전고용·호황","작음","더 만들 여력이 없어 물가만 오르기 쉬워요"],["수입 비중이 큰 나라","작음","쓴 돈의 상당 부분이 해외로 빠져나가요"],["정부부채가 많음","작음","나중에 세금이 오를 거라 보고 가계가 소비를 줄여요"]],"type":"table","title":"재정승수가 상황마다 다른 이유","caption":"재정승수는 정부가 1원을 쓸 때 GDP가 몇 원 늘어나는지를 나타내요.","columns":["상황","재정승수","이유"]},{"type":"flow","steps":["정부지출 ↑·세금 ↓","가계·기업 소득 ↑","소비·투자 ↑","총수요 ↑","생산·고용 ↑"],"title":"경기가 나쁠 때 정부가 돈을 더 쓰면","caption":"대신 나랏빚이 늘 수 있고, 정부가 돈을 많이 빌리면 금리가 올라 민간 투자를 밀어낼 수도 있어요(구축효과)."}]},{"id":939,"quiz":{"q":"항만과 철도를 확충해 기업의 운송 여건을 개선해요. 이런 시설은?","options":["사회간접자본","가계 금융자산","소비재 재고"],"answer":0,"explanation":"여러 생산 활동을 뒷받침하는 공공 기반 시설이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":984,"quiz":{"q":"쓰레기 처리 시설의 필요성은 인정하지만 자기 동네 설치만 반대해요. 가까운 현상은?","options":["리쇼어링","님비","특화"],"answer":1,"explanation":"시설의 사회적 필요와 자기 지역의 부담을 다르게 받아들이는 사례예요.","type":"quiz","lessonCheck":true},"before":null},{"id":560,"quiz":{"q":"카드로 결제하자 연결된 예금계좌에서 즉시 돈이 빠졌어요. 가까운 결제 방식은?","options":["후불 외상 결제","장기 할부대출","직불 결제"],"answer":2,"explanation":"직불 방식은 계좌 잔액에서 결제 대금이 즉시 지급돼요.","type":"quiz","lessonCheck":true},"before":null},{"id":269,"quiz":{"q":"가게가 수많은 주문 기록을 분석해 시간대별 수요를 예측해요. 활용하는 것은?","options":["빅데이터 분석","액면분할","화폐 발행"],"answer":0,"explanation":"대량의 거래 자료에서 패턴을 찾아 의사결정에 사용하는 사례예요.","type":"quiz","lessonCheck":true},"before":null},{"id":500,"quiz":{"q":"손님이 온라인 쇼핑몰에서 주문하고 결제했어요. 이 거래는?","options":["중앙은행 공개시장운영","전자상거래","은행 간 결제만을 위한 거래"],"answer":1,"explanation":"온라인으로 상품이나 서비스를 거래하는 전자상거래 사례예요.","type":"quiz","lessonCheck":true},"before":null},{"id":897,"quiz":{"q":"제품의 환경 개선 근거는 없는데 친환경 이미지만 강조해 광고해요. 주의할 현상은?","options":["리쇼어링","가격경쟁","그린워싱"],"answer":2,"explanation":"실제 환경 성과보다 친환경인 것처럼 보이게 포장하는 행위예요.","type":"quiz","lessonCheck":true},"before":null},{"id":990,"quiz":{"q":"기업이 반도체 설계만 맡고 생산은 전문 제조업체에 의뢰해요. 이 기업의 유형은?","options":["팹리스","파운드리","종합상사"],"answer":0,"explanation":"팹리스는 자체 제조 공장 없이 반도체 설계에 집중해요.","type":"quiz","lessonCheck":true},"before":null},{"id":902,"quiz":{"q":"장부상 이익은 있지만 외상대금을 받지 못해 만기 채무를 갚지 못했어요. 가능한 상황은?","options":["무상증자","흑자도산","현금 과잉"],"answer":1,"explanation":"이익 발생과 현금 유입 시점은 달라서 흑자여도 지급 불능에 빠질 수 있어요.","type":"quiz","lessonCheck":true},"before":null},{"id":983,"quiz":{"q":"작은 업체가 특정 알레르기가 있는 고객만을 위한 제품에 집중해요. 겨냥하는 시장은?","options":["전체 대중시장","은행 간 시장","니치마켓"],"answer":2,"explanation":"큰 시장 안에서 특정 수요를 가진 좁은 고객층을 공략하는 전략이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":644,"quiz":{"q":"처분가능소득이 100만 원 늘었을 때 소비가 70만 원 늘었어요. 한계소비성향은?","options":["0.7","1.7","약 1.43"],"answer":0,"explanation":"추가 소비 70만 원을 추가 소득 100만 원으로 나눠요.","type":"quiz","lessonCheck":true},"before":null},{"id":1004,"quiz":{"q":"매출 100만 원, 명시적 비용 60만 원, 포기한 다른 일의 소득 30만 원이에요. 경제학적 이익은?","options":["70만 원","10만 원","40만 원"],"answer":1,"explanation":"명시적 비용뿐 아니라 암묵적 기회비용 30만 원도 차감해요.","type":"quiz","lessonCheck":true},"before":[{"body":"번 돈에서 쓴 돈만 빼면 회계학적 이익이에요.\n포기한 월급까지 빼야 경제학적 이익이에요.\n0보다 크면 그 선택이 다른 선택보다 나아요.","type":"text","title":"쉽게 설명"},{"type":"flow","steps":["총수입 확인","명시적 비용(낸 돈) 빼기","암묵적 비용(포기한 수입) 빼기","0보다 크면 선택"],"title":"경제학적 이익 구하는 순서","caption":"이미 써서 못 돌려받는 매몰비용은 계산에서 빼요."},{"body":"경제학적 이익이 0이라는 건 망했다는 뜻이 아니에요.\n다른 데서 벌 수 있던 만큼은 번 상태라는 뜻이에요.","type":"text","title":"왜 중요할까?"}]},{"id":1015,"quiz":{"q":"이번 달 월급과 오늘의 예금 잔액을 구분해요. 올바른 연결은?","options":["월급은 저량, 잔액은 유량","둘 다 유량","월급은 유량, 잔액은 저량"],"answer":2,"explanation":"기간에 걸쳐 생긴 소득은 유량, 한 시점의 보유액은 저량이에요.","type":"quiz","lessonCheck":true},"before":[{"body":"\"월급 300만원\"은 한 달이라는 기간이 있어야 뜻이 통해서 유량이에요.\n\"통장에 300만원\"은 지금 이 순간의 양이라 저량이에요.","type":"text","title":"쉽게 설명"},{"rows":[["기준","일정 기간 동안의 흐름","특정 시점의 상태"],["예시","GDP, 월급, 이자, 월세","통장 잔고, 외환보유액"],["재무제표","손익계산서","재무상태표"]],"type":"table","title":"유량 vs 저량","columns":["구분","유량(Flow)","저량(Stock)"]},{"body":"대출 잔액은 저량이고, 한 달 새 늘어난 대출은 유량이에요.\n\"기간\"이 붙으면 유량이라고 기억해요.","type":"text","title":"헷갈리기 쉬운 점"}]},{"id":1031,"quiz":{"q":"가격이 10% 올랐을 때 수요량이 약 20% 줄었어요. 수요의 가격탄력성 절댓값은 대략?","options":["2","0.5","0.1"],"answer":0,"explanation":"수요량 변화율의 절댓값을 가격 변화율로 나누면 20/10=2예요.","type":"quiz","lessonCheck":true},"before":[{"body":"과자값이 내리면 훨씬 많이 사고 오르면 안 사버려요.\n가격에 민감하게 반응하는 수요예요.","type":"text","title":"쉽게 설명"},{"rows":[["탄력성 값","1 초과","1 미만"],["수요량 반응","가격보다 더 변함","가격보다 덜 변함"],["수요곡선(같은 점 비교)","완만함","가파름"],["예시","과자","쌀"]],"type":"table","title":"탄력적 vs 비탄력적","columns":["구분","탄력적","비탄력적"]},{"rows":[["대체재 수","많을수록"],["지출 비중","클수록"],["측정 기간","길수록"],["상품 범위","좁을수록"]],"type":"table","title":"탄력적이 되는 요인","columns":["요인","탄력적이 되는 쪽"]}]},{"id":1037,"quiz":{"q":"농산물 수요가 비탄력적인데 풍년으로 공급이 크게 늘었어요. 농가 총수입은?","options":["반드시 그대로다","줄어들 수 있다","반드시 늘어난다"],"answer":1,"explanation":"판매량 증가보다 가격 하락 효과가 커지면 총수입이 줄 수 있어요.","type":"quiz","lessonCheck":true},"before":[{"body":"배추 농사가 잘돼 물량이 넘치면 값이 폭락해요.\n많이 수확했는데 손에 쥐는 돈은 줄어드는 거예요.","type":"text","title":"쉽게 설명"},{"type":"flow","steps":["풍작으로 공급 증가","수요가 비탄력적이라 판매량은 조금만 늘어남","가격이 크게 하락","농가 총수입 감소"],"title":"풍년의 역설이 생기는 과정"},{"body":"산지에서 수확한 배추를 갈아엎는 뉴스가 바로 이 현상이에요.\n정부가 수매나 비축으로 가격을 받치는 이유이기도 해요.","type":"text","title":"왜 중요할까?"}]},{"id":1060,"quiz":{"q":"용돈 1만 원으로 2천 원짜리 음료와 3천 원짜리 빵을 사요. 가능한 조합은?","options":["음료 3개와 빵 2개","음료 1개와 빵 3개","음료 2개와 빵 2개"],"answer":2,"explanation":"첫 조합만 총액 1만 원으로 예산을 넘지 않아요.","type":"quiz","lessonCheck":true},"before":[{"body":"한 달 용돈이 10만원이면 그 안에서만 살 수 있어요.\n갖고 싶은 건 많아도 돈이 한계를 정해요.","type":"text","title":"쉽게 설명"},{"rows":[["예산선 위","돈을 다 쓴 조합"],["예산선 안쪽","살 수 있지만 돈이 남는 조합"],["예산선 바깥","돈이 모자라 못 사는 조합"]],"type":"table","title":"예산선 기준 위치","columns":["위치","의미"]}]},{"id":1113,"quiz":{"q":"산 빵을 먹으면 다른 사람이 그 빵을 먹을 수 없고, 판매자가 미구매자를 배제할 수 있어요. 빵은?","options":["사적재","순수 공공재","비경합적 정보"],"answer":0,"explanation":"배제성과 경합성을 모두 가진 소비재의 사례예요.","type":"quiz","lessonCheck":true},"before":[{"body":"내가 산 빵을 먹으면 다른 사람은 그 빵을 못 먹어요.\n돈을 안 내면 가게에서 가져갈 수도 없어요. 이런 보통 물건이 사적재예요.","type":"text","title":"쉽게 설명"},{"rows":[["경합성","있음","없음"],["배제성","있음","없음"],["시장 수요","개인 수요를 가로로 더함","한계편익을 세로로 더함"],["시장에 맡기면","잘 공급됨","과소 공급"]],"type":"table","title":"사적재와 공공재 비교","columns":["구분","사적재","공공재"]}]},{"id":378,"quiz":{"q":"소득이 늘어 식비는 조금 늘었지만 전체 소비에서 식비 비중은 낮아졌어요. 가까운 법칙은?","options":["그레샴의 법칙","엥겔의 법칙","수요의 법칙"],"answer":1,"explanation":"소득이 높아질수록 소비지출 중 식비 비중이 낮아지는 경향이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":1039,"quiz":{"q":"소득이 20% 늘 때 어떤 물건의 수요가 5%만 늘었어요. 소득탄력성 기준 유형은?","options":["사치재","열등재","필수재"],"answer":2,"explanation":"소득탄력성이 양수이면서 1보다 작으므로 필수재로 분류해요.","type":"quiz","lessonCheck":true},"before":[{"body":"월급이 두 배가 돼도 쌀을 두 배로 먹진 않아요.\n소득보다 덜 늘어나는 재화가 필수재예요.","type":"text","title":"쉽게 설명"},{"rows":[["필수재·사치재","소득탄력성","0~1이면 필수재, 1 초과면 사치재"],["탄력적·비탄력적","가격탄력성","1 초과면 탄력적, 1 미만이면 비탄력적"]],"type":"table","title":"헷갈리기 쉬운 두 기준","columns":["구분","기준","내용"]}]},{"id":50,"quiz":{"q":"자동차 주문은 충분하지만 반도체 부족으로 생산이 멈췄어요. 가까운 현상은?","options":["공급병목","초과공급 재고 누적","수요 소멸"],"answer":0,"explanation":"특정 투입물의 부족이 전체 생산 흐름을 막은 상황이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":189,"quiz":{"q":"물가상승률이 5%에서 2%로 낮아졌어요. 가장 정확한 해석은?","options":["물가가 오르지 않았다","물가는 오르되 속도가 느려졌다","물가 수준이 3% 내려갔다"],"answer":1,"explanation":"양의 상승률이 낮아진 것은 디스인플레이션이며 물가 하락과 달라요.","type":"quiz","lessonCheck":true},"before":null},{"id":880,"quiz":{"q":"식당이 가격을 바꾸려고 메뉴판과 안내물을 다시 만들었어요. 이 비용은?","options":["매몰된 대출 원금","관세","메뉴비용"],"answer":2,"explanation":"가격 조정에 필요한 인쇄와 안내 등의 비용을 뜻해요.","type":"quiz","lessonCheck":true},"before":null},{"id":249,"quiz":{"q":"빵집이 밀가루 등 중간재 40만 원으로 빵 100만 원어치를 만들었어요. 부가가치는?","options":["60만 원","100만 원","140만 원"],"answer":0,"explanation":"산출액에서 중간투입액을 빼면 새로 더한 가치가 남아요.","type":"quiz","lessonCheck":true},"before":null},{"id":482,"quiz":{"q":"현재 GDP가 늘었다는 이유만으로 잠재성장률도 반드시 올랐다고 할 수 있나요?","options":["네, 물가만 오르면 잠재성장률도 올라요","아니요, 지속 가능한 생산능력을 따로 봐야 해요","네, 두 수치는 항상 같아요"],"answer":1,"explanation":"실제 생산의 단기 반등과 노동·자본·생산성에 따른 장기 능력은 구분해요.","type":"quiz","lessonCheck":true},"before":[{"rows":[["생산성 ↑","↑","투자할 곳이 늘어 돈을 빌리려는 수요가 커져요"],["고령화·인구 감소","↓","성장이 느려지고 노후 대비 저축이 늘어요"],["세계적으로 저축 ↑","↓","빌려주려는 돈이 넘쳐요"],["정부부채 ↑","↑","정부가 돈을 많이 빌려 자금 수요가 커져요"],["안전자산 선호 ↑","↓","위험을 피해 국채로 몰려 안전한 금리가 낮아져요"]],"type":"table","title":"중립금리를 움직이는 힘","caption":"중립금리는 경기를 누르지도 띄우지도 않는 금리예요. 눈에 보이지 않아 추정만 할 수 있고, 이 힘들이 바뀌면 같은 기준금리라도 긴축인지 완화인지가 달라져요.","columns":["무슨 일이 생기면","중립금리","이유"]}]},{"id":693,"quiz":{"q":"실제 GDP가 105, 잠재 GDP가 100이에요. GDP갭의 방향은?","options":["음의 갭","갭 없음","양의 갭"],"answer":2,"explanation":"실제 생산이 잠재 수준보다 높으므로 양의 갭이에요.","type":"quiz","lessonCheck":true},"before":[{"type":"flow","steps":["실제 GDP > 잠재 GDP (플러스 GDP갭)","물건을 원하는 만큼 만들 일손·설비가 부족","임금·원자재 값 ↑","기업이 가격에 반영","물가 상승 압력 ↑"],"title":"경제가 제 실력보다 달리면 물가가 오르는 이유","caption":"마이너스 GDP갭이면 반대예요. 일손·설비가 남아 물가 상승 압력이 약해져요."}]},{"id":731,"quiz":{"q":"명목 GDP는 10% 늘었지만 생산량은 그대로이고 가격만 10% 올랐어요. 실질 GDP는?","options":["변하지 않는다","10% 증가한다","10% 감소한다"],"answer":0,"explanation":"실질 GDP는 가격 변화 효과를 제거해 생산량 변화를 측정해요.","type":"quiz","lessonCheck":true},"before":null},{"id":1119,"quiz":{"q":"가정이 먹으려고 산 빵과 빵집이 생산에 쓰려고 산 밀가루 중 최종 생산물은?","options":["둘 다 중간재","가정이 산 빵","빵집이 산 밀가루"],"answer":1,"explanation":"분류는 물건 이름보다 사용 목적에 따라 달라져요. 소비자가 먹는 빵은 최종재예요.","type":"quiz","lessonCheck":true},"before":[{"body":"밀 → 밀가루 → 빵으로 이어질 때\n마지막에 소비자가 사 먹는 빵이 최종 생산물이에요.\n밀과 밀가루 값은 이미 빵 값에 들어 있어서 따로 세지 않아요.","type":"text","title":"쉽게 설명"},{"rows":[["농부 → 밀","1,000원","1,000원"],["제분업자 → 밀가루","1,500원","500원"],["제빵업자 → 빵","2,500원","1,000원"]],"type":"table","title":"빵 한 개가 만들어지기까지","caption":"빵 값 2,500원 = 부가가치 합 1,000 + 500 + 1,000원이에요.\n세 가격을 다 더한 5,000원은 두 번 센 값이에요.","columns":["단계","판매 가격","새로 더한 가치"]},{"body":"GDP를 계산할 때 무엇을 넣고 뺄지 정하는 기준이에요.\n중간재까지 세면 나라 경제 크기가 부풀려져요.","type":"text","title":"왜 중요할까?"}]},{"id":1183,"quiz":{"q":"같은 산정 방식의 제조업 PMI가 48에서 52가 됐어요. 일반적인 해석은?","options":["생산량이 정확히 4% 증가","물가가 정확히 52% 상승","전월 대비 위축에서 확장 쪽으로 전환"],"answer":2,"explanation":"PMI의 50은 확장과 위축을 가르는 기준이며 지수 차이가 생산 증가율은 아니에요.","type":"quiz","lessonCheck":true},"before":[{"body":"원자재를 사는 담당자는 주문이 늘고 주는 걸 가장 먼저 알아요.\n그들의 답을 모아 50보다 크면 경기가 좋아지는 쪽이에요.","type":"text","title":"쉽게 설명"},{"rows":[["BSI","기업가","100"],["CSI","소비자","100"],["PMI","구매 담당자","50"]],"type":"table","title":"설문형 경기지표 기준","columns":["지표","누구에게","기준"]}]},{"id":161,"quiz":{"q":"같은 근로시간에 생산량이 100개에서 120개로 늘었어요. 노동생산성 변화는?","options":["20% 상승","20% 하락","변화 없음"],"answer":0,"explanation":"노동 투입이 같을 때 산출량이 20% 늘면 노동생산성도 20% 높아져요.","type":"quiz","lessonCheck":true},"before":null},{"id":202,"quiz":{"q":"직장을 그만둔 사람이 자신에게 맞는 새 일자리를 찾는 중이에요. 대표적인 실업 유형은?","options":["기술 변화로 인한 구조적 실업","마찰적 실업","계절적 실업"],"answer":1,"explanation":"일자리 이동 과정에서 탐색과 연결에 시간이 드는 실업이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":851,"quiz":{"q":"경제가 완전고용 상태여도 구직 중인 사람이 있을 수 있나요?","options":["아니요, 실업자가 반드시 0명이에요","아니요, 모든 성인이 반드시 일해요","네, 일자리 이동 과정의 실업은 남을 수 있어요"],"answer":2,"explanation":"완전고용은 실업률 0%나 전체 인구 취업을 의미하지 않아요.","type":"quiz","lessonCheck":true},"before":null},{"id":1164,"quiz":{"q":"자동화로 기존 직무가 줄었는데 구직자의 기술은 새 일자리와 맞지 않아요. 어떤 실업인가요?","options":["구조적 실업","마찰적 실업만으로 설명되는 실업","자발적 휴가"],"answer":0,"explanation":"산업의 요구와 노동자의 기술 사이 불일치가 원인이에요.","type":"quiz","lessonCheck":true},"before":[{"body":"무인 계산대가 늘면 계산원 일자리가 줄어요.\n경기가 좋아져도 그 일자리는 잘 돌아오지 않아요.\n새 기술을 배워야 다시 일할 수 있어요.","type":"text","title":"쉽게 설명"},{"rows":[["마찰적 실업","일자리를 찾는 과정","일자리 정보망"],["구조적 실업","산업 구조 변화","직업 재교육·훈련"],["경기적 실업","경기 침체","재정·통화정책"]],"type":"table","title":"실업의 세 가지 종류","columns":["종류","원인","대책"]}]},{"id":211,"quiz":{"q":"예금 안내에 연 4%가 적혀 있어요. 물가를 빼기 전 표시 금리는?","options":["실업률","명목금리","실질금리"],"answer":1,"explanation":"표시된 이자율은 명목금리이고, 구매력 변화를 보려면 물가도 고려해요.","type":"quiz","lessonCheck":true},"before":null},{"id":463,"quiz":{"q":"대출 금리가 COFIX에 가산금리를 더하는 방식이에요. COFIX만 오르고 나머지는 같다면 다음 조정 금리는?","options":["내린다","항상 고정된다","오른다"],"answer":2,"explanation":"약정된 금리 조정 시점에 기준 지표의 상승분이 반영될 수 있어요.","type":"quiz","lessonCheck":true},"before":null},{"id":732,"quiz":{"q":"예금의 명목금리가 4%, 물가상승률이 3%예요. 단순 차감한 실질금리는?","options":["약 1%","약 7%","약 -1%"],"answer":0,"explanation":"구매력 기준 수익률은 명목금리에서 물가상승률을 빼서 근사해요.","type":"quiz","lessonCheck":true},"before":[{"type":"flow","steps":["생산성·인구구조","잠재성장률","중립금리(R*)","중앙은행의 기준금리 결정","실질금리","소비·투자","총수요","물가·고용"],"title":"경제의 체력이 금리와 물가로 이어지는 길","caption":"중립금리는 경기를 누르지도 띄우지도 않는 금리예요. 기준금리가 이보다 높으면 경기를 식히고, 낮으면 경기를 데워요."},{"rows":[["생산성 ↑","↑","투자할 곳이 늘어 돈을 빌리려는 수요가 커져요"],["고령화·인구 감소","↓","성장이 느려지고 노후 대비 저축이 늘어요"],["세계적으로 저축 ↑","↓","빌려주려는 돈이 넘쳐요"],["정부부채 ↑","↑","정부가 돈을 많이 빌려 자금 수요가 커져요"],["안전자산 선호 ↑","↓","위험을 피해 국채로 몰려 안전한 금리가 낮아져요"]],"type":"table","title":"중립금리를 움직이는 힘","caption":"중립금리는 경기를 누르지도 띄우지도 않는 금리예요. 눈에 보이지 않아 추정만 할 수 있고, 이 힘들이 바뀌면 같은 기준금리라도 긴축인지 완화인지가 달라져요.","columns":["무슨 일이 생기면","중립금리","이유"]}]},{"id":884,"quiz":{"q":"중앙은행이 금리 인상 기조에서 인하 기조로 방향을 바꿨어요. 가까운 표현은?","options":["리디노미네이션","정책 피벗","액면분할"],"answer":1,"explanation":"피벗은 통화정책의 방향 전환을 가리키는 표현이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":1133,"quiz":{"q":"가계가 은행 밖에서 지폐와 동전을 보유해요. 이 돈은?","options":["기업의 주식","은행의 지준예치금","현금통화"],"answer":2,"explanation":"현금통화는 민간이 보유한 현금이며 예금이나 중앙은행에 둔 준비금과 구분해요.","type":"quiz","lessonCheck":true},"before":[{"body":"내 지갑 속 지폐와 동전,\n가게 금고 속 현금이 현금통화예요.\n은행 금고 안 현금은 시재금이라 따로 세요.","type":"text","title":"쉽게 설명"},{"rows":[["가계·기업","현금통화"],["은행 금고","시재금"],["둘을 합치면","화폐발행액"]],"type":"table","title":"현금은 어디에 있나","columns":["위치","이름"]}]},{"id":233,"quiz":{"q":"은행이 망한다는 소문에 예금자들이 한꺼번에 인출하려 해요. 어떤 현상인가요?","options":["뱅크런","유상증자","무역적자"],"answer":0,"explanation":"동시 인출 요구가 몰려 은행의 유동성에 압박을 주는 상황이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":348,"quiz":{"q":"기업의 투자 계획은 그대로인데 금융기관이 대출 공급을 급격히 줄였어요. 가까운 현상은?","options":["주식 액면분할","신용경색","통화 팽창"],"answer":1,"explanation":"신용 공급이 위축되어 자금 조달이 어려워진 상황이에요.","type":"quiz","lessonCheck":true},"before":[{"type":"flow","steps":["경기가 좋아 자산값 ↑","담보가치 ↑ → 은행이 대출을 더 내줌","빌린 돈으로 자산을 더 사서 자산값 ↑","충격이 오면 자산값 ↓","담보가치 ↓ → 은행이 대출 회수","빚을 갚으려 급히 팔아 자산값 더 ↓","신용경색 → 금융위기"],"title":"빚이 호황과 위기를 모두 키우는 과정","caption":"올라갈 때는 빚이 상승을 키우고, 내려갈 때는 같은 빚이 하락을 키워요. 2008년 글로벌 금융위기가 이 과정을 거쳤어요."}]},{"id":717,"quiz":{"q":"회사가 은행 대출 대신 투자자에게 회사채를 발행해 돈을 모아요. 어떤 금융인가요?","options":["은행 대출을 통한 간접금융","현물 물물교환","직접금융"],"answer":2,"explanation":"자금 수요자가 증권을 발행해 투자자로부터 직접 자금을 조달해요.","type":"quiz","lessonCheck":true},"before":null},{"id":914,"quiz":{"q":"보험사가 거액 보험금 지급 위험 일부를 다른 보험사에 넘겨요. 어떤 거래인가요?","options":["재보험","유상증자","예금보험 가입"],"answer":0,"explanation":"보험사가 인수한 위험을 다른 보험사와 나누는 보험 거래예요.","type":"quiz","lessonCheck":true},"before":null},{"id":227,"quiz":{"q":"회사가 새 채권을 발행하고 투자자가 최초로 인수했어요. 어느 시장 거래인가요?","options":["외환 현물시장","발행시장","기존 채권 유통시장"],"answer":1,"explanation":"새 증권이 처음 투자자에게 공급되어 발행자에게 자금이 들어오는 거래예요.","type":"quiz","lessonCheck":true},"before":null},{"id":350,"quiz":{"q":"회사채 금리 6%, 같은 만기의 국채 금리 3%라면 단순 금리차는?","options":["9%포인트","2%포인트","3%포인트"],"answer":2,"explanation":"신용스프레드는 비교 기준 채권과의 금리 차이로 계산해요.","type":"quiz","lessonCheck":true},"before":null},{"id":487,"quiz":{"q":"10년물 금리가 4%, 1년물 금리가 3%예요. 장기 금리에서 단기 금리를 뺀 차이는?","options":["1%포인트","-1%포인트","7%포인트"],"answer":0,"explanation":"비교하는 두 만기를 명시하고 장기 금리에서 단기 금리를 빼요.","type":"quiz","lessonCheck":true},"before":[{"item":"5050000","stat":"721Y001","type":"ecos","unit":"%","cycle":"M","title":"국고채 10년과 3년 금리","months":60,"series":[{"item":"5050000","name":"10년","stat":"721Y001"},{"item":"5020000","name":"3년","stat":"721Y001"}],"caption":"두 선 사이 간격이 장단기금리차예요. 간격이 좁아지거나 3년이 10년보다 높아지면(역전) 경기 둔화 신호로 봐요."}]},{"id":755,"quiz":{"q":"주가가 2만 원, 주당순이익이 2천 원이에요. PER은?","options":["20배","10배","0.1배"],"answer":1,"explanation":"주가를 주당순이익으로 나누면 10배예요. 낮은 수치만으로 저평가를 단정하지 않아요.","type":"quiz","lessonCheck":true},"before":[{"body":"주가: 주식 1주의 가격이에요.\n주당순이익(EPS): 회사가 1년 동안 번 돈(순이익)을 주식 수로 나눈 값이에요. 주식 1주가 1년에 번 돈이라고 보면 돼요.","type":"text","title":"미리 알아둘 말"},{"body":"PER = 주가 ÷ 주당순이익\n\n회사가 1년에 1억 원을 벌고 주식이 1만 주라면, 1주가 번 돈은 1만 원이에요.\n주가가 10만 원이면 PER은 10만 ÷ 1만 = 10배예요.\n지금 가격이면 이 회사가 10년 동안 번 돈으로 본전을 찾는다는 뜻이에요.","type":"text","title":"PER은 이렇게 계산해요"},{"rows":[["높다 (예: 30배)","버는 돈에 비해 비싸게 거래돼요","앞으로 크게 성장할 거라는 기대가 담겼을 수도 있어요"],["낮다 (예: 5배)","버는 돈에 비해 싸게 거래돼요","성장 기대가 작거나 곧 이익이 줄 거라 보는 것일 수도 있어요"]],"type":"table","title":"PER이 높을 때와 낮을 때","caption":"같은 업종끼리 비교해야 의미가 있어요. 반도체와 은행의 PER을 그대로 비교하면 안 돼요.","columns":["PER","뜻","주의할 점"]},{"type":"flow","steps":["금리 ↑","예금·채권으로도 안전하게 더 벌 수 있음","주식에 기대하는 수익률 ↑","같은 이익에 매기는 값 ↓","적정 PER ↓ (주가 부담)"],"title":"금리가 오르면 적정 PER이 낮아지는 이유","caption":"금리가 내리면 반대로 같은 이익에도 더 높은 값을 쳐줘 PER이 높아지기 쉬워요."}]},{"id":870,"quiz":{"q":"신용등급이 낮은 회사채가 더 높은 이자를 제시해요. 먼저 함께 볼 위험은?","options":["주식 분할로 주식 수가 늘어날 위험","연결 계좌의 결제 오류 위험","원리금을 못 받을 위험"],"answer":2,"explanation":"높은 금리는 채무불이행 위험에 대한 보상일 수 있어 수익률만 비교하면 안 돼요.","type":"quiz","lessonCheck":true},"before":null},{"id":899,"quiz":{"q":"주가가 급락한 뒤 잠깐 반등했어요. 이 사실만으로 장기 상승 전환을 확신할 수 있나요?","options":["아니요, 일시 반등일 수 있어요","네, 장기 상승이 보장돼요","네, 손실 가능성이 사라져요"],"answer":0,"explanation":"급락 후 짧은 반등 뒤 다시 하락하는 흐름도 있어요.","type":"quiz","lessonCheck":true},"before":null},{"id":295,"quiz":{"q":"농가가 3개월 뒤 곡물을 정한 가격에 팔기로 선물 계약을 맺었어요. 주된 목적은?","options":["현재 생산비를 없애기","미래 판매 가격 위험을 줄이기","수확량을 확정하기"],"answer":1,"explanation":"가격을 미리 정해 불확실성을 줄이지만 생산량과 비용까지 보장하지는 않아요.","type":"quiz","lessonCheck":true},"before":null},{"id":538,"quiz":{"q":"선물 포지션에 손실이 나 추가 증거금 납부를 요구받았어요. 필요한 대응은?","options":["추가 자금 요구는 무시해도 된다","최초 증거금만큼만 손실이 날 수 있다","계약 조건에 맞춰 자금을 준비하거나 포지션을 조정한다"],"answer":2,"explanation":"증거금은 거래 이행을 위한 담보이며 최대 손실을 뜻하지 않아요.","type":"quiz","lessonCheck":true},"before":null},{"id":632,"quiz":{"q":"주가 하락에 대비해 정한 가격으로 주식을 팔 권리를 샀어요. 어떤 옵션인가요?","options":["풋옵션","콜옵션","무조건 매수해야 하는 의무"],"answer":0,"explanation":"풋옵션의 매수자는 정해진 조건으로 기초자산을 팔 권리를 가져요.","type":"quiz","lessonCheck":true},"before":null},{"id":729,"quiz":{"q":"불안이 커져 투자자들이 위험자산 비중을 줄이는 분위기예요. 가까운 표현은?","options":["유상증자","리스크 오프","리스크 온"],"answer":1,"explanation":"위험을 회피하려는 흐름을 뜻하며 특정 자산의 상승을 보장하지 않아요.","type":"quiz","lessonCheck":true},"before":null},{"id":980,"quiz":{"q":"동일한 자산이 두 시장에서 서로 다른 가격으로 동시에 거래돼요. 비용이 없다면 차익거래 방향은?","options":["비싼 시장에서 사고 싼 시장에서 판다","가격 차이와 관계없이 둘 다 산다","싼 시장에서 사고 비싼 시장에서 판다"],"answer":2,"explanation":"동일 자산의 가격 차이를 이용해 매수와 매도를 결합하는 거래예요.","type":"quiz","lessonCheck":true},"before":null},{"id":666,"quiz":{"q":"수출기업이 한 달 뒤 달러를 받기로 했는데 원화가 강해졌어요. 받을 달러가 같다면 원화 환산액은?","options":["줄어든다","늘어난다","항상 같다"],"answer":0,"explanation":"달러당 원화 가격이 내려가 같은 달러를 바꿔도 받는 원화가 줄어요.","type":"quiz","lessonCheck":true},"before":null},{"id":667,"quiz":{"q":"수입기업이 미래 달러 지급액의 원화 비용을 미리 고정하려 해요. 목적에 맞는 행동은?","options":["달러 지급액을 무시하기","지급 시점에 맞춘 선물환 매입","환율 상승에 더 크게 노출되기"],"answer":1,"explanation":"선물환으로 미래 환율을 정하면 비용 불확실성을 줄일 수 있으나 유리한 환율 변화의 이점도 제한돼요.","type":"quiz","lessonCheck":true},"before":null},{"id":1212,"quiz":{"q":"고정환율 체제에서 당국이 자국 통화의 공식 가치를 높였어요. 이를 무엇이라 하나요?","options":["평가절하","통화가치 불변","평가절상"],"answer":2,"explanation":"공식 환율 조정으로 자국 통화 가치를 높이는 조치예요.","type":"quiz","lessonCheck":true},"before":[{"body":"정부가 \"오늘부터 우리 돈 1단위는 달러를 더 많이 쳐 준다\"고 발표하는 거예요.\n시장이 아니라 정부가 바꾼다는 점이 핵심이에요.","type":"text","title":"쉽게 설명"},{"rows":[["평가절상·평가절하","정부·중앙은행이 인위적으로","고정환율제"],["원화 강세·약세","시장의 수요·공급으로","변동환율제"]],"type":"table","title":"평가절상·절하 vs 강세·약세","columns":["구분","누가","제도"]}]},{"id":292,"quiz":{"q":"외국 관광객이 국내 호텔에서 숙박비를 냈어요. 국제수지상 주로 어느 항목인가요?","options":["서비스수지","상품수지","외환보유액 자체"],"answer":0,"explanation":"여행 관련 서비스 제공에 따른 대가이므로 상품 수출과 구분해요.","type":"quiz","lessonCheck":true},"before":null},{"id":781,"quiz":{"q":"같은 시간에 A국은 옷 10벌, B국은 6벌을 만들어요. 옷 생산에서 A국이 가진 것은?","options":["반드시 무역적자","절대우위","반드시 비교우위"],"answer":1,"explanation":"같은 투입으로 더 많이 생산하므로 절대우위지만 비교우위에는 다른 상품의 기회비용도 필요해요.","type":"quiz","lessonCheck":true},"before":null},{"id":837,"quiz":{"q":"불황으로 수출도 줄었지만 수입이 더 크게 줄어 무역흑자가 났어요. 가까운 표현은?","options":["수출 호황 확정","교역 중단","불황형 흑자"],"answer":2,"explanation":"흑자만으로 경기가 좋다고 판단할 수 없는 사례예요.","type":"quiz","lessonCheck":true},"before":null},{"id":1198,"quiz":{"q":"관세 대신 까다로운 수입 허가와 기술 요건으로 수입이 어려워졌어요. 이런 장벽은?","options":["비관세장벽","수출 보조금","환율 자유화"],"answer":0,"explanation":"세금 형태가 아닌 규정과 절차도 무역을 제한할 수 있어요.","type":"quiz","lessonCheck":true},"before":[{"body":"세금을 매기지 않아도 수입을 막을 방법은 많아요.\n수입량을 정하거나 검사를 까다롭게 하는 식이에요.","type":"text","title":"쉽게 설명"},{"rows":[["관세","가격에 세금","정부 (관세 수입)"],["수입할당제","수입량을 정함","수입 면허를 받은 수입업자"],["수출자율규제","수출국이 스스로 줄임","수출국 수출업자"]],"type":"table","title":"수단별로 초과이윤이 가는 곳","columns":["수단","방식","가운데 몫"]}]},{"id":190,"quiz":{"q":"세계 경기가 둔화하는데 한 나라 경기는 다른 방향으로 움직여요. 가까운 표현은?","options":["액면분할","디커플링","커플링"],"answer":1,"explanation":"같이 움직이던 경제 흐름이 서로 떨어져 움직이는 현상이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":302,"quiz":{"q":"국가 사이 무역 규범과 무역 분쟁을 다루는 국제기구를 찾고 있어요. 해당 기구는?","options":["IMF","WHO","WTO"],"answer":2,"explanation":"WTO는 국제 무역 규범과 분쟁 해결을 다루며 통화 안정 기구와 구분돼요.","type":"quiz","lessonCheck":true},"before":null},{"id":433,"quiz":{"q":"유로 사용 지역의 통화정책을 분석하려 해요. 확인할 중앙은행은?","options":["유럽중앙은행","미국 연방준비제도","일본은행"],"answer":0,"explanation":"ECB는 유로 지역 통화정책의 중심 기관이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":605,"quiz":{"q":"기업들이 국제 공급망을 줄이고 생산을 자국이나 가까운 국가로 돌려요. 연결되는 흐름은?","options":["완전 자유무역의 완성","탈세계화","국제 분업의 무조건 확대"],"answer":1,"explanation":"국경을 넘는 연결과 의존을 줄이려는 움직임으로 볼 수 있어요.","type":"quiz","lessonCheck":true},"before":null},{"id":728,"quiz":{"q":"두 나라의 경기가 비슷한 방향으로 함께 움직이는 경향이 커졌어요. 가까운 표현은?","options":["디커플링","디플레이션","커플링"],"answer":2,"explanation":"경제 변수나 시장의 동조화가 커진 상황이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":276,"quiz":{"q":"가입자들이 보험료를 내고 질병이나 노후 같은 위험에 대비하는 공적 제도예요. 가까운 유형은?","options":["사회보험","주식 배당","개인 간 증여"],"answer":0,"explanation":"사회적 위험을 공동으로 분담하는 보험 방식의 사회보장제도예요.","type":"quiz","lessonCheck":true},"before":null},{"id":817,"quiz":{"q":"공공사업의 현재가치 기준 편익이 120억 원, 비용이 100억 원이에요. 순편익은?","options":["-20억 원","20억 원","220억 원"],"answer":1,"explanation":"편익에서 비용을 빼요. 실제 판단에서는 분배와 불확실성도 함께 검토해요.","type":"quiz","lessonCheck":true},"before":null},{"id":908,"quiz":{"q":"같은 소비세 10만 원을 낼 때 소득 100만 원인 사람의 부담 비중은 1천만 원인 사람보다?","options":["낮다","같다","높다"],"answer":2,"explanation":"같은 세액이라도 저소득자의 소득 대비 부담이 더 커 역진성이 나타나요.","type":"quiz","lessonCheck":true},"before":null},{"id":965,"quiz":{"q":"법에 정한 날짜가 지나면 특별한 연장 없이 지원 제도가 종료돼요. 이런 장치는?","options":["일몰제","영구 보장","소급 과세"],"answer":0,"explanation":"기한을 정해 제도의 효력을 끝내고 존속 필요성을 다시 검토하게 해요.","type":"quiz","lessonCheck":true},"before":null},{"id":1154,"quiz":{"q":"소득이 높은 구간에 더 높은 세율을 적용해요. 세율 구조는?","options":["소득과 무관한 동일 세액","누진세","정액세"],"answer":1,"explanation":"과세표준이 커질수록 적용 세율이 높아지는 구조예요.","type":"quiz","lessonCheck":true},"before":[{"body":"많이 버는 사람은 더 높은 비율로 세금을 내요.\n그래서 경기가 좋을 땐 세금이 확 늘고\n나쁠 땐 확 줄어 경기 출렁임을 줄여 줘요.","type":"text","title":"쉽게 설명"},{"rows":[["호황","소득보다 더 빨리 늘어요","과열 진정"],["불황","소득보다 더 빨리 줄어요","소비 지탱"]],"type":"table","title":"경기에 따라 저절로","columns":["경기","세금","효과"]}]},{"id":429,"quiz":{"q":"자산 가치는 충분하지만 오늘 갚을 현금을 제때 마련하지 못해요. 가장 직접적인 위험은?","options":["환율 상승만의 위험","생산량 과잉","유동성리스크"],"answer":2,"explanation":"지급할 시점에 필요한 자금을 구하지 못하는 위험이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":900,"quiz":{"q":"오랫동안 경고된 큰 부채 위험을 방치하다 문제가 터졌어요. 가까운 비유는?","options":["회색 코뿔소","전혀 예상 못 한 블랙 스완","완전한 무위험"],"answer":0,"explanation":"발생 가능성과 충격이 큰데도 간과하는 위험을 가리켜요.","type":"quiz","lessonCheck":true},"before":null},{"id":552,"quiz":{"q":"요금 청구기관이 보낸 고지서의 납부 정보를 이용해 은행에서 요금을 냈어요. 가까운 방식은?","options":["외환 선물거래","지로 납부","주식 청약"],"answer":1,"explanation":"지로는 공과금 등 대량 수납에 쓰는 지급 방식이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":660,"quiz":{"q":"지폐를 기울이니 무늬와 색이 달라져 진위를 확인하는 데 도움을 줘요. 이런 장치는?","options":["이자 쿠폰","신용평가등급","홀로그램"],"answer":2,"explanation":"각도에 따라 다르게 보이는 광학 효과를 위조 방지에 활용해요.","type":"quiz","lessonCheck":true},"before":null},{"id":706,"quiz":{"q":"휴대전화를 단말기에 가까이 대고 짧은 거리에서 정보를 주고받아 결제했어요. 관련 기술은?","options":["NFC","위성항법만으로 하는 결제","장거리 라디오 방송"],"answer":0,"explanation":"NFC는 가까운 거리에서 기기 간 데이터를 주고받는 무선통신 기술이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":204,"quiz":{"q":"판매자에게 바로 돈을 주지 않고 구매 확인 뒤 중개자가 대금을 지급해요. 어떤 장치인가요?","options":["신용 창조","에스크로","공매도"],"answer":1,"explanation":"제3자가 대금을 보관했다가 조건 충족 후 지급해 거래 위험을 줄여요.","type":"quiz","lessonCheck":true},"before":null},{"id":336,"quiz":{"q":"어떤 코인이 1달러 가치 유지를 목표로 해요. 이용 전 적절한 판단은?","options":["언제나 법적으로 1달러가 보장된다","가격이 하락할 수 없다","목표와 실제 가격 안정성은 다를 수 있다"],"answer":2,"explanation":"가치 고정 목표가 있어도 준비자산이나 구조에 따라 가격 이탈 위험이 있어요.","type":"quiz","lessonCheck":true},"before":null},{"id":501,"quiz":{"q":"온라인 계약서가 누가 작성했는지 확인하고 변경 여부를 검증하려 해요. 관련 수단은?","options":["전자서명","환율 고시","현금 인출"],"answer":0,"explanation":"전자서명은 전자문서의 서명자 확인 등에 쓰이며 구체적인 검증 방식은 기술에 따라 달라요.","type":"quiz","lessonCheck":true},"before":null},{"id":603,"quiz":{"q":"기업의 배출량이 보유 배출권보다 많아 추가 배출권을 구입해요. 거래 대상은?","options":["무제한 오염 허가","정해진 양의 온실가스를 배출할 수 있는 권리","기업 주주총회 의결권"],"answer":1,"explanation":"배출권은 제도에서 허용한 배출량 단위의 권리이며 무제한 배출을 허용하지 않아요.","type":"quiz","lessonCheck":true},"before":null},{"id":986,"quiz":{"q":"법에서 금지한 사항 외에는 사업을 허용하는 규제 방식을 택했어요. 유형은?","options":["허용 목록에 든 것만 가능한 규제","모든 사업 금지","네거티브 규제"],"answer":2,"explanation":"금지할 대상을 열거하는 방식으로, 허용 대상만 나열하는 방식과 달라요.","type":"quiz","lessonCheck":true},"before":null},{"id":427,"quiz":{"q":"유동자산 200억 원, 유동부채 100억 원이면 유동비율은?","options":["200%","50%","100%"],"answer":0,"explanation":"유동자산을 유동부채로 나눈 뒤 100을 곱해요. 자산의 실제 환금성도 별도로 봐야 해요.","type":"quiz","lessonCheck":true},"before":null},{"id":445,"quiz":{"q":"영업이익 60억 원, 이자비용 20억 원이면 이자보상배율은?","options":["80배","3배","0.33배"],"answer":1,"explanation":"영업이익을 이자비용으로 나누어 이자 지급 부담을 살펴요.","type":"quiz","lessonCheck":true},"before":null},{"id":592,"quiz":{"q":"경쟁 업체들이 서로 가격을 낮추지 않기로 합의했어요. 어떤 행위인가요?","options":["독립적인 가격경쟁","소비자 간 공동구매","카르텔"],"answer":2,"explanation":"경쟁자끼리 가격 등을 합의해 경쟁을 제한하는 담합의 사례예요.","type":"quiz","lessonCheck":true},"before":null},{"id":702,"quiz":{"q":"회사가 경쟁사의 경영권을 확보하려 지분을 인수했어요. 가까운 거래는?","options":["M&A","일반 상품 구매","국채 상환"],"answer":0,"explanation":"기업의 합병과 인수는 사업이나 경영권의 결합을 목적으로 해요.","type":"quiz","lessonCheck":true},"before":null},{"id":831,"quiz":{"q":"제품을 한 개 더 팔자 총수입이 8천 원 늘었어요. 이 추가 수입은?","options":["매몰비용","한계수입","평균고정비용"],"answer":1,"explanation":"판매량 한 단위 증가에 따른 총수입의 증가분이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":871,"quiz":{"q":"회사를 정리해 자산을 각각 팔 경우 회수할 수 있는 금액을 추정해요. 평가하는 것은?","options":["계속 영업할 때의 가치만","주식의 액면가 합계","청산가치"],"answer":2,"explanation":"사업을 계속하는 가치와 달리 자산을 처분하는 상황을 기준으로 해요.","type":"quiz","lessonCheck":true},"before":null},{"id":933,"quiz":{"q":"쇼핑몰에서 인기 상품 몇 개보다 수많은 비인기 상품의 매출 합계가 크게 나타나요. 가까운 현상은?","options":["롱테일 법칙","독점 가격 결정","은행 신용 창조"],"answer":0,"explanation":"각각은 적게 팔려도 다양한 상품의 누적 수요가 중요해질 수 있어요.","type":"quiz","lessonCheck":true},"before":null},{"id":976,"quiz":{"q":"누적 손실로 회사 자본총계가 자본금보다 작아졌어요. 어떤 상태인가요?","options":["액면분할","자본잠식","무조건 현금 과잉"],"answer":1,"explanation":"손실이 쌓여 납입된 자본금까지 줄어든 상태이며 현금 잔액과는 다른 개념이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":1045,"quiz":{"q":"총비용 100만 원으로 200개를 생산했어요. 개당 평균비용은?","options":["2천 원","20만 원","5천 원"],"answer":2,"explanation":"총비용을 생산량으로 나누면 단위당 평균비용이 나와요.","type":"quiz","lessonCheck":true},"before":[{"body":"빵 3개를 만드는 데 24원이 들면 한 개당 8원이에요.\n이게 평균비용이에요.","type":"text","title":"쉽게 설명"},{"rows":[["1개","7원","7원","7원"],["2개","15원","7.5원","8원"],["3개","24원","8원","9원"]],"type":"table","title":"빵 생산 비용","columns":["빵","총비용","평균비용","한계비용"]},{"body":"새 과목 점수가 평균보다 높으면 평균이 올라요.\nMC가 AC보다 크면 AC가 오르고, 작으면 AC가 내려요.","type":"text","title":"평균과 한계의 관계"}]},{"id":1075,"quiz":{"q":"생산을 잠시 멈춰도 계약상 매장 월세를 그대로 내야 해요. 단기적으로 어떤 비용인가요?","options":["고정비용","생산량에 비례하는 가변비용","한계수입"],"answer":0,"explanation":"해당 기간 생산량과 무관하게 발생하는 비용이에요.","type":"quiz","lessonCheck":true},"before":[{"body":"빵을 200개 굽든 300개 굽든 한 달 임대료 100만 원은 그대로예요.\n이렇게 안 만들어도 나가는 돈이 고정비용이에요.","type":"text","title":"쉽게 설명"},{"rows":[["0개","100만","0","100만"],["200개","100만","20만","120만"],["500개","100만","50만","150만"],["1,000개","100만","100만","200만"]],"type":"table","title":"빵집 총비용 (임대료 100만 원, 재료비 개당 1,000원)","caption":"생산량이 0이어도 단기에는 100만 원이 나가요.","columns":["생산량","고정비용","가변비용","총비용"]},{"rows":[["기준","생산량과 상관없음","되돌릴 수 없음"],["예시","다음 달 임대료","이미 낸 인테리어비"]],"type":"table","title":"고정비용과 매몰비용","columns":["구분","고정비용","매몰비용"]}]},{"id":1095,"quiz":{"q":"카페가 가격 할인 대신 서비스와 공간을 개선해 고객을 모아요. 어떤 경쟁인가요?","options":["생산 중단","비가격 경쟁","가격 인하 경쟁"],"answer":1,"explanation":"가격 외의 품질과 경험으로 경쟁하는 방식이에요.","type":"quiz","lessonCheck":true},"before":[{"body":"통신사들이 요금은 비슷하게 두고 멤버십 혜택과 광고로 경쟁하는 모습이 비가격 경쟁이에요.","type":"text","title":"쉽게 설명"},{"rows":[["완전경쟁","거의 없음 (상품이 같음)"],["독점적 경쟁","많음 (인테리어, 서비스)"],["과점","매우 치열 (광고, 디자인)"]],"type":"table","title":"시장별 비가격 경쟁","columns":["시장","비가격 경쟁"]}]},{"id":1033,"quiz":{"q":"가격이 1% 오르면 수요량이 약 1% 줄어드는 구간이에요. 탄력성 절댓값은?","options":["0","무한대","1"],"answer":2,"explanation":"두 변화율의 크기가 같으므로 단위탄력적이에요.","type":"quiz","lessonCheck":true},"before":[{"body":"값이 10% 오르면 사려는 양도 정확히 10% 줄어요.\n그래서 매출은 그대로예요.","type":"text","title":"쉽게 설명"},{"rows":[["0","완전비탄력적","수직선"],["0~1","비탄력적","가파름"],["1","단위탄력적","-"],["1 초과","탄력적","완만함"],["무한대","완전탄력적","수평선"]],"type":"table","title":"탄력성 다섯 구간","columns":["탄력성 값","이름","수요곡선"]}]},{"id":1049,"quiz":{"q":"곡물을 더 생산할수록 포기해야 할 옷의 양이 점점 많아져요. 나타나는 원리는?","options":["기회비용 체증","기회비용 소멸","모든 자원의 생산성 동일"],"answer":0,"explanation":"다른 용도에 적합한 자원까지 옮기면서 추가 생산의 기회비용이 커져요.","type":"quiz","lessonCheck":true},"before":[{"body":"자동차를 더 만들려고 옷 공장 사람을 옮기면\n처음엔 차를 잘 만드는 사람부터, 나중엔 옷을 잘 만드는 사람까지 옮겨야 해요.\n그래서 포기하는 옷이 점점 많아져요.","type":"text","title":"쉽게 설명"},{"rows":[["0대","100벌","-"],["1대","96벌","4벌"],["2대","84벌","12벌"],["3대","64벌","20벌"],["4대","36벌","28벌"]],"type":"table","title":"옷 = 100 - 4 × 자동차^2 예시","columns":["자동차","옷","1대 더 만들 때 포기하는 옷"]},{"body":"생산가능곡선이 우하향하는 건 희소성 때문이에요.\n오목한 건 기회비용 체증 때문이에요.","type":"text","title":"외우는 요령"}]},{"id":1068,"quiz":{"q":"짧은 기간에는 공장 건물 크기를 바꿀 수 없지만 근무 시간은 늘릴 수 있어요. 건물은?","options":["최종 소비재","고정 생산요소","가변 생산요소"],"answer":1,"explanation":"분석 기간 안에 투입량을 조절할 수 없는 요소를 고정 요소라고 해요.","type":"quiz","lessonCheck":true},"before":[{"body":"1만 평 논에 일할 사람은 금방 더 데려올 수 있어요.\n하지만 논 자체는 당장 늘릴 수 없어요.\n이 논처럼 당장 못 바꾸는 요소가 고정 생산요소예요.","type":"text","title":"쉽게 설명"},{"rows":[["고정 생산요소","당장은 바꿀 수 없음","논, 공장, 기계"],["가변 생산요소","생산량에 맞춰 바꿀 수 있음","일하는 사람, 원재료"]],"type":"table","title":"고정 생산요소와 가변 생산요소","caption":"단기 모형에서는 보통 자본을 고정, 노동을 가변으로 둬요.","columns":["구분","뜻","예시"]}]},{"id":1073,"quiz":{"q":"노동자 4명이 100개, 5명이 118개를 만들어요. 다섯 번째 노동자의 한계생산은?","options":["118개","약 23.6개","18개"],"answer":2,"explanation":"노동 투입 한 단위 증가에 따른 산출 증가분 118-100을 계산해요.","type":"quiz","lessonCheck":true},"before":[{"body":"\"한 명 더 뽑으면 몇 개 더 나오나\"가 한계생산이에요.\n좁은 주방에 요리사를 계속 늘리면 서로 부딪혀 추가로 나오는 요리가 줄어요.","type":"text","title":"쉽게 설명"},{"rows":[["3명","4가마","9가마","3"],["4명","5가마","14가마","3.5"],["5명","4가마","18가마","3.6"],["6명","3가마","21가마","3.5"],["9명","0가마","24가마","약 2.7"],["10명","-1가마","23가마","2.3"]],"type":"table","title":"논농사로 보는 생산 (논 1만 평 고정)","caption":"5명째부터 한계생산이 줄어요.\n그래도 0보다 크면 총생산은 계속 늘어요.","columns":["노동","한계생산","총생산","평균생산"]},{"body":"기업이 사람을 더 뽑을지 판단하는 기준이 한계생산이에요.\n한계생산이 줄면 하나 더 만드는 비용인 한계비용이 커져요.","type":"text","title":"왜 중요할까?"}]},{"id":1079,"quiz":{"q":"총고정비용은 100만 원으로 같고 생산량이 100개에서 200개로 늘어요. 평균고정비용은?","options":["1만 원에서 5천 원으로 감소","1만 원에서 2만 원으로 증가","100만 원으로 유지"],"answer":0,"explanation":"같은 고정비용을 더 많은 제품에 나누어 부담해요.","type":"quiz","lessonCheck":true},"before":[{"body":"임대료 100만 원을 커피 1,000잔으로 나누면 한 잔에 1,000원이에요.\n4,000잔을 팔면 250원으로 줄어요.","type":"text","title":"쉽게 설명"},{"x":["500잔","1,000잔","2,000잔","4,000잔"],"type":"line","unit":"원","title":"판매량별 잔당 비용 (임대료 100만 원, 재료비 잔당 500원)","series":[{"name":"평균고정비용","values":[2000,1000,500,250]},{"name":"평균가변비용","values":[500,500,500,500]},{"name":"평균비용","values":[2500,1500,1000,750]}],"caption":"평균고정비용은 U자가 아니라 계속 줄기만 해요."}]},{"id":1092,"quiz":{"q":"주도 기업이 가격을 바꾸자 다른 업체들이 비슷하게 따라가요. 가까운 현상은?","options":["물물교환","가격 선도","완전한 가격 수용"],"answer":1,"explanation":"한 기업의 가격 결정이 다른 기업의 가격 조정에 기준이 되는 상황이에요.","type":"quiz","lessonCheck":true},"before":[{"body":"업계 1위가 값을 올리면 며칠 뒤 다른 회사들도 비슷하게 올려요.\n앞장선 회사를 따라가는 모습이라 가격 선도라고 해요.","type":"text","title":"쉽게 설명"},{"type":"flow","steps":["선도 기업이 가격 인상","다른 기업이 반응을 살핌","비슷한 폭으로 따라 인상","시장 가격이 함께 오름"],"title":"가격 선도가 일어나는 흐름"}]},{"id":1105,"quiz":{"q":"한 사람의 만족이 높아지고 다른 누구의 만족도 낮아지지 않았어요. 이 변화는?","options":["반드시 완전한 평등","반드시 총생산 감소","파레토 개선"],"answer":2,"explanation":"누군가 더 나아지면서 아무도 더 나빠지지 않는 변화예요. 평등을 보장하는 개념은 아니에요.","type":"quiz","lessonCheck":true},"before":[{"body":"안 쓰는 물건을 필요한 사람에게 팔면 파는 사람도 사는 사람도 좋아져요.\n아무도 손해 보지 않았으니 파레토 개선이에요.","type":"text","title":"쉽게 설명"},{"rows":[["갑","100","100"],["을","92","92"],["병","80","85"]],"type":"table","title":"세 사람의 효용 변화","caption":"병만 좋아지고 아무도 손해 보지 않아 A → B는 파레토 개선이에요.\n병이 75로 줄었다면 파레토 개선이 아니에요.","columns":["사람","상태 A","상태 B"]}]},{"id":1161,"quiz":{"q":"미래 소득은 충분할 듯하지만 지금 돈이 없고 빌릴 수도 없어 소비를 못 해요. 어떤 제약인가요?","options":["유동성 제약","소비 욕구 소멸","공급 독점"],"answer":0,"explanation":"원하는 시점에 쓸 자금을 확보하지 못해 현재 지출이 제한돼요.","type":"quiz","lessonCheck":true},"before":[{"body":"내년에 월급이 오를 걸 알아도\n지금 은행이 돈을 안 빌려주면 지금 쓸 수 없어요.\n그래서 돈이 생기면 바로 써요.","type":"text","title":"쉽게 설명"},{"rows":[["유동성 제약 없음","미래 세금을 생각해 일부 저축"],["유동성 제약 있음","대부분 바로 소비"]],"type":"table","title":"감세 100만 원을 받으면","columns":["가계","행동"]}]},{"id":1171,"quiz":{"q":"높은 물가상승으로 현금을 적게 보유하려고 은행을 더 자주 오가요. 이런 번거로움의 비용은?","options":["관세","구두창 비용","메뉴비용"],"answer":1,"explanation":"현금 보유를 줄이기 위해 드는 시간과 거래 노력의 비용을 뜻해요.","type":"quiz","lessonCheck":true},"before":[{"body":"물가가 빨리 오르면 지갑 속 현금 가치가 금방 줄어요.\n그래서 조금씩 자주 찾아 쓰느라 시간과 발품이 들어요.\n이 수고가 구두창 비용이에요.","type":"text","title":"쉽게 설명"},{"rows":[["구두창 비용","현금 관리에 드는 수고"],["메뉴비용","가격표를 바꾸는 비용"],["인플레이션 조세","화폐 구매력 감소"]],"type":"table","title":"인플레이션의 비용 비교","columns":["비용","뜻"]}]},{"id":138,"quiz":{"q":"기업들의 생산과 주문 전망 응답을 종합해 경기에 대한 심리를 살펴요. 가까운 지표는?","options":["소비자물가지수","원화 현금 발행액","기업심리지수"],"answer":2,"explanation":"기업의 체감과 전망을 조사한 심리 지표이며 실제 생산 증가율과 같지는 않아요.","type":"quiz","lessonCheck":true},"before":null},{"id":163,"quiz":{"q":"생산 증가와 함께 환경 훼손 비용도 반영해 경제 성과를 보려 해요. 연결되는 개념은?","options":["녹색GDP","명목환율","주가수익비율"],"answer":0,"explanation":"환경 비용 등을 조정해 기존 생산 지표의 한계를 보완하려는 개념이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":287,"quiz":{"q":"판매보다 생산이 많아 창고의 완제품이 늘었어요. 직접 연결되는 통계는?","options":["원화 실효환율","생산자제품재고지수","실업률"],"answer":1,"explanation":"생산자가 보유한 제품 재고의 변화를 보는 지표예요.","type":"quiz","lessonCheck":true},"before":null},{"id":470,"quiz":{"q":"같은 양의 자본을 투입해 더 많은 부가가치를 만들었어요. 개선된 것은?","options":["법정 세율","환율 수준","자본생산성"],"answer":2,"explanation":"자본 투입 대비 산출이나 부가가치가 커진 상황이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":531,"quiz":{"q":"식당이 음식을 만들려고 식재료를 사서 사용했어요. 국민계정에서 이 투입은?","options":["중간소비","가계 최종소비","고정자본형성"],"answer":0,"explanation":"생산 과정에서 소비되는 재화와 서비스의 가치예요.","type":"quiz","lessonCheck":true},"before":null},{"id":639,"quiz":{"q":"회사가 노동의 대가로 임금과 사용자 부담 사회보험료를 지급해요. 국민계정의 관련 항목은?","options":["토지 매각대금","피용자보수","배당소득"],"answer":1,"explanation":"피용자보수는 임금뿐 아니라 고용주가 부담하는 사회기여금 등도 포함해요.","type":"quiz","lessonCheck":true},"before":null},{"id":1122,"quiz":{"q":"판매 부진으로 설비가 놀고 있을 때 지출 증가가 생산을 늘린다고 설명해요. 가까운 관점은?","options":["수요는 생산에 아무 영향도 없다는 관점","가격 수준만으로 모든 생산을 설명하는 관점","유효수요를 중시하는 케인스 관점"],"answer":2,"explanation":"유휴 자원이 있는 상황에서 총수요가 실제 생산과 고용에 영향을 준다고 봐요.","type":"quiz","lessonCheck":true},"before":[{"body":"1,000개를 만들어도 800개만 팔리면\n결국 800개만 만들게 돼요.\n케인스는 \"수요가 생산을 정한다\"고 봤어요.","type":"text","title":"쉽게 설명"},{"rows":[["가격·임금","빠르게 움직임","잘 안 움직임"],["국민소득을 정하는 것","공급","수요(유효수요)"],["실업","자발적 실업만","비자발적 실업도 있음"],["정부 역할","작을수록 좋음","불황엔 적극적으로"]],"type":"table","title":"고전학파 vs 케인스","columns":["구분","고전학파","케인스"]},{"body":"불황 때 정부가 재정지출을 늘리는 이유가 이 이론에서 나와요.\n오늘날 경기부양책의 출발점이에요.","type":"text","title":"왜 중요할까?"}]},{"id":1126,"quiz":{"q":"현재 소득이 0이어도 저축을 꺼내 최소한의 식비를 써요. 단순 소비함수에서 이 부분은?","options":["기본소비","유발소비만","기업 투자"],"answer":0,"explanation":"소득과 무관하게 발생하는 소비를 기본소비 또는 독립소비라고 해요.","type":"quiz","lessonCheck":true},"before":[{"body":"월급이 끊겨도 밥은 먹고 월세는 내야 해요.\n이렇게 소득과 상관없이 나가는 소비가 기본소비예요.","type":"text","title":"쉽게 설명"},{"rows":[["0","50"],["100","130"],["200","210"]],"type":"table","title":"소비함수 C = 50 + 0.8Y","caption":"50이 기본소비, 0.8이 한계소비성향이에요.","columns":["가처분소득","소비"]}]},{"id":1177,"quiz":{"q":"경제성장을 노동 증가, 자본 증가, 생산성 향상으로 나누어 설명해요. 어떤 분석인가요?","options":["물가지수 품목 교체","성장회계","복식부기만의 자산 기록"],"answer":1,"explanation":"성장률에 각 생산요소와 생산성이 얼마나 기여했는지 분해하는 분석이에요.","type":"quiz","lessonCheck":true},"before":[{"body":"성장률 5%가 어디서 왔는지 영수증처럼 나눠 보는 거예요.\n사람이 늘어서, 기계가 늘어서, 기술이 좋아져서 각각 얼마인지 따져요.","type":"text","title":"쉽게 설명"},{"rows":[["노동 투입 증가","1%p"],["자본 투입 증가","2%p"],["나머지 (솔로 잔차)","2%p"]],"type":"table","title":"성장률 5%를 쪼개면 (예시)","caption":"노동과 자본으로 설명 못 하는 나머지가 기술·제도의 기여예요.","columns":["요인","기여"]}]},{"id":168,"quiz":{"q":"근로자 보수 총액은 10% 늘고 생산량은 그대로예요. 단위노동비용은?","options":["10% 감소","변화 없음","10% 증가"],"answer":2,"explanation":"산출 한 단위에 들어가는 노동비용이 같은 비율로 높아져요.","type":"quiz","lessonCheck":true},"before":null},{"id":1104,"quiz":{"q":"소득 하위 40%의 소득을 상위 20% 소득으로 나눈 비율이 높아졌어요. 다른 조건이 같다면?","options":["분배가 더 균등해진 방향","분배가 더 불균등해진 방향","실업자가 반드시 감소"],"answer":0,"explanation":"10분위분배율이 높을수록 하위 집단의 상대적 소득 몫이 커졌음을 뜻해요.","type":"quiz","lessonCheck":true},"before":[{"body":"모두 똑같이 벌면 하위 40%가 40%, 상위 20%가 20%를 가져 값이 2예요.\n상위 20%가 다 가지면 0이 돼요.","type":"text","title":"쉽게 설명"},{"rows":[["지니계수","로렌츠 곡선 면적 비율","0 ~ 1","작아짐"],["10분위분배율","하위 40% ÷ 상위 20%","0 ~ 2","커짐"],["소득5분위배율","상위 20% ÷ 하위 20%","1 이상","작아짐"]],"type":"table","title":"소득분배 지표 비교","caption":"세 지표 중 10분위분배율만 클수록 평등해요.","columns":["지표","계산","범위","평등할수록"]},{"body":"시험에서는 \"어떤 지표가 클수록 평등한가\"를 가장 자주 물어요.\n지표마다 방향이 달라 여러 지표를 함께 봐야 해요.","type":"text","title":"왜 중요할까?"}]},{"id":274,"quiz":{"q":"중앙은행이 향후 금리 결정의 조건과 방향을 미리 설명했어요. 어떤 수단인가요?","options":["기업 배당 공시","포워드 가이던스","정부 예산 편성"],"answer":1,"explanation":"앞으로의 정책에 대한 소통으로 시장의 기대 형성에 영향을 줘요.","type":"quiz","lessonCheck":true},"before":null},{"id":584,"quiz":{"q":"은행의 일시적 유동성 부족이 시스템 위기로 번지지 않도록 중앙은행이 긴급 자금을 공급해요. 역할은?","options":["기업 주주총회","조세 징수자","최종대부자"],"answer":2,"explanation":"중앙은행은 금융시스템 안정을 위해 최후의 유동성 공급자 역할을 할 수 있어요.","type":"quiz","lessonCheck":true},"before":null},{"id":616,"quiz":{"q":"명목 GDP가 500, 통화량이 100이라면 같은 기간 통화유통속도는?","options":["5","0.2","600"],"answer":0,"explanation":"명목 GDP를 통화량으로 나누어 계산해요.","type":"quiz","lessonCheck":true},"before":null},{"id":1132,"quiz":{"q":"은행이 지급준비를 위해 중앙은행 계좌에 예치한 돈이에요. 해당 항목은?","options":["기업의 매출채권","지준예치금","가계 보유 현금"],"answer":1,"explanation":"은행이 중앙은행에 보유하는 준비금으로 민간 예금과 구분돼요.","type":"quiz","lessonCheck":true},"before":[{"body":"은행도 한국은행에 통장이 있어요.\n그 통장에 넣어 둔 준비금이 지준예치금이에요.","type":"text","title":"쉽게 설명"},{"rows":[["지급준비금 = 시재금 + 지준예치금","은행이 남겨 둔 돈 전체"],["본원통화 = 화폐발행액 + 지준예치금","한국은행이 공급한 돈 전체"]],"type":"table","title":"한 줄 공식","columns":["식","뜻"]}]},{"id":1135,"quiz":{"q":"은행의 실제 준비금은 120억 원, 법정 필요액은 100억 원이에요. 초과준비금은?","options":["100억 원","220억 원","20억 원"],"answer":2,"explanation":"법정 필요액을 넘겨 보유한 준비금 120-100을 계산해요.","type":"quiz","lessonCheck":true},"before":[{"body":"꼭 남길 돈보다 더 남겨 둔 여유분이에요.\n은행이 \"지금은 빌려주기 불안하다\"고 느끼면 늘어나요.","type":"text","title":"쉽게 설명"},{"rows":[["법정지급준비금","법으로 꼭 남겨야 하는 돈"],["초과지급준비금","그보다 더 남긴 돈"]],"type":"table","title":"실제 지급준비금의 구성","caption":"실제 지급준비금 = 법정 + 초과예요.","columns":["구분","뜻"]}]},{"id":1146,"quiz":{"q":"명목통화량은 그대로인데 물가 수준이 두 배가 됐어요. 실질통화량은?","options":["절반이 된다","두 배가 된다","그대로다"],"answer":0,"explanation":"실질통화량은 명목통화량을 물가 수준으로 나눈 값이에요.","type":"quiz","lessonCheck":true},"before":[{"body":"통장에 100만 원이 그대로 있어도\n물가가 2배가 되면 살 수 있는 건 절반이에요.\n이 \"실제 구매력 기준\" 돈의 양이 실질통화량이에요.","type":"text","title":"쉽게 설명"},{"rows":[["100","100"],["125","80"],["80","125"]],"type":"table","title":"명목 100, 물가가 바뀌면","columns":["물가","실질통화량"]}]},{"id":1157,"quiz":{"q":"경기 악화를 파악한 뒤 정책 결정까지 몇 달이 걸렸어요. 어떤 시차인가요?","options":["결제 시차","내부시차","외부시차"],"answer":1,"explanation":"문제 인식에서 정책 결정과 실행까지 걸리는 시간이 내부시차예요.","type":"quiz","lessonCheck":true},"before":[{"body":"아픈 걸 알아채고 병원에 가서 처방받기까지 걸리는 시간이에요.\n약을 먹은 뒤 낫기까지는 외부시차예요.","type":"text","title":"쉽게 설명"},{"rows":[["내부시차","알아채고 실행하기까지","재정정책"],["외부시차","실행 후 효과가 나타나기까지","통화정책"]],"type":"table","title":"내부시차와 외부시차","columns":["시차","뜻","긴 쪽"]}]},{"id":121,"quiz":{"q":"기업이 은행 대출을 줄이고 시장에서 직접 채권을 발행해요. 연결되는 흐름은?","options":["은행 대출 의존 증가","현금 사용 금지","금융의 탈중개화"],"answer":2,"explanation":"은행의 자금 중개를 거치지 않는 직접 자금 조달이 확대되는 흐름이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":389,"quiz":{"q":"고객의 예금을 받아 자금을 조달하는 금융기관을 분류해요. 기준에 맞는 분류는?","options":["예금취급기관","비금융 제조기업","일반 소매점"],"answer":0,"explanation":"예금을 수신하는 기능을 기준으로 금융기관을 묶은 분류예요.","type":"quiz","lessonCheck":true},"before":null},{"id":392,"quiz":{"q":"대출금 90억 원, 예수금 100억 원인 단순 사례에서 예대율은?","options":["10%","90%","약 111%"],"answer":1,"explanation":"대출금을 예수금으로 나눠 계산해요. 실제 규제에는 별도 산정 범위가 있어요.","type":"quiz","lessonCheck":true},"before":null},{"id":746,"quiz":{"q":"월중에는 잔액이 자주 바뀌었지만 월말 마지막 날 잔액만 확인했어요. 어떤 잔액인가요?","options":["평잔","월간 수입 합계","말잔"],"answer":2,"explanation":"말잔은 기간 말 시점의 잔액이고, 평잔은 기간 동안의 평균 잔액이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":449,"quiz":{"q":"채권 보유자가 만기 전에도 약정된 날짜마다 이자를 받아요. 가까운 채권 유형은?","options":["이표채","이자가 전혀 없는 영구 주식","무조건 할인채"],"answer":0,"explanation":"이표채는 약정에 따라 이자를 정기적으로 지급하는 채권이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":507,"quiz":{"q":"채권자가 약정 조건에 따라 채권을 발행사의 주식으로 바꿀 수 있어요. 어떤 채권인가요?","options":["무조건 상환만 가능한 회사채","전환사채","일반 국채"],"answer":1,"explanation":"전환사채에는 주식으로 전환할 수 있는 권리가 붙어 있어요.","type":"quiz","lessonCheck":true},"before":null},{"id":571,"quiz":{"q":"채권시장 경색에 대응하려 공동 자금을 모아 채권 매입에 활용해요. 가까운 장치는?","options":["가계 여행 적금","주식 액면분할","채권시장안정펀드"],"answer":2,"explanation":"채권시장의 자금 흐름과 안정을 지원하려는 펀드예요.","type":"quiz","lessonCheck":true},"before":null},{"id":714,"quiz":{"q":"옵션 가격에 반영된 코스피200의 예상 변동성이 커졌어요. 직접 연결되는 지표는?","options":["V-KOSPI","소비자물가지수","주택 전세가율"],"answer":0,"explanation":"V-KOSPI는 옵션에 내재된 변동성 기대를 나타내며 주가 상승 방향을 확정하지 않아요.","type":"quiz","lessonCheck":true},"before":null},{"id":777,"quiz":{"q":"미래 현금흐름은 같지만 적용 할인율이 높아졌어요. DCF 평가가치는?","options":["반드시 같다","낮아진다","높아진다"],"answer":1,"explanation":"미래 현금을 더 큰 할인율로 할인하면 현재가치가 줄어들어요.","type":"quiz","lessonCheck":true},"before":[{"type":"flow","steps":["기준금리 ↑","시장금리 ↑","무위험수익률 ↑","WACC·요구수익률 ↑","미래 현금흐름의 할인율 ↑","DCF 현재가치 ↓","주식의 적정가치 ↓"],"title":"금리가 오르면 주식의 적정가치가 낮아지는 이유","caption":"같은 미래 이익도 할인율이 높을수록 지금 가치로는 작아져요."}]},{"id":475,"quiz":{"q":"여러 대출채권을 묶고 그 현금흐름을 바탕으로 증권을 발행해요. 어떤 과정인가요?","options":["예금의 현금 인출","일반 상품 생산","자산유동화"],"answer":2,"explanation":"현금흐름을 만들어 내는 자산을 기초로 거래 가능한 증권을 만드는 방식이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":530,"quiz":{"q":"주택담보대출에서 들어오는 원리금을 바탕으로 증권을 만들었어요. 관련 상품은?","options":["MBS","일반 보통주","원자재 현물"],"answer":0,"explanation":"주택저당증권은 주택담보대출 채권 등을 기초로 발행되는 증권이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":278,"quiz":{"q":"자유로운 자본 이동과 고정환율을 유지하면서 독립적 통화정책까지 완벽히 추구하려 해요. 삼불원칙의 판단은?","options":["세 목표 중 어느 하나도 달성할 수 없다","세 목표를 동시에 완전히 달성하기 어렵다","세 목표는 언제나 충돌하지 않는다"],"answer":1,"explanation":"세 목표 사이에 제약이 있어 정책 조합에서 선택이 필요해요.","type":"quiz","lessonCheck":true},"before":null},{"id":566,"quiz":{"q":"만기 때 통화 원금 전액 대신 약정환율과 기준환율의 차액만 정산해요. 어떤 거래인가요?","options":["현금 환전","일반 예금 인출","NDF"],"answer":2,"explanation":"차액결제선물환은 환율 차이로 생긴 금액을 결제하는 구조예요.","type":"quiz","lessonCheck":true},"before":null},{"id":1209,"quiz":{"q":"환율은 주로 시장에서 정해지지만 당국이 급변을 완화하려 개입해요. 가까운 제도는?","options":["관리변동환율제","엄격한 고정환율제","외환거래 전면 금지"],"answer":0,"explanation":"시장 변동을 허용하면서 필요시 당국이 관리하는 방식이에요.","type":"quiz","lessonCheck":true},"before":[{"body":"평소엔 시장에 맡기다가 환율이 너무 빨리 움직이면 당국이 브레이크를 밟아요.","type":"text","title":"쉽게 설명"},{"rows":[["고정환율제","정부가 고정","외환보유액 부담"],["변동환율제","외환 수요·공급","환위험, 환투기"],["관리변동환율제","시장 + 급변 시 개입","개입 시점 판단이 어려움"]],"type":"table","title":"환율 제도 비교","columns":["제도","결정 방식","단점"]}]},{"id":321,"quiz":{"q":"수출기업이 해외 구매자의 대금 미지급 위험에 대비하려 보험에 들어요. 목적에 맞는 제도는?","options":["예금보험","수출보험","화재보험만"],"answer":1,"explanation":"수출대금 회수 등에 따르는 위험을 보험으로 분담하는 장치예요.","type":"quiz","lessonCheck":true},"before":null},{"id":533,"quiz":{"q":"상품을 사들여 국내에 반입하거나 가공하지 않고 제3국에 원형 그대로 팔았어요. 가까운 무역 방식은?","options":["단순 중개수수료 거래","국내 최종소비","중계무역"],"answer":2,"explanation":"중계무역은 물품을 사들여 다시 파는 거래이며 거래를 연결만 하는 중개와 구분돼요.","type":"quiz","lessonCheck":true},"before":null},{"id":700,"quiz":{"q":"통화가치 하락 후 무역수지가 먼저 나빠졌다가 시간이 지나 개선돼요. 가까운 현상은?","options":["J커브효과","즉시 균형 보장","일물일가의 법칙 자체"],"answer":0,"explanation":"계약과 수출입 물량이 조정되는 데 시간이 걸리면서 나타날 수 있어요.","type":"quiz","lessonCheck":true},"before":null},{"id":1194,"quiz":{"q":"역내 관세 철폐 후 비싼 국내 생산을 회원국의 저렴한 수입품이 대체해요. 어떤 효과인가요?","options":["수입 전면 중단","무역창출효과","무역전환효과"],"answer":1,"explanation":"더 낮은 비용의 생산으로 교역이 새로 발생하는 경우예요.","type":"quiz","lessonCheck":true},"before":[{"body":"국내에서 비싸게 만들던 물건을 관세가 사라진 회원국에서 더 싸게 사 와요.\n소비자는 이득이고 자원도 효율적으로 쓰여요.","type":"text","title":"쉽게 설명"},{"rows":[["무역창출효과","비싼 국내 생산 → 싼 회원국 수입","좋은 효과"],["무역전환효과","싼 비회원국 → 비싼 회원국 수입","나쁜 효과"]],"type":"table","title":"무역창출 vs 무역전환","columns":["효과","뜻","평가"]}]},{"id":1199,"quiz":{"q":"정부가 한 해 특정 상품 수입량을 1만 톤까지로 제한해요. 어떤 조치인가요?","options":["종가관세만 부과","수입 완전 자유화","수입할당제"],"answer":2,"explanation":"가격에 세금을 붙이는 대신 수입 가능한 물량에 한도를 둬요.","type":"quiz","lessonCheck":true},"before":[{"body":"올해는 이 상품을 1만 톤까지만 들여올 수 있다고 정하는 거예요.\n수입이 줄어 값이 오르면 면허를 가진 수입업자가 이득을 봐요.","type":"text","title":"쉽게 설명"},{"rows":[["수입할당제","수입국","수입업자"],["수출자율규제","수출국","수출국 기업"]],"type":"table","title":"수입할당제 vs 수출자율규제","columns":["구분","누가 줄이나","초과이윤"]}]},{"id":1205,"quiz":{"q":"국제수지 통계의 거래 자료를 집계했는데 대응 항목의 합계가 정확히 맞지 않아요. 통계상 조정 항목은?","options":["오차 및 누락","관세수입","기업 배당"],"answer":0,"explanation":"자료의 포착 범위와 시점 차이 등으로 생긴 불일치를 조정하는 항목이에요.","type":"quiz","lessonCheck":true},"before":[{"body":"가계부를 맞춰 보니 몇천 원이 비면 \"기타\"로 적어 두잖아요.\n국제수지표에서 그 칸이 오차 및 누락이에요.","type":"text","title":"쉽게 설명"},{"type":"flow","steps":["경상수지","+ 자본수지","- 금융계정","+ 오차 및 누락 = 0"],"title":"국제수지 항등식"}]},{"id":103,"quiz":{"q":"외화가 급히 필요해질 때 IMF 지원이나 국가 간 통화스왑을 활용하려 해요. 이런 장치들의 묶음은?","options":["기업 생산라인","글로벌금융안전망","국내 소매 결제망"],"answer":1,"explanation":"외화 유동성 위기에 대응하기 위한 국제적 지원 체계예요.","type":"quiz","lessonCheck":true},"before":null},{"id":164,"quiz":{"q":"개발도상국의 온실가스 감축과 기후 적응 사업을 지원하려 해요. 관련 국제기금은?","options":["일반 연금기금","예금보험기금","녹색기후기금"],"answer":2,"explanation":"GCF는 개발도상국의 기후변화 대응을 지원하는 기금이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":261,"quiz":{"q":"전후 국제통화질서에서 달러를 금과 연결하고 다른 통화를 달러에 연결했어요. 해당 체제는?","options":["브레튼우즈체제","자유변동환율만의 체제","모든 국가의 금화 직접 사용"],"answer":0,"explanation":"달러를 중심으로 고정환율 질서를 만든 역사적 체제예요.","type":"quiz","lessonCheck":true},"before":null},{"id":434,"quiz":{"q":"미국 밖 은행에 달러 표시 예금을 맡겼어요. 이 달러 자금의 일반적 명칭은?","options":["엔화 예금","유로달러","유로화 현금"],"answer":1,"explanation":"유로달러의 유로는 통화 유로를 뜻하지 않으며 미국 밖의 달러 예금 등을 가리켜요.","type":"quiz","lessonCheck":true},"before":null},{"id":478,"quiz":{"q":"정부가 자국의 광물에 대한 통제를 강화하고 수출을 제한해요. 관련 흐름은?","options":["자원 거래 완전 자유화","무역장벽 철폐","자원민족주의"],"answer":2,"explanation":"자원을 국가의 전략 자산으로 보고 자국 이익을 우선하는 움직임이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":596,"quiz":{"q":"해외 거래 상대의 경영은 안정적이지만 그 나라의 정치 혼란으로 송금이 막혔어요. 어떤 위험인가요?","options":["컨트리리스크","상품 재고 부족만의 위험","개별 제품 품질 위험"],"answer":0,"explanation":"상대국의 정치와 경제 환경이 거래 이행에 영향을 주는 국가위험이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":1087,"quiz":{"q":"상품 가격과 관계없이 한 병당 100원의 세금을 붙여요. 어떤 세금 방식인가요?","options":["소득세","종량세","종가세"],"answer":1,"explanation":"거래 금액이 아니라 수량 단위를 기준으로 세액을 매겨요.","type":"quiz","lessonCheck":true},"before":[{"body":"라면 한 봉지 팔 때마다 50원씩 세금을 내야 한다면 많이 팔수록 세금도 늘어요.\n그만큼 하나 더 만드는 비용이 올라가요.","type":"text","title":"쉽게 설명"},{"rows":[["종량세","한 단위마다 일정액","오름","생산량 감소, 가격 상승"],["정액세","생산량과 무관하게 일정액","그대로","변화 없음"]],"type":"table","title":"종량세와 정액세 비교","columns":["구분","매기는 방식","한계비용","생산량·가격"]}]},{"id":1125,"quiz":{"q":"단순 케인스 모형에서 정부지출과 정액세를 같은 금액만큼 늘려요. 투자 고정, 수입과 구축효과가 없다면 균형재정승수는?","options":["0","-1","1"],"answer":2,"explanation":"이 단순 모형에서는 지출 증가 효과가 증세에 따른 소비 감소보다 커서 늘린 정부지출만큼 국민소득이 증가해요.","type":"quiz","lessonCheck":true},"before":[{"body":"세금 100을 걷어 그대로 100을 써도\n경제 전체 소득은 100만큼 늘어나요.\n세금이 줄이는 소비보다 정부가 쓰는 돈이 더 크기 때문이에요.","type":"text","title":"쉽게 설명"},{"rows":[["정부지출 100","+500"],["세금 100","-400 (소비가 80 줄어서)"],["합계","+100"]],"type":"table","title":"한계소비성향 0.8일 때","caption":"늘어난 소득이 정부지출 금액과 같아서 승수가 1이에요.","columns":["항목","소득 변화"]}]},{"id":115,"quiz":{"q":"여러 은행이 서로 빌려준 돈이 많아 한 은행의 문제가 다른 은행으로 번져요. 중요한 구조는?","options":["금융시스템 상호연계성","완전한 기관 간 독립","가계 소비계절성"],"answer":0,"explanation":"기관 사이의 자금과 거래 연결이 충격 전파 경로가 될 수 있어요.","type":"quiz","lessonCheck":true},"before":null},{"id":339,"quiz":{"q":"은행이 집값 급락과 실업 급증을 가정해 손실을 계산해요. 어떤 점검인가요?","options":["주식 액면분할","스트레스 테스트","지난달 이익만 단순 집계"],"answer":1,"explanation":"불리한 가상 상황에서 자본과 유동성이 버틸 수 있는지 평가해요.","type":"quiz","lessonCheck":true},"before":null},{"id":343,"quiz":{"q":"보유 채권의 시장금리가 올라 채권 가격이 떨어졌어요. 직접적인 위험 유형은?","options":["직원 입력 실수만의 위험","단순 배송 지연","시장리스크"],"answer":2,"explanation":"금리 등 시장가격 변화로 자산 가치에 손실이 발생하는 위험이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":418,"quiz":{"q":"전산 장애 때문에 결제가 중단되고 손실이 났어요. 주된 위험 유형은?","options":["운영리스크","원자재 가격 위험만","외환 평가절하만"],"answer":0,"explanation":"시스템과 절차의 실패 등으로 발생하는 손실 위험이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":663,"quiz":{"q":"현금 결제에 쓰는 지폐와 동전의 금액 종류를 1, 5, 10 등의 조합으로 설계해요. 무엇을 정하나요?","options":["주가수익비율","화폐의 액면체계","통화정책 금리"],"answer":1,"explanation":"화폐 권종과 액면 금액의 구성을 정하는 문제예요.","type":"quiz","lessonCheck":true},"before":null},{"id":481,"quiz":{"q":"참여자가 연산 경쟁을 통해 블록 생성에 필요한 조건을 충족해요. 가까운 합의 방식은?","options":["지분증명","중앙은행의 직접 승인만","작업증명"],"answer":2,"explanation":"작업증명은 연산 작업을 수행했다는 증거를 블록 검증 등에 활용해요.","type":"quiz","lessonCheck":true},"before":null},{"id":179,"quiz":{"q":"채권자가 대출채권을 주식으로 바꾸어 주주가 됐어요. 이 조치는?","options":["출자전환","단순 만기 연장","원금의 현금 상환"],"answer":0,"explanation":"부채가 지분으로 바뀌는 구조이며 채권자가 주주의 위험을 부담하게 돼요.","type":"quiz","lessonCheck":true},"before":null},{"id":565,"quiz":{"q":"시장점유율이 50%, 30%, 20%인 세 기업뿐이에요. 백분율 수치를 제곱해 더한 HHI는?","options":["1,000","3,800","100"],"answer":1,"explanation":"50의 제곱 2,500, 30의 제곱 900, 20의 제곱 400을 더해요.","type":"quiz","lessonCheck":true},"before":null},{"id":1057,"quiz":{"q":"소비자가 A보다 B를 좋아한다고 순서를 매기지만 만족의 절대량은 말하지 않아요. 가까운 접근은?","options":["기수적 효용의 정확한 측정","가격만으로 선호 확정","서수적 효용"],"answer":2,"explanation":"서수적 효용은 선호의 순서가 중요하며 만족의 크기를 직접 비교하지 않아요.","type":"quiz","lessonCheck":true},"before":[{"body":"짜장면이 짬뽕보다 좋다는 건 말할 수 있어도\n정확히 몇 점 더 좋은지는 재기 어려워요.\n순서만 따지는 게 서수적 효용이에요.","type":"text","title":"쉽게 설명"},{"rows":[["비교하는 것","순서만","크기까지"],["82와 70","82가 더 좋음","12만큼 더 좋음"],["쓰이는 이론","무차별곡선 이론","한계효용 이론"]],"type":"table","title":"서수적 효용 vs 기수적 효용","columns":["구분","서수적 효용","기수적 효용"]}]},{"id":1091,"quiz":{"q":"기업들이 한 번만이 아니라 매달 반복해 거래하면서 다음 거래의 대응까지 고려해요. 분석 틀은?","options":["반복 게임","일회성 게임만","완전한 의사결정 부재"],"answer":0,"explanation":"현재 행동이 이후 상대의 행동에 영향을 줄 수 있어 반복 관계가 중요해요.","type":"quiz","lessonCheck":true},"before":[{"body":"한 번 보고 말 사이면 배신해도 그만이지만, 매일 볼 사이면 다음에 보복당할까 봐 약속을 지켜요.","type":"text","title":"쉽게 설명"},{"rows":[["한 번뿐인 게임","당장 이득","깨지기 쉬움"],["반복 게임","다음 판에 보복당함","유지되기도 함"]],"type":"table","title":"한 번과 반복의 차이","columns":["구분","배신의 결과","협조"]}]},{"id":1099,"quiz":{"q":"비옥한 땅과 척박한 땅에 같은 노동을 들였는데 비옥한 땅의 수확이 더 많아요. 차이에서 생기는 지대는?","options":["임금의 완전 소멸","차액지대","모든 토지의 동일 수확"],"answer":1,"explanation":"토지의 생산성 등 조건 차이가 초과 수익의 원인이 될 수 있어요.","type":"quiz","lessonCheck":true},"before":[{"body":"같은 노력으로 A 땅은 10가마, 한계지는 5가마를 거두면 A 땅 주인은 차이 5가마만큼 지대를 받을 수 있어요.","type":"text","title":"쉽게 설명"},{"rows":[["A","10가마","5가마"],["B","9가마","4가마"],["C","8가마","3가마"],["E","6가마","1가마"],["F (한계지)","5가마","0"]],"type":"table","title":"리카도의 땅별 차액지대","caption":"비옥할수록 차액지대가 커져요.","columns":["땅","수확량","차액지대"]}]},{"id":1173,"quiz":{"q":"물가상승률을 낮추는 과정에서 발생한 생산 손실을 낮아진 상승률과 비교해요. 관련 개념은?","options":["예대율","식료품 비중","희생비율"],"answer":2,"explanation":"디스인플레이션에 수반되는 산출 손실을 측정하는 비율이에요.","type":"quiz","lessonCheck":true},"before":[{"body":"물가를 잡으려고 금리를 올리면 경기가 식어요.\n물가상승률 1%p를 낮추는 데 GDP가 몇 % 줄었는지가 희생비율이에요.","type":"text","title":"쉽게 설명"},{"body":"중앙은행이 물가를 잡을 때 경기 희생을 얼마나 감수해야 하는지 가늠하게 해 줘요.","type":"text","title":"왜 중요할까?"}]},{"id":277,"quiz":{"q":"자동차 생산이 철강과 전기 산업에 얼마나 연결되는지 표로 분석하려 해요. 적합한 자료는?","options":["산업연관표","개별 주식 호가표","가계 출석부"],"answer":0,"explanation":"산업별로 무엇을 투입하고 어디에 산출물을 공급하는지 보여 주는 표예요.","type":"quiz","lessonCheck":true},"before":null},{"id":493,"quiz":{"q":"철강 공급 여건 개선이 철강을 쓰는 자동차 산업의 생산을 돕고 있어요. 가까운 효과는?","options":["산업 간 연결 없음","전방연쇄효과","자동차 수요가 철강을 늘리는 후방 효과"],"answer":1,"explanation":"중간재 공급 산업의 변화가 이를 사용하는 하류 산업에 미치는 효과예요.","type":"quiz","lessonCheck":true},"before":null},{"id":1149,"quiz":{"q":"전통적인 AD-AS 설명에서 명목통화량이 같은데 물가가 낮아지면 금리를 통한 총수요 경로는?","options":["실질통화량 감소, 금리 상승 방향","통화량과 금리는 전혀 무관","실질통화량 증가, 금리 하락, 투자 확대 방향"],"answer":2,"explanation":"다른 조건이 같다면 실질 화폐 잔액 증가가 금리를 낮추고 투자를 자극하는 이자율 효과예요.","type":"quiz","lessonCheck":true},"before":[{"body":"물건 값이 싸지면 거래에 필요한 돈이 줄어\n돈이 남게 돼요.\n남는 돈이 이자율을 낮추고 투자를 늘려요.","type":"text","title":"쉽게 설명"},{"type":"flow","steps":["실질통화량↑","이자율↓ (LM 오른쪽)","투자↑","국민소득↑"],"title":"물가가 내리면"}]},{"id":1179,"quiz":{"q":"기술 진보가 없는 솔로 모형에서 노동자 1인당 자본이 더 늘지 않고 일정해졌어요. 가까운 상태는?","options":["균제상태","자본의 무한 가속 성장","모든 생산 중단"],"answer":0,"explanation":"1인당 투자가 감가상각과 인구 증가에 필요한 자본 보충을 상쇄하는 상태예요.","type":"quiz","lessonCheck":true},"before":[{"body":"물이 들어오는 만큼 빠져나가 수위가 그대로인 욕조와 비슷해요.\n1인당 생산이 더 늘지도 줄지도 않아요.","type":"text","title":"쉽게 설명"},{"rows":[["1인당 생산·자본","멈춰요"],["총생산","인구 증가율만큼 늘어요"],["기술 진보가 있으면","균제상태가 위로 이동"]],"type":"table","title":"균제상태에서는","columns":["항목","변화"]}]},{"id":200,"quiz":{"q":"명목 GDP가 500이고 사람들이 보유하려는 화폐가 100이에요. 마샬의 k는?","options":["400","0.2","5"],"answer":1,"explanation":"명목소득 대비 화폐 보유 비율이므로 100을 500으로 나눠요.","type":"quiz","lessonCheck":true},"before":null},{"id":607,"quiz":{"q":"물가가 목표보다 높고 생산도 잠재 수준을 웃돌아요. 기본 테일러 준칙이 시사하는 금리 방향은?","options":["무조건 인하","어떤 경우에도 동결","인상 방향"],"answer":2,"explanation":"물가갭과 산출갭이 양수이면 기준금리를 높이는 방향의 신호가 돼요. 실제 결정은 더 많은 요인을 봐요.","type":"quiz","lessonCheck":true},"before":null},{"id":614,"quiz":{"q":"중앙은행이 은행들의 여유 자금을 기한부 예금으로 받아 시중 유동성을 흡수해요. 관련 수단은?","options":["통화안정계정","가계 주택담보대출","기업 주식 공모"],"answer":0,"explanation":"중앙은행이 금융기관의 자금을 일정 기간 묶어 유동성을 조절하는 수단이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":1144,"quiz":{"q":"저축 공급이 늘고 투자 수요는 같아요. 단순 대부자금시장 모형에서 균형 이자율은?","options":["반드시 변하지 않는다","내린다","오른다"],"answer":1,"explanation":"빌려줄 자금의 공급 증가가 균형 이자율을 낮추는 방향으로 작용해요.","type":"quiz","lessonCheck":true},"before":[{"body":"돈을 빌려주려는 사람과 빌리려는 사람이 만나는 시장이 있어요.\n빌려줄 돈이 많으면 이자가 싸지고\n빌리려는 사람이 많으면 이자가 비싸져요.","type":"text","title":"쉽게 설명"},{"rows":[["공급","저축하는 가계","빌려줄 돈"],["수요","투자하는 기업","빌리려는 돈"]],"type":"table","title":"대부자금시장","columns":["쪽","누가","무엇"]}]},{"id":1145,"quiz":{"q":"실질통화량이 일정한 단순 LM 모형에서 소득이 늘어 화폐수요가 커졌어요. 균형 이자율은?","options":["내린다","항상 0이 된다","오른다"],"answer":2,"explanation":"고정된 화폐공급 아래 늘어난 화폐수요를 맞추려면 이자율 상승이 필요해요.","type":"quiz","lessonCheck":true},"before":[{"body":"소득이 늘면 쓸 돈이 더 필요해요.\n돈은 그대로인데 찾는 사람이 많아지니 이자율이 올라요.\n이 관계를 선으로 그린 게 LM 곡선이에요.","type":"text","title":"쉽게 설명"},{"type":"flow","steps":["소득↑","화폐수요↑","화폐공급은 그대로","이자율↑"],"title":"LM 곡선이 우상향하는 이유"},{"rows":[["크다","완만"],["작다","가파름"],["0 (고전학파)","수직"],["무한대 (유동성 함정)","수평"]],"type":"table","title":"LM 곡선의 기울기","columns":["화폐수요의 이자율 탄력성","LM 모양"]}]},{"id":569,"quiz":{"q":"보유 채권의 시장 가격이 떨어져 장부 가치를 현재 시장 가격으로 다시 계산해요. 어떤 평가인가요?","options":["채권시가평가","취득원가만 유지","액면가만 고정 적용"],"answer":0,"explanation":"매입 시 가격이 아니라 평가 시점의 시장 가치를 반영해요.","type":"quiz","lessonCheck":true},"before":null},{"id":725,"quiz":{"q":"채권 입찰에서 두 낙찰자가 각각 써낸 금리대로 발행 조건을 적용받아요. 방식은?","options":["입찰 없는 수의계약","복수금리방식","모든 낙찰자에게 같은 금리 적용"],"answer":1,"explanation":"낙찰자마다 자신이 제시한 금리가 적용되는 방식이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":344,"quiz":{"q":"같은 날 1,000원에 1달러, 1,200원에 3달러가 거래됐어요. 거래량 가중평균 환율은?","options":["1,100원","1,200원","1,150원"],"answer":2,"explanation":"총 원화 4,600원을 총 거래량 4달러로 나눠요.","type":"quiz","lessonCheck":true},"before":null},{"id":403,"quiz":{"q":"외화자산이 100만 달러, 외화부채가 80만 달러예요. 단순 순외화포지션은?","options":["20만 달러 매입초과","20만 달러 매도초과","180만 달러 매입초과"],"answer":0,"explanation":"외화자산에서 외화부채를 빼면 양수이므로 순자산 또는 매입초과 상태예요.","type":"quiz","lessonCheck":true},"before":null},{"id":421,"quiz":{"q":"원화와 위안화를 달러로 바꾸는 중간 단계 없이 교환했어요. 어느 시장의 거래인가요?","options":["주식 발행시장","원·위안 직거래시장","원·달러 시장만"],"answer":1,"explanation":"두 통화를 직접 교환해 달러 경유 거래와 구분돼요.","type":"quiz","lessonCheck":true},"before":null},{"id":779,"quiz":{"q":"정책 충격 뒤 환율이 새 장기 수준을 넘어 크게 움직였다가 되돌아와요. 가까운 현상은?","options":["항상 고정된 환율","환율 변화 없음","환율 오버슈팅"],"answer":2,"explanation":"단기 반응이 장기 균형 변화보다 커지는 현상이에요.","type":"quiz","lessonCheck":true},"before":[{"type":"flow","steps":["통화정책 변화","금리 즉각 변화","자본이동","환율 급변 (균형보다 더)","가격·임금이 천천히 조정","환율 일부 되돌림"],"title":"환율이 한 번에 크게 움직이는 과정"}]},{"id":1189,"quiz":{"q":"수출 생산은 늘었는데 수출가격 하락으로 교역조건이 크게 악화해 후생이 줄었어요. 가능한 현상은?","options":["궁핍화 성장","성장이면 항상 후생 증가","수입 완전 중단"],"answer":0,"explanation":"특정 조건에서는 교역조건 악화가 생산 확대의 이득을 넘어설 수 있어요.","type":"quiz","lessonCheck":true},"before":[{"body":"커피만 수출하는 나라가 커피를 두 배로 만들면 커피값이 폭락해요.\n더 많이 팔아도 사 올 수 있는 물건은 오히려 줄 수 있어요.","type":"text","title":"쉽게 설명"},{"type":"flow","steps":["수출품 생산 급증","국제 가격 하락","교역조건 악화","GDP↑ 그러나 후생↓"],"title":"궁핍화 성장 과정"}]},{"id":1156,"quiz":{"q":"정부지출이 같은데 감세를 국채로 메워요. 가계가 미래 증세를 완전히 예상하고 추가 소득을 저축한다는 이론은?","options":["화폐수요가 항상 0이라는 이론","리카도 대등정리","현재 감세가 항상 같은 만큼 소비를 늘린다는 이론"],"answer":1,"explanation":"엄격한 가정 아래 조세와 국채 조달의 소비 효과가 같아질 수 있다는 주장으로 현실의 보편 법칙은 아니에요.","type":"quiz","lessonCheck":true},"before":[{"body":"정부가 빚을 내서 세금을 깎아 줘도\n\"나중에 세금으로 갚겠구나\" 하고 저축하면\n소비는 그대로예요.","type":"text","title":"쉽게 설명"},{"type":"flow","steps":["오늘 세금↓, 가처분소득↑","미래 증세를 예상","늘어난 소득을 저축","소비 그대로"],"title":"국채로 감세하면"},{"rows":[["유동성 제약","돈을 빌리기 어려운 사람은 감세분을 바로 써요"],["근시안","먼 미래 세금까지 계산하지 않아요"],["세대 차이","미래 세대가 갚는다고 보면 지금 소비를 늘려요"]],"type":"table","title":"현실에서 잘 안 맞는 이유","columns":["이유","내용"]}]},{"id":133,"quiz":{"q":"은행이 계속 영업하는 상태에서 손실을 흡수할 핵심 자본의 충분성을 봐요. 관련 자본 분류는?","options":["일반 고객 예금","단기 차입금 전부","기본자본(Tier 1)"],"answer":2,"explanation":"기본자본은 영업을 지속하는 동안 손실을 흡수할 수 있는 자본이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":225,"quiz":{"q":"여러 나라 감독당국이 은행 자본 규제의 국제 기준을 함께 논의해요. 관련 기구는?","options":["바젤은행감독위원회","세계보건기구","국내 개별 은행 이사회"],"answer":0,"explanation":"BCBS는 은행 감독과 건전성 규제의 국제 기준을 논의하는 기구예요.","type":"quiz","lessonCheck":true},"before":null},{"id":326,"quiz":{"q":"은행이 장기 대출을 매우 짧은 차입금에만 의존해 운용해요. 특히 살펴볼 지표는?","options":["실업률","순안정자금조달비율","소비자물가상승률"],"answer":1,"explanation":"NSFR은 자산 구조에 비해 안정적인 자금조달이 충분한지 살펴요.","type":"quiz","lessonCheck":true},"before":null},{"id":450,"quiz":{"q":"은행이 특정 기업에 빌려준 돈이 100억 원에서 150억 원으로 늘었어요. 그 기업에 대한 익스포저는?","options":["작아졌다","항상 같다","커졌다"],"answer":2,"explanation":"해당 거래 상대의 위험에 노출된 금액이 늘어난 상황이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":472,"quiz":{"q":"같은 위험의 자산을 가진 두 은행 중 손실을 흡수할 자본이 더 많은 은행을 비교해요. 우선 유리한 측면은?","options":["자본적정성","반드시 높은 수익률","반드시 낮은 모든 운영비"],"answer":0,"explanation":"다른 조건이 같다면 손실에 대비한 자본 여력이 더 크다고 볼 수 있어요.","type":"quiz","lessonCheck":true},"before":null},{"id":739,"quiz":{"q":"동일한 금액의 두 자산에 서로 다른 위험가중치가 적용돼요. 위험가중자산이 더 큰 것은?","options":["항상 두 자산이 같다","위험가중치가 높은 자산","위험가중치가 낮은 자산"],"answer":1,"explanation":"같은 노출액에 더 높은 가중치를 곱하면 위험가중자산이 더 커져요.","type":"quiz","lessonCheck":true},"before":null},{"id":37,"quiz":{"q":"주식을 팔았지만 종이 증서를 옮기지 않고 장부의 계좌 간 기록을 변경했어요. 방식은?","options":["실물 현금 배송","주식 액면분할","계좌대체"],"answer":2,"explanation":"예탁·등록 장부의 계좌 이동으로 권리 이전을 처리하는 방식이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":171,"quiz":{"q":"월요일에 외환 거래를 맺고 그 월요일에 결제했어요. 결제 시점 분류는?","options":["당일결제","익일결제","익익일결제"],"answer":0,"explanation":"거래 계약일과 자금 결제일이 같은 방식이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":173,"quiz":{"q":"회사가 하나의 계좌에서 직원 100명에게 급여를 한꺼번에 이체해요. 가까운 지급 방식은?","options":["외환 차익거래","대량지급","개별 주식 청약"],"answer":1,"explanation":"한 지급자가 여러 수취인에게 급여나 연금 등을 일괄 지급하는 방식이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":361,"quiz":{"q":"은행 간 지급 지시가 들어올 때마다 서로 상계하지 않고 즉시 전액 결제해요. 방식은?","options":["하루 말 차액결제만","한 달 뒤 일괄 결제","실시간총액결제"],"answer":2,"explanation":"각 지급 건을 실시간으로 개별 결제하므로 총액 기준이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":462,"quiz":{"q":"학원이 여러 수강생 계좌에서 동의받은 수강료를 일괄 출금하려 해요. 관련 공동망은?","options":["CMS공동망","주식 거래소","신용평가 등급표"],"answer":0,"explanation":"CMS는 다수 계좌의 자금 수납과 지급을 지원하는 서비스예요.","type":"quiz","lessonCheck":true},"before":null},{"id":502,"quiz":{"q":"종이 대신 전자문서로 약속어음을 발행하고 온라인으로 이전해요. 해당 수단은?","options":["현물 금 인도","전자어음","종이 수표 배송"],"answer":1,"explanation":"어음의 발행과 유통을 전자적으로 처리하는 지급 수단이에요.","type":"quiz","lessonCheck":true},"before":null},{"id":534,"quiz":{"q":"청산기관이 매도자에게는 매수자, 매수자에게는 매도자가 되어 거래 이행을 관리해요. 역할은?","options":["단순 광고 중개인","개별 거래의 구경꾼","중앙거래당사자"],"answer":2,"explanation":"CCP가 거래 사이에 들어가 상대방 위험을 관리하며 위험 자체가 모두 없어지는 것은 아니에요.","type":"quiz","lessonCheck":true},"before":null},{"id":540,"quiz":{"q":"증권을 넘길 때 대금도 함께 결제되도록 두 절차를 연결했어요. 방식은?","options":["증권대금동시결제","증권만 먼저 주고 대금은 무조건 나중","단순 현금 보관"],"answer":0,"explanation":"증권 인도와 대금 지급을 연계해 한쪽만 이행되는 원금 위험을 줄여요.","type":"quiz","lessonCheck":true},"before":null},{"id":558,"quiz":{"q":"은행들이 결제 건을 모아 정해진 시각에 일괄 처리해요. 시간 처리 방식은?","options":["결제 영구 연기","지정시점처리","모든 건의 즉시 처리"],"answer":1,"explanation":"미리 정한 시각에 묶어서 처리하는 방식으로 실시간 처리와 구분돼요.","type":"quiz","lessonCheck":true},"before":null},{"id":567,"quiz":{"q":"A은행이 B은행에 100억 원, B은행이 A은행에 70억 원을 지급해야 해요. 차액결제라면?","options":["B가 A에게 30억 원 지급","A가 B에게 170억 원 지급","A가 B에게 30억 원 지급"],"answer":2,"explanation":"서로의 지급 의무를 상계한 순차액 100-70만 이전해요.","type":"quiz","lessonCheck":true},"before":null},{"id":659,"quiz":{"q":"결제 안전성을 확보하면서 상계로 필요한 자금도 절약하려 해요. 두 방식의 장점을 결합한 것은?","options":["혼합형결제시스템","실물 현금 운송만","결제 없는 거래"],"answer":0,"explanation":"총액결제와 차액결제의 장점을 결합해 안전성과 유동성 효율을 추구해요.","type":"quiz","lessonCheck":true},"before":null},{"id":695,"quiz":{"q":"외환 거래에서 원화는 보냈지만 상대 은행이 파산해 받을 달러를 못 받았어요. 대표적인 위험은?","options":["주식 희석 위험","Herstatt 리스크","단순 환율 변동만의 위험"],"answer":1,"explanation":"두 통화 결제 시점 차이 등으로 한쪽 원금만 지급되는 외환결제 위험이에요.","type":"quiz","lessonCheck":true},"before":null}]$payload$::jsonb) p ON w.id=(p->>'id')::integer
  WHERE COALESCE(w.visuals,'[]'::jsonb)=COALESCE(NULLIF(p->'before','null'::jsonb),'[]'::jsonb)
     OR COALESCE(w.visuals,'[]'::jsonb)=COALESCE(NULLIF(p->'before','null'::jsonb),'[]'::jsonb)||jsonb_build_array(p->'quiz');
  IF matched <> 221 THEN RAISE EXCEPTION 'Content changed since review: matched % of 221', matched; END IF;
END $guard$;
WITH payload AS (
 SELECT (p->>'id')::integer id,p->'quiz' quiz FROM jsonb_array_elements($payload$[{"id":724,"quiz":{"q":"100만 원을 연 10% 복리로 2년간 맡겼어요. 세금이 없다면 얼마가 되나요?","options":["121만 원","120만 원","110만 원"],"answer":0,"explanation":"둘째 해에는 원금과 첫해 이자를 합한 110만 원에 10%가 붙어요.","type":"quiz","lessonCheck":true}},{"id":1011,"quiz":{"q":"다른 조건은 같고 사과 가격만 올랐어요. 수요의 법칙에 따른 변화는?","options":["수요곡선 자체가 오른쪽 이동","사려는 양 감소","사려는 양 증가"],"answer":1,"explanation":"가격 자체의 변화는 같은 수요곡선 위에서 수요량을 바꿔요.","type":"quiz","lessonCheck":true}},{"id":1026,"quiz":{"q":"한 가격에서 손님은 100개를 사고 가게도 100개를 팔려 해요. 이 상태는?","options":["초과수요","초과공급","시장균형"],"answer":2,"explanation":"그 가격에서 수요량과 공급량이 같아 부족분이나 남는 물량이 없어요.","type":"quiz","lessonCheck":true}},{"id":1029,"quiz":{"q":"같은 가격에서 손님은 100개를 원하지만 가게는 60개만 팔려 해요. 부족한 양은?","options":["40개","60개","160개"],"answer":0,"explanation":"수요량 100개에서 공급량 60개를 빼면 초과수요는 40개예요.","type":"quiz","lessonCheck":true}},{"id":1,"quiz":{"q":"한 달 수입이 300만 원, 지출이 250만 원이에요. 가계수지는?","options":["550만 원 흑자","50만 원 흑자","50만 원 적자"],"answer":1,"explanation":"수입에서 지출을 빼면 50만 원이 남아요.","type":"quiz","lessonCheck":true}},{"id":224,"quiz":{"q":"새 아파트 100가구를 분양했지만 20가구가 계약되지 않았어요. 이 20가구는?","options":["전세주택","기존 중고주택","미분양주택"],"answer":2,"explanation":"분양했으나 팔리지 않은 새 주택을 미분양주택이라 해요.","type":"quiz","lessonCheck":true}},{"id":578,"quiz":{"q":"연소득 5천만 원, 모든 대출의 연간 원리금이 1천만 원이면 단순 계산한 DSR은?","options":["20%","5%","50%"],"answer":0,"explanation":"연간 원리금 1천만 원을 연소득 5천만 원으로 나눠요. 실제 심사에서는 대출별 산정 규칙도 적용돼요.","type":"quiz","lessonCheck":true}},{"id":945,"quiz":{"q":"새 소파를 산 뒤 어울리는 탁자와 조명까지 샀어요. 이 연쇄 소비는?","options":["기저효과","디드로 효과","립스틱 효과"],"answer":1,"explanation":"한 물건의 구매가 주변 물건의 추가 구매를 유발한 사례예요.","type":"quiz","lessonCheck":true}},{"id":901,"quiz":{"q":"과자 가격은 2천 원인데 내용량이 100g에서 80g으로 줄었어요. 해석은?","options":["단위 무게당 가격 하락","실질 가격 불변","단위 무게당 가격 상승"],"answer":2,"explanation":"1g당 가격이 20원에서 25원으로 올라요.","type":"quiz","lessonCheck":true}},{"id":1174,"quiz":{"q":"매년 6%로 꾸준히 성장한다고 가정해요. 72의 법칙으로 두 배까지 걸리는 기간은?","options":["약 12년","약 6년","약 72년"],"answer":0,"explanation":"72를 성장률 숫자 6으로 나눈 12년으로 어림해요. 정확한 복리 계산값은 아니에요.","type":"quiz","lessonCheck":true}},{"id":364,"quiz":{"q":"명목임금은 그대로인데 물가가 10% 올랐어요. 실질임금은?","options":["변하지 않는다","하락한다","상승한다"],"answer":1,"explanation":"같은 임금으로 살 수 있는 양이 줄어 구매력 기준 임금이 낮아져요.","type":"quiz","lessonCheck":true}},{"id":573,"quiz":{"q":"청년 경제활동인구 100명 중 취업자 90명, 실업자 10명이에요. 청년실업률은?","options":["약 11.1%","90%","10%"],"answer":2,"explanation":"실업자를 취업자만이 아니라 전체 경제활동인구로 나눠요.","type":"quiz","lessonCheck":true}},{"id":721,"quiz":{"q":"15세 이상 200명 중 취업자 100명, 실업자 20명이에요. 경제활동참가율은?","options":["60%","50%","10%"],"answer":0,"explanation":"취업자와 실업자를 합친 120명을 15세 이상 인구 200명으로 나눠요.","type":"quiz","lessonCheck":true}},{"id":1009,"quiz":{"q":"빵집이 제빵사를 채용하고 오븐을 빌려요. 무엇을 거래하는 시장인가요?","options":["외환시장","생산요소 시장","최종 소비재 시장"],"answer":1,"explanation":"노동과 생산 설비는 빵을 만드는 데 투입되는 생산요소예요.","type":"quiz","lessonCheck":true}},{"id":749,"quiz":{"q":"고정 이자를 주는 기존 채권의 거래 가격이 떨어졌어요. 다른 조건이 같다면 수익률은?","options":["내린다","항상 그대로다","오른다"],"answer":2,"explanation":"같은 미래 지급액을 더 싼 가격에 사므로 수익률은 높아져요.","type":"quiz","lessonCheck":true}},{"id":905,"quiz":{"q":"기준금리가 3.0%에서 3.5%로 올랐어요. 인상 폭은?","options":["0.5%포인트","0.5%","3.5%포인트"],"answer":0,"explanation":"두 금리의 차이는 0.5%포인트이며, 이런 폭의 조정을 빅스텝이라고 불러요.","type":"quiz","lessonCheck":true}},{"id":820,"quiz":{"q":"주식 1주를 5주로 액면분할해요. 분할만으로 기존 10주는 몇 주가 되나요?","options":["10주","50주","2주"],"answer":1,"explanation":"주식 수가 5배가 되지만 분할 자체로 기업 가치나 보유 지분율이 늘지는 않아요.","type":"quiz","lessonCheck":true}},{"id":849,"quiz":{"q":"회사가 새 주식을 발행해 투자자에게 돈을 받고 팔았어요. 어떤 자금 조달인가요?","options":["무상증자","액면분할","유상증자"],"answer":2,"explanation":"유상증자는 새 주식의 대금을 받아 회사 자본을 늘리는 방식이에요.","type":"quiz","lessonCheck":true}},{"id":867,"quiz":{"q":"투자자가 악재를 보고 가치 검토 없이 급히 주식을 모두 팔았어요. 가까운 표현은?","options":["패닉 셀","리밸런싱","유상증자"],"answer":0,"explanation":"공포에 휩쓸려 급하게 매도하는 행동을 패닉 셀이라 해요.","type":"quiz","lessonCheck":true}},{"id":893,"quiz":{"q":"집값이 더 오를까 불안해 예산 검토도 없이 매수를 서둘러요. 가까운 표현은?","options":["차익실현","패닉 바잉","분산투자"],"answer":1,"explanation":"가격 상승을 놓칠 것이라는 불안이 성급한 매수로 이어진 상황이에요.","type":"quiz","lessonCheck":true}},{"id":928,"quiz":{"q":"100주 주문에 0을 더 입력해 1,000주를 주문했어요. 어떤 위험의 사례인가요?","options":["환율 위험","배당 감소","팻 핑거"],"answer":2,"explanation":"입력 실수로 의도와 다른 주문이 나간 사례예요.","type":"quiz","lessonCheck":true}},{"id":996,"quiz":{"q":"회사가 번 이익 일부를 주주에게 정기적으로 나눠 줘요. 이 현금 흐름은?","options":["배당","대출 원금 상환","신주 청약 대금"],"answer":0,"explanation":"배당은 이익의 일부를 주주에게 분배하는 것이며 금액과 지급 여부는 변할 수 있어요.","type":"quiz","lessonCheck":true}},{"id":847,"quiz":{"q":"펀드가 특정 주가지수와 비슷한 구성과 수익률을 목표로 운용돼요. 가까운 유형은?","options":["정기예금","패시브펀드","개별 종목 직접투자"],"answer":1,"explanation":"지수를 따라가는 운용은 시장 초과 수익을 적극 추구하는 운용과 구분돼요.","type":"quiz","lessonCheck":true}},{"id":879,"quiz":{"q":"목표는 주식 60%, 채권 40%인데 주가 상승으로 80:20이 됐어요. 목표 비중으로 되돌리는 일은?","options":["공매도","액면분할","리밸런싱"],"answer":2,"explanation":"자산 가격 변화로 달라진 비중을 정해 둔 목표에 맞추는 조정이에요.","type":"quiz","lessonCheck":true}},{"id":964,"quiz":{"q":"초기 투자자가 보유한 스타트업 지분을 팔아 투자금을 회수했어요. 이 과정은?","options":["엑시트","신규 출자","유상증자 참여"],"answer":0,"explanation":"기존 투자에서 지분 매각 등으로 빠져나와 자금을 회수한 것이에요.","type":"quiz","lessonCheck":true}},{"id":993,"quiz":{"q":"개인이 창업 초기 기업에 자기 돈을 투자하고 지분을 받아요. 가까운 유형은?","options":["국채 매입","엔젤투자","주택담보대출"],"answer":1,"explanation":"개인이 초기 기업의 성장 가능성을 보고 위험을 부담하며 투자하는 방식이에요.","type":"quiz","lessonCheck":true}},{"id":751,"quiz":{"q":"1달러 가격이 1,200원에서 1,300원이 됐어요. 100달러 구매 비용은 얼마나 늘었나요?","options":["100원","10만 원","1만 원"],"answer":2,"explanation":"달러당 100원씩 더 필요하므로 100달러에는 1만 원이 더 들어요.","type":"quiz","lessonCheck":true}},{"id":883,"quiz":{"q":"한 기간 상품 수출액이 120억 달러, 수입액이 100억 달러예요. 무역수지는?","options":["20억 달러 흑자","20억 달러 적자","220억 달러 흑자"],"answer":0,"explanation":"수출액에서 수입액을 뺀 차이가 양수이므로 흑자예요.","type":"quiz","lessonCheck":true}},{"id":1186,"quiz":{"q":"한 지역이 기회비용이 낮은 과일 생산에 자원을 집중하고 옷은 다른 지역과 교환해요. 이 생산 방식은?","options":["가격통제","특화","자급자족"],"answer":1,"explanation":"비교적 유리한 생산에 집중하는 것이 특화이며 교환과 함께 활용돼요.","type":"quiz","lessonCheck":true}},{"id":491,"quiz":{"q":"정부가 경기 부양을 위해 공공사업 지출을 늘려요. 어떤 정책인가요?","options":["긴축 통화정책","기업의 배당정책","확장 재정정책"],"answer":2,"explanation":"정부 지출 확대는 총수요를 늘리려는 재정정책 수단이에요.","type":"quiz","lessonCheck":true}},{"id":939,"quiz":{"q":"항만과 철도를 확충해 기업의 운송 여건을 개선해요. 이런 시설은?","options":["사회간접자본","가계 금융자산","소비재 재고"],"answer":0,"explanation":"여러 생산 활동을 뒷받침하는 공공 기반 시설이에요.","type":"quiz","lessonCheck":true}},{"id":984,"quiz":{"q":"쓰레기 처리 시설의 필요성은 인정하지만 자기 동네 설치만 반대해요. 가까운 현상은?","options":["리쇼어링","님비","특화"],"answer":1,"explanation":"시설의 사회적 필요와 자기 지역의 부담을 다르게 받아들이는 사례예요.","type":"quiz","lessonCheck":true}},{"id":560,"quiz":{"q":"카드로 결제하자 연결된 예금계좌에서 즉시 돈이 빠졌어요. 가까운 결제 방식은?","options":["후불 외상 결제","장기 할부대출","직불 결제"],"answer":2,"explanation":"직불 방식은 계좌 잔액에서 결제 대금이 즉시 지급돼요.","type":"quiz","lessonCheck":true}},{"id":269,"quiz":{"q":"가게가 수많은 주문 기록을 분석해 시간대별 수요를 예측해요. 활용하는 것은?","options":["빅데이터 분석","액면분할","화폐 발행"],"answer":0,"explanation":"대량의 거래 자료에서 패턴을 찾아 의사결정에 사용하는 사례예요.","type":"quiz","lessonCheck":true}},{"id":500,"quiz":{"q":"손님이 온라인 쇼핑몰에서 주문하고 결제했어요. 이 거래는?","options":["중앙은행 공개시장운영","전자상거래","은행 간 결제만을 위한 거래"],"answer":1,"explanation":"온라인으로 상품이나 서비스를 거래하는 전자상거래 사례예요.","type":"quiz","lessonCheck":true}},{"id":897,"quiz":{"q":"제품의 환경 개선 근거는 없는데 친환경 이미지만 강조해 광고해요. 주의할 현상은?","options":["리쇼어링","가격경쟁","그린워싱"],"answer":2,"explanation":"실제 환경 성과보다 친환경인 것처럼 보이게 포장하는 행위예요.","type":"quiz","lessonCheck":true}},{"id":990,"quiz":{"q":"기업이 반도체 설계만 맡고 생산은 전문 제조업체에 의뢰해요. 이 기업의 유형은?","options":["팹리스","파운드리","종합상사"],"answer":0,"explanation":"팹리스는 자체 제조 공장 없이 반도체 설계에 집중해요.","type":"quiz","lessonCheck":true}},{"id":902,"quiz":{"q":"장부상 이익은 있지만 외상대금을 받지 못해 만기 채무를 갚지 못했어요. 가능한 상황은?","options":["무상증자","흑자도산","현금 과잉"],"answer":1,"explanation":"이익 발생과 현금 유입 시점은 달라서 흑자여도 지급 불능에 빠질 수 있어요.","type":"quiz","lessonCheck":true}},{"id":983,"quiz":{"q":"작은 업체가 특정 알레르기가 있는 고객만을 위한 제품에 집중해요. 겨냥하는 시장은?","options":["전체 대중시장","은행 간 시장","니치마켓"],"answer":2,"explanation":"큰 시장 안에서 특정 수요를 가진 좁은 고객층을 공략하는 전략이에요.","type":"quiz","lessonCheck":true}},{"id":644,"quiz":{"q":"처분가능소득이 100만 원 늘었을 때 소비가 70만 원 늘었어요. 한계소비성향은?","options":["0.7","1.7","약 1.43"],"answer":0,"explanation":"추가 소비 70만 원을 추가 소득 100만 원으로 나눠요.","type":"quiz","lessonCheck":true}},{"id":1004,"quiz":{"q":"매출 100만 원, 명시적 비용 60만 원, 포기한 다른 일의 소득 30만 원이에요. 경제학적 이익은?","options":["70만 원","10만 원","40만 원"],"answer":1,"explanation":"명시적 비용뿐 아니라 암묵적 기회비용 30만 원도 차감해요.","type":"quiz","lessonCheck":true}},{"id":1015,"quiz":{"q":"이번 달 월급과 오늘의 예금 잔액을 구분해요. 올바른 연결은?","options":["월급은 저량, 잔액은 유량","둘 다 유량","월급은 유량, 잔액은 저량"],"answer":2,"explanation":"기간에 걸쳐 생긴 소득은 유량, 한 시점의 보유액은 저량이에요.","type":"quiz","lessonCheck":true}},{"id":1031,"quiz":{"q":"가격이 10% 올랐을 때 수요량이 약 20% 줄었어요. 수요의 가격탄력성 절댓값은 대략?","options":["2","0.5","0.1"],"answer":0,"explanation":"수요량 변화율의 절댓값을 가격 변화율로 나누면 20/10=2예요.","type":"quiz","lessonCheck":true}},{"id":1037,"quiz":{"q":"농산물 수요가 비탄력적인데 풍년으로 공급이 크게 늘었어요. 농가 총수입은?","options":["반드시 그대로다","줄어들 수 있다","반드시 늘어난다"],"answer":1,"explanation":"판매량 증가보다 가격 하락 효과가 커지면 총수입이 줄 수 있어요.","type":"quiz","lessonCheck":true}},{"id":1060,"quiz":{"q":"용돈 1만 원으로 2천 원짜리 음료와 3천 원짜리 빵을 사요. 가능한 조합은?","options":["음료 3개와 빵 2개","음료 1개와 빵 3개","음료 2개와 빵 2개"],"answer":2,"explanation":"첫 조합만 총액 1만 원으로 예산을 넘지 않아요.","type":"quiz","lessonCheck":true}},{"id":1113,"quiz":{"q":"산 빵을 먹으면 다른 사람이 그 빵을 먹을 수 없고, 판매자가 미구매자를 배제할 수 있어요. 빵은?","options":["사적재","순수 공공재","비경합적 정보"],"answer":0,"explanation":"배제성과 경합성을 모두 가진 소비재의 사례예요.","type":"quiz","lessonCheck":true}},{"id":378,"quiz":{"q":"소득이 늘어 식비는 조금 늘었지만 전체 소비에서 식비 비중은 낮아졌어요. 가까운 법칙은?","options":["그레샴의 법칙","엥겔의 법칙","수요의 법칙"],"answer":1,"explanation":"소득이 높아질수록 소비지출 중 식비 비중이 낮아지는 경향이에요.","type":"quiz","lessonCheck":true}},{"id":1039,"quiz":{"q":"소득이 20% 늘 때 어떤 물건의 수요가 5%만 늘었어요. 소득탄력성 기준 유형은?","options":["사치재","열등재","필수재"],"answer":2,"explanation":"소득탄력성이 양수이면서 1보다 작으므로 필수재로 분류해요.","type":"quiz","lessonCheck":true}},{"id":50,"quiz":{"q":"자동차 주문은 충분하지만 반도체 부족으로 생산이 멈췄어요. 가까운 현상은?","options":["공급병목","초과공급 재고 누적","수요 소멸"],"answer":0,"explanation":"특정 투입물의 부족이 전체 생산 흐름을 막은 상황이에요.","type":"quiz","lessonCheck":true}},{"id":189,"quiz":{"q":"물가상승률이 5%에서 2%로 낮아졌어요. 가장 정확한 해석은?","options":["물가가 오르지 않았다","물가는 오르되 속도가 느려졌다","물가 수준이 3% 내려갔다"],"answer":1,"explanation":"양의 상승률이 낮아진 것은 디스인플레이션이며 물가 하락과 달라요.","type":"quiz","lessonCheck":true}},{"id":880,"quiz":{"q":"식당이 가격을 바꾸려고 메뉴판과 안내물을 다시 만들었어요. 이 비용은?","options":["매몰된 대출 원금","관세","메뉴비용"],"answer":2,"explanation":"가격 조정에 필요한 인쇄와 안내 등의 비용을 뜻해요.","type":"quiz","lessonCheck":true}},{"id":249,"quiz":{"q":"빵집이 밀가루 등 중간재 40만 원으로 빵 100만 원어치를 만들었어요. 부가가치는?","options":["60만 원","100만 원","140만 원"],"answer":0,"explanation":"산출액에서 중간투입액을 빼면 새로 더한 가치가 남아요.","type":"quiz","lessonCheck":true}},{"id":482,"quiz":{"q":"현재 GDP가 늘었다는 이유만으로 잠재성장률도 반드시 올랐다고 할 수 있나요?","options":["네, 물가만 오르면 잠재성장률도 올라요","아니요, 지속 가능한 생산능력을 따로 봐야 해요","네, 두 수치는 항상 같아요"],"answer":1,"explanation":"실제 생산의 단기 반등과 노동·자본·생산성에 따른 장기 능력은 구분해요.","type":"quiz","lessonCheck":true}},{"id":693,"quiz":{"q":"실제 GDP가 105, 잠재 GDP가 100이에요. GDP갭의 방향은?","options":["음의 갭","갭 없음","양의 갭"],"answer":2,"explanation":"실제 생산이 잠재 수준보다 높으므로 양의 갭이에요.","type":"quiz","lessonCheck":true}},{"id":731,"quiz":{"q":"명목 GDP는 10% 늘었지만 생산량은 그대로이고 가격만 10% 올랐어요. 실질 GDP는?","options":["변하지 않는다","10% 증가한다","10% 감소한다"],"answer":0,"explanation":"실질 GDP는 가격 변화 효과를 제거해 생산량 변화를 측정해요.","type":"quiz","lessonCheck":true}},{"id":1119,"quiz":{"q":"가정이 먹으려고 산 빵과 빵집이 생산에 쓰려고 산 밀가루 중 최종 생산물은?","options":["둘 다 중간재","가정이 산 빵","빵집이 산 밀가루"],"answer":1,"explanation":"분류는 물건 이름보다 사용 목적에 따라 달라져요. 소비자가 먹는 빵은 최종재예요.","type":"quiz","lessonCheck":true}},{"id":1183,"quiz":{"q":"같은 산정 방식의 제조업 PMI가 48에서 52가 됐어요. 일반적인 해석은?","options":["생산량이 정확히 4% 증가","물가가 정확히 52% 상승","전월 대비 위축에서 확장 쪽으로 전환"],"answer":2,"explanation":"PMI의 50은 확장과 위축을 가르는 기준이며 지수 차이가 생산 증가율은 아니에요.","type":"quiz","lessonCheck":true}},{"id":161,"quiz":{"q":"같은 근로시간에 생산량이 100개에서 120개로 늘었어요. 노동생산성 변화는?","options":["20% 상승","20% 하락","변화 없음"],"answer":0,"explanation":"노동 투입이 같을 때 산출량이 20% 늘면 노동생산성도 20% 높아져요.","type":"quiz","lessonCheck":true}},{"id":202,"quiz":{"q":"직장을 그만둔 사람이 자신에게 맞는 새 일자리를 찾는 중이에요. 대표적인 실업 유형은?","options":["기술 변화로 인한 구조적 실업","마찰적 실업","계절적 실업"],"answer":1,"explanation":"일자리 이동 과정에서 탐색과 연결에 시간이 드는 실업이에요.","type":"quiz","lessonCheck":true}},{"id":851,"quiz":{"q":"경제가 완전고용 상태여도 구직 중인 사람이 있을 수 있나요?","options":["아니요, 실업자가 반드시 0명이에요","아니요, 모든 성인이 반드시 일해요","네, 일자리 이동 과정의 실업은 남을 수 있어요"],"answer":2,"explanation":"완전고용은 실업률 0%나 전체 인구 취업을 의미하지 않아요.","type":"quiz","lessonCheck":true}},{"id":1164,"quiz":{"q":"자동화로 기존 직무가 줄었는데 구직자의 기술은 새 일자리와 맞지 않아요. 어떤 실업인가요?","options":["구조적 실업","마찰적 실업만으로 설명되는 실업","자발적 휴가"],"answer":0,"explanation":"산업의 요구와 노동자의 기술 사이 불일치가 원인이에요.","type":"quiz","lessonCheck":true}},{"id":211,"quiz":{"q":"예금 안내에 연 4%가 적혀 있어요. 물가를 빼기 전 표시 금리는?","options":["실업률","명목금리","실질금리"],"answer":1,"explanation":"표시된 이자율은 명목금리이고, 구매력 변화를 보려면 물가도 고려해요.","type":"quiz","lessonCheck":true}},{"id":463,"quiz":{"q":"대출 금리가 COFIX에 가산금리를 더하는 방식이에요. COFIX만 오르고 나머지는 같다면 다음 조정 금리는?","options":["내린다","항상 고정된다","오른다"],"answer":2,"explanation":"약정된 금리 조정 시점에 기준 지표의 상승분이 반영될 수 있어요.","type":"quiz","lessonCheck":true}},{"id":732,"quiz":{"q":"예금의 명목금리가 4%, 물가상승률이 3%예요. 단순 차감한 실질금리는?","options":["약 1%","약 7%","약 -1%"],"answer":0,"explanation":"구매력 기준 수익률은 명목금리에서 물가상승률을 빼서 근사해요.","type":"quiz","lessonCheck":true}},{"id":884,"quiz":{"q":"중앙은행이 금리 인상 기조에서 인하 기조로 방향을 바꿨어요. 가까운 표현은?","options":["리디노미네이션","정책 피벗","액면분할"],"answer":1,"explanation":"피벗은 통화정책의 방향 전환을 가리키는 표현이에요.","type":"quiz","lessonCheck":true}},{"id":1133,"quiz":{"q":"가계가 은행 밖에서 지폐와 동전을 보유해요. 이 돈은?","options":["기업의 주식","은행의 지준예치금","현금통화"],"answer":2,"explanation":"현금통화는 민간이 보유한 현금이며 예금이나 중앙은행에 둔 준비금과 구분해요.","type":"quiz","lessonCheck":true}},{"id":233,"quiz":{"q":"은행이 망한다는 소문에 예금자들이 한꺼번에 인출하려 해요. 어떤 현상인가요?","options":["뱅크런","유상증자","무역적자"],"answer":0,"explanation":"동시 인출 요구가 몰려 은행의 유동성에 압박을 주는 상황이에요.","type":"quiz","lessonCheck":true}},{"id":348,"quiz":{"q":"기업의 투자 계획은 그대로인데 금융기관이 대출 공급을 급격히 줄였어요. 가까운 현상은?","options":["주식 액면분할","신용경색","통화 팽창"],"answer":1,"explanation":"신용 공급이 위축되어 자금 조달이 어려워진 상황이에요.","type":"quiz","lessonCheck":true}},{"id":717,"quiz":{"q":"회사가 은행 대출 대신 투자자에게 회사채를 발행해 돈을 모아요. 어떤 금융인가요?","options":["은행 대출을 통한 간접금융","현물 물물교환","직접금융"],"answer":2,"explanation":"자금 수요자가 증권을 발행해 투자자로부터 직접 자금을 조달해요.","type":"quiz","lessonCheck":true}},{"id":914,"quiz":{"q":"보험사가 거액 보험금 지급 위험 일부를 다른 보험사에 넘겨요. 어떤 거래인가요?","options":["재보험","유상증자","예금보험 가입"],"answer":0,"explanation":"보험사가 인수한 위험을 다른 보험사와 나누는 보험 거래예요.","type":"quiz","lessonCheck":true}},{"id":227,"quiz":{"q":"회사가 새 채권을 발행하고 투자자가 최초로 인수했어요. 어느 시장 거래인가요?","options":["외환 현물시장","발행시장","기존 채권 유통시장"],"answer":1,"explanation":"새 증권이 처음 투자자에게 공급되어 발행자에게 자금이 들어오는 거래예요.","type":"quiz","lessonCheck":true}},{"id":350,"quiz":{"q":"회사채 금리 6%, 같은 만기의 국채 금리 3%라면 단순 금리차는?","options":["9%포인트","2%포인트","3%포인트"],"answer":2,"explanation":"신용스프레드는 비교 기준 채권과의 금리 차이로 계산해요.","type":"quiz","lessonCheck":true}},{"id":487,"quiz":{"q":"10년물 금리가 4%, 1년물 금리가 3%예요. 장기 금리에서 단기 금리를 뺀 차이는?","options":["1%포인트","-1%포인트","7%포인트"],"answer":0,"explanation":"비교하는 두 만기를 명시하고 장기 금리에서 단기 금리를 빼요.","type":"quiz","lessonCheck":true}},{"id":755,"quiz":{"q":"주가가 2만 원, 주당순이익이 2천 원이에요. PER은?","options":["20배","10배","0.1배"],"answer":1,"explanation":"주가를 주당순이익으로 나누면 10배예요. 낮은 수치만으로 저평가를 단정하지 않아요.","type":"quiz","lessonCheck":true}},{"id":870,"quiz":{"q":"신용등급이 낮은 회사채가 더 높은 이자를 제시해요. 먼저 함께 볼 위험은?","options":["주식 분할로 주식 수가 늘어날 위험","연결 계좌의 결제 오류 위험","원리금을 못 받을 위험"],"answer":2,"explanation":"높은 금리는 채무불이행 위험에 대한 보상일 수 있어 수익률만 비교하면 안 돼요.","type":"quiz","lessonCheck":true}},{"id":899,"quiz":{"q":"주가가 급락한 뒤 잠깐 반등했어요. 이 사실만으로 장기 상승 전환을 확신할 수 있나요?","options":["아니요, 일시 반등일 수 있어요","네, 장기 상승이 보장돼요","네, 손실 가능성이 사라져요"],"answer":0,"explanation":"급락 후 짧은 반등 뒤 다시 하락하는 흐름도 있어요.","type":"quiz","lessonCheck":true}},{"id":295,"quiz":{"q":"농가가 3개월 뒤 곡물을 정한 가격에 팔기로 선물 계약을 맺었어요. 주된 목적은?","options":["현재 생산비를 없애기","미래 판매 가격 위험을 줄이기","수확량을 확정하기"],"answer":1,"explanation":"가격을 미리 정해 불확실성을 줄이지만 생산량과 비용까지 보장하지는 않아요.","type":"quiz","lessonCheck":true}},{"id":538,"quiz":{"q":"선물 포지션에 손실이 나 추가 증거금 납부를 요구받았어요. 필요한 대응은?","options":["추가 자금 요구는 무시해도 된다","최초 증거금만큼만 손실이 날 수 있다","계약 조건에 맞춰 자금을 준비하거나 포지션을 조정한다"],"answer":2,"explanation":"증거금은 거래 이행을 위한 담보이며 최대 손실을 뜻하지 않아요.","type":"quiz","lessonCheck":true}},{"id":632,"quiz":{"q":"주가 하락에 대비해 정한 가격으로 주식을 팔 권리를 샀어요. 어떤 옵션인가요?","options":["풋옵션","콜옵션","무조건 매수해야 하는 의무"],"answer":0,"explanation":"풋옵션의 매수자는 정해진 조건으로 기초자산을 팔 권리를 가져요.","type":"quiz","lessonCheck":true}},{"id":729,"quiz":{"q":"불안이 커져 투자자들이 위험자산 비중을 줄이는 분위기예요. 가까운 표현은?","options":["유상증자","리스크 오프","리스크 온"],"answer":1,"explanation":"위험을 회피하려는 흐름을 뜻하며 특정 자산의 상승을 보장하지 않아요.","type":"quiz","lessonCheck":true}},{"id":980,"quiz":{"q":"동일한 자산이 두 시장에서 서로 다른 가격으로 동시에 거래돼요. 비용이 없다면 차익거래 방향은?","options":["비싼 시장에서 사고 싼 시장에서 판다","가격 차이와 관계없이 둘 다 산다","싼 시장에서 사고 비싼 시장에서 판다"],"answer":2,"explanation":"동일 자산의 가격 차이를 이용해 매수와 매도를 결합하는 거래예요.","type":"quiz","lessonCheck":true}},{"id":666,"quiz":{"q":"수출기업이 한 달 뒤 달러를 받기로 했는데 원화가 강해졌어요. 받을 달러가 같다면 원화 환산액은?","options":["줄어든다","늘어난다","항상 같다"],"answer":0,"explanation":"달러당 원화 가격이 내려가 같은 달러를 바꿔도 받는 원화가 줄어요.","type":"quiz","lessonCheck":true}},{"id":667,"quiz":{"q":"수입기업이 미래 달러 지급액의 원화 비용을 미리 고정하려 해요. 목적에 맞는 행동은?","options":["달러 지급액을 무시하기","지급 시점에 맞춘 선물환 매입","환율 상승에 더 크게 노출되기"],"answer":1,"explanation":"선물환으로 미래 환율을 정하면 비용 불확실성을 줄일 수 있으나 유리한 환율 변화의 이점도 제한돼요.","type":"quiz","lessonCheck":true}},{"id":1212,"quiz":{"q":"고정환율 체제에서 당국이 자국 통화의 공식 가치를 높였어요. 이를 무엇이라 하나요?","options":["평가절하","통화가치 불변","평가절상"],"answer":2,"explanation":"공식 환율 조정으로 자국 통화 가치를 높이는 조치예요.","type":"quiz","lessonCheck":true}},{"id":292,"quiz":{"q":"외국 관광객이 국내 호텔에서 숙박비를 냈어요. 국제수지상 주로 어느 항목인가요?","options":["서비스수지","상품수지","외환보유액 자체"],"answer":0,"explanation":"여행 관련 서비스 제공에 따른 대가이므로 상품 수출과 구분해요.","type":"quiz","lessonCheck":true}},{"id":781,"quiz":{"q":"같은 시간에 A국은 옷 10벌, B국은 6벌을 만들어요. 옷 생산에서 A국이 가진 것은?","options":["반드시 무역적자","절대우위","반드시 비교우위"],"answer":1,"explanation":"같은 투입으로 더 많이 생산하므로 절대우위지만 비교우위에는 다른 상품의 기회비용도 필요해요.","type":"quiz","lessonCheck":true}},{"id":837,"quiz":{"q":"불황으로 수출도 줄었지만 수입이 더 크게 줄어 무역흑자가 났어요. 가까운 표현은?","options":["수출 호황 확정","교역 중단","불황형 흑자"],"answer":2,"explanation":"흑자만으로 경기가 좋다고 판단할 수 없는 사례예요.","type":"quiz","lessonCheck":true}},{"id":1198,"quiz":{"q":"관세 대신 까다로운 수입 허가와 기술 요건으로 수입이 어려워졌어요. 이런 장벽은?","options":["비관세장벽","수출 보조금","환율 자유화"],"answer":0,"explanation":"세금 형태가 아닌 규정과 절차도 무역을 제한할 수 있어요.","type":"quiz","lessonCheck":true}},{"id":190,"quiz":{"q":"세계 경기가 둔화하는데 한 나라 경기는 다른 방향으로 움직여요. 가까운 표현은?","options":["액면분할","디커플링","커플링"],"answer":1,"explanation":"같이 움직이던 경제 흐름이 서로 떨어져 움직이는 현상이에요.","type":"quiz","lessonCheck":true}},{"id":302,"quiz":{"q":"국가 사이 무역 규범과 무역 분쟁을 다루는 국제기구를 찾고 있어요. 해당 기구는?","options":["IMF","WHO","WTO"],"answer":2,"explanation":"WTO는 국제 무역 규범과 분쟁 해결을 다루며 통화 안정 기구와 구분돼요.","type":"quiz","lessonCheck":true}},{"id":433,"quiz":{"q":"유로 사용 지역의 통화정책을 분석하려 해요. 확인할 중앙은행은?","options":["유럽중앙은행","미국 연방준비제도","일본은행"],"answer":0,"explanation":"ECB는 유로 지역 통화정책의 중심 기관이에요.","type":"quiz","lessonCheck":true}},{"id":605,"quiz":{"q":"기업들이 국제 공급망을 줄이고 생산을 자국이나 가까운 국가로 돌려요. 연결되는 흐름은?","options":["완전 자유무역의 완성","탈세계화","국제 분업의 무조건 확대"],"answer":1,"explanation":"국경을 넘는 연결과 의존을 줄이려는 움직임으로 볼 수 있어요.","type":"quiz","lessonCheck":true}},{"id":728,"quiz":{"q":"두 나라의 경기가 비슷한 방향으로 함께 움직이는 경향이 커졌어요. 가까운 표현은?","options":["디커플링","디플레이션","커플링"],"answer":2,"explanation":"경제 변수나 시장의 동조화가 커진 상황이에요.","type":"quiz","lessonCheck":true}},{"id":276,"quiz":{"q":"가입자들이 보험료를 내고 질병이나 노후 같은 위험에 대비하는 공적 제도예요. 가까운 유형은?","options":["사회보험","주식 배당","개인 간 증여"],"answer":0,"explanation":"사회적 위험을 공동으로 분담하는 보험 방식의 사회보장제도예요.","type":"quiz","lessonCheck":true}},{"id":817,"quiz":{"q":"공공사업의 현재가치 기준 편익이 120억 원, 비용이 100억 원이에요. 순편익은?","options":["-20억 원","20억 원","220억 원"],"answer":1,"explanation":"편익에서 비용을 빼요. 실제 판단에서는 분배와 불확실성도 함께 검토해요.","type":"quiz","lessonCheck":true}},{"id":908,"quiz":{"q":"같은 소비세 10만 원을 낼 때 소득 100만 원인 사람의 부담 비중은 1천만 원인 사람보다?","options":["낮다","같다","높다"],"answer":2,"explanation":"같은 세액이라도 저소득자의 소득 대비 부담이 더 커 역진성이 나타나요.","type":"quiz","lessonCheck":true}},{"id":965,"quiz":{"q":"법에 정한 날짜가 지나면 특별한 연장 없이 지원 제도가 종료돼요. 이런 장치는?","options":["일몰제","영구 보장","소급 과세"],"answer":0,"explanation":"기한을 정해 제도의 효력을 끝내고 존속 필요성을 다시 검토하게 해요.","type":"quiz","lessonCheck":true}},{"id":1154,"quiz":{"q":"소득이 높은 구간에 더 높은 세율을 적용해요. 세율 구조는?","options":["소득과 무관한 동일 세액","누진세","정액세"],"answer":1,"explanation":"과세표준이 커질수록 적용 세율이 높아지는 구조예요.","type":"quiz","lessonCheck":true}},{"id":429,"quiz":{"q":"자산 가치는 충분하지만 오늘 갚을 현금을 제때 마련하지 못해요. 가장 직접적인 위험은?","options":["환율 상승만의 위험","생산량 과잉","유동성리스크"],"answer":2,"explanation":"지급할 시점에 필요한 자금을 구하지 못하는 위험이에요.","type":"quiz","lessonCheck":true}},{"id":900,"quiz":{"q":"오랫동안 경고된 큰 부채 위험을 방치하다 문제가 터졌어요. 가까운 비유는?","options":["회색 코뿔소","전혀 예상 못 한 블랙 스완","완전한 무위험"],"answer":0,"explanation":"발생 가능성과 충격이 큰데도 간과하는 위험을 가리켜요.","type":"quiz","lessonCheck":true}},{"id":552,"quiz":{"q":"요금 청구기관이 보낸 고지서의 납부 정보를 이용해 은행에서 요금을 냈어요. 가까운 방식은?","options":["외환 선물거래","지로 납부","주식 청약"],"answer":1,"explanation":"지로는 공과금 등 대량 수납에 쓰는 지급 방식이에요.","type":"quiz","lessonCheck":true}},{"id":660,"quiz":{"q":"지폐를 기울이니 무늬와 색이 달라져 진위를 확인하는 데 도움을 줘요. 이런 장치는?","options":["이자 쿠폰","신용평가등급","홀로그램"],"answer":2,"explanation":"각도에 따라 다르게 보이는 광학 효과를 위조 방지에 활용해요.","type":"quiz","lessonCheck":true}},{"id":706,"quiz":{"q":"휴대전화를 단말기에 가까이 대고 짧은 거리에서 정보를 주고받아 결제했어요. 관련 기술은?","options":["NFC","위성항법만으로 하는 결제","장거리 라디오 방송"],"answer":0,"explanation":"NFC는 가까운 거리에서 기기 간 데이터를 주고받는 무선통신 기술이에요.","type":"quiz","lessonCheck":true}},{"id":204,"quiz":{"q":"판매자에게 바로 돈을 주지 않고 구매 확인 뒤 중개자가 대금을 지급해요. 어떤 장치인가요?","options":["신용 창조","에스크로","공매도"],"answer":1,"explanation":"제3자가 대금을 보관했다가 조건 충족 후 지급해 거래 위험을 줄여요.","type":"quiz","lessonCheck":true}},{"id":336,"quiz":{"q":"어떤 코인이 1달러 가치 유지를 목표로 해요. 이용 전 적절한 판단은?","options":["언제나 법적으로 1달러가 보장된다","가격이 하락할 수 없다","목표와 실제 가격 안정성은 다를 수 있다"],"answer":2,"explanation":"가치 고정 목표가 있어도 준비자산이나 구조에 따라 가격 이탈 위험이 있어요.","type":"quiz","lessonCheck":true}},{"id":501,"quiz":{"q":"온라인 계약서가 누가 작성했는지 확인하고 변경 여부를 검증하려 해요. 관련 수단은?","options":["전자서명","환율 고시","현금 인출"],"answer":0,"explanation":"전자서명은 전자문서의 서명자 확인 등에 쓰이며 구체적인 검증 방식은 기술에 따라 달라요.","type":"quiz","lessonCheck":true}},{"id":603,"quiz":{"q":"기업의 배출량이 보유 배출권보다 많아 추가 배출권을 구입해요. 거래 대상은?","options":["무제한 오염 허가","정해진 양의 온실가스를 배출할 수 있는 권리","기업 주주총회 의결권"],"answer":1,"explanation":"배출권은 제도에서 허용한 배출량 단위의 권리이며 무제한 배출을 허용하지 않아요.","type":"quiz","lessonCheck":true}},{"id":986,"quiz":{"q":"법에서 금지한 사항 외에는 사업을 허용하는 규제 방식을 택했어요. 유형은?","options":["허용 목록에 든 것만 가능한 규제","모든 사업 금지","네거티브 규제"],"answer":2,"explanation":"금지할 대상을 열거하는 방식으로, 허용 대상만 나열하는 방식과 달라요.","type":"quiz","lessonCheck":true}},{"id":427,"quiz":{"q":"유동자산 200억 원, 유동부채 100억 원이면 유동비율은?","options":["200%","50%","100%"],"answer":0,"explanation":"유동자산을 유동부채로 나눈 뒤 100을 곱해요. 자산의 실제 환금성도 별도로 봐야 해요.","type":"quiz","lessonCheck":true}},{"id":445,"quiz":{"q":"영업이익 60억 원, 이자비용 20억 원이면 이자보상배율은?","options":["80배","3배","0.33배"],"answer":1,"explanation":"영업이익을 이자비용으로 나누어 이자 지급 부담을 살펴요.","type":"quiz","lessonCheck":true}},{"id":592,"quiz":{"q":"경쟁 업체들이 서로 가격을 낮추지 않기로 합의했어요. 어떤 행위인가요?","options":["독립적인 가격경쟁","소비자 간 공동구매","카르텔"],"answer":2,"explanation":"경쟁자끼리 가격 등을 합의해 경쟁을 제한하는 담합의 사례예요.","type":"quiz","lessonCheck":true}},{"id":702,"quiz":{"q":"회사가 경쟁사의 경영권을 확보하려 지분을 인수했어요. 가까운 거래는?","options":["M&A","일반 상품 구매","국채 상환"],"answer":0,"explanation":"기업의 합병과 인수는 사업이나 경영권의 결합을 목적으로 해요.","type":"quiz","lessonCheck":true}},{"id":831,"quiz":{"q":"제품을 한 개 더 팔자 총수입이 8천 원 늘었어요. 이 추가 수입은?","options":["매몰비용","한계수입","평균고정비용"],"answer":1,"explanation":"판매량 한 단위 증가에 따른 총수입의 증가분이에요.","type":"quiz","lessonCheck":true}},{"id":871,"quiz":{"q":"회사를 정리해 자산을 각각 팔 경우 회수할 수 있는 금액을 추정해요. 평가하는 것은?","options":["계속 영업할 때의 가치만","주식의 액면가 합계","청산가치"],"answer":2,"explanation":"사업을 계속하는 가치와 달리 자산을 처분하는 상황을 기준으로 해요.","type":"quiz","lessonCheck":true}},{"id":933,"quiz":{"q":"쇼핑몰에서 인기 상품 몇 개보다 수많은 비인기 상품의 매출 합계가 크게 나타나요. 가까운 현상은?","options":["롱테일 법칙","독점 가격 결정","은행 신용 창조"],"answer":0,"explanation":"각각은 적게 팔려도 다양한 상품의 누적 수요가 중요해질 수 있어요.","type":"quiz","lessonCheck":true}},{"id":976,"quiz":{"q":"누적 손실로 회사 자본총계가 자본금보다 작아졌어요. 어떤 상태인가요?","options":["액면분할","자본잠식","무조건 현금 과잉"],"answer":1,"explanation":"손실이 쌓여 납입된 자본금까지 줄어든 상태이며 현금 잔액과는 다른 개념이에요.","type":"quiz","lessonCheck":true}},{"id":1045,"quiz":{"q":"총비용 100만 원으로 200개를 생산했어요. 개당 평균비용은?","options":["2천 원","20만 원","5천 원"],"answer":2,"explanation":"총비용을 생산량으로 나누면 단위당 평균비용이 나와요.","type":"quiz","lessonCheck":true}},{"id":1075,"quiz":{"q":"생산을 잠시 멈춰도 계약상 매장 월세를 그대로 내야 해요. 단기적으로 어떤 비용인가요?","options":["고정비용","생산량에 비례하는 가변비용","한계수입"],"answer":0,"explanation":"해당 기간 생산량과 무관하게 발생하는 비용이에요.","type":"quiz","lessonCheck":true}},{"id":1095,"quiz":{"q":"카페가 가격 할인 대신 서비스와 공간을 개선해 고객을 모아요. 어떤 경쟁인가요?","options":["생산 중단","비가격 경쟁","가격 인하 경쟁"],"answer":1,"explanation":"가격 외의 품질과 경험으로 경쟁하는 방식이에요.","type":"quiz","lessonCheck":true}},{"id":1033,"quiz":{"q":"가격이 1% 오르면 수요량이 약 1% 줄어드는 구간이에요. 탄력성 절댓값은?","options":["0","무한대","1"],"answer":2,"explanation":"두 변화율의 크기가 같으므로 단위탄력적이에요.","type":"quiz","lessonCheck":true}},{"id":1049,"quiz":{"q":"곡물을 더 생산할수록 포기해야 할 옷의 양이 점점 많아져요. 나타나는 원리는?","options":["기회비용 체증","기회비용 소멸","모든 자원의 생산성 동일"],"answer":0,"explanation":"다른 용도에 적합한 자원까지 옮기면서 추가 생산의 기회비용이 커져요.","type":"quiz","lessonCheck":true}},{"id":1068,"quiz":{"q":"짧은 기간에는 공장 건물 크기를 바꿀 수 없지만 근무 시간은 늘릴 수 있어요. 건물은?","options":["최종 소비재","고정 생산요소","가변 생산요소"],"answer":1,"explanation":"분석 기간 안에 투입량을 조절할 수 없는 요소를 고정 요소라고 해요.","type":"quiz","lessonCheck":true}},{"id":1073,"quiz":{"q":"노동자 4명이 100개, 5명이 118개를 만들어요. 다섯 번째 노동자의 한계생산은?","options":["118개","약 23.6개","18개"],"answer":2,"explanation":"노동 투입 한 단위 증가에 따른 산출 증가분 118-100을 계산해요.","type":"quiz","lessonCheck":true}},{"id":1079,"quiz":{"q":"총고정비용은 100만 원으로 같고 생산량이 100개에서 200개로 늘어요. 평균고정비용은?","options":["1만 원에서 5천 원으로 감소","1만 원에서 2만 원으로 증가","100만 원으로 유지"],"answer":0,"explanation":"같은 고정비용을 더 많은 제품에 나누어 부담해요.","type":"quiz","lessonCheck":true}},{"id":1092,"quiz":{"q":"주도 기업이 가격을 바꾸자 다른 업체들이 비슷하게 따라가요. 가까운 현상은?","options":["물물교환","가격 선도","완전한 가격 수용"],"answer":1,"explanation":"한 기업의 가격 결정이 다른 기업의 가격 조정에 기준이 되는 상황이에요.","type":"quiz","lessonCheck":true}},{"id":1105,"quiz":{"q":"한 사람의 만족이 높아지고 다른 누구의 만족도 낮아지지 않았어요. 이 변화는?","options":["반드시 완전한 평등","반드시 총생산 감소","파레토 개선"],"answer":2,"explanation":"누군가 더 나아지면서 아무도 더 나빠지지 않는 변화예요. 평등을 보장하는 개념은 아니에요.","type":"quiz","lessonCheck":true}},{"id":1161,"quiz":{"q":"미래 소득은 충분할 듯하지만 지금 돈이 없고 빌릴 수도 없어 소비를 못 해요. 어떤 제약인가요?","options":["유동성 제약","소비 욕구 소멸","공급 독점"],"answer":0,"explanation":"원하는 시점에 쓸 자금을 확보하지 못해 현재 지출이 제한돼요.","type":"quiz","lessonCheck":true}},{"id":1171,"quiz":{"q":"높은 물가상승으로 현금을 적게 보유하려고 은행을 더 자주 오가요. 이런 번거로움의 비용은?","options":["관세","구두창 비용","메뉴비용"],"answer":1,"explanation":"현금 보유를 줄이기 위해 드는 시간과 거래 노력의 비용을 뜻해요.","type":"quiz","lessonCheck":true}},{"id":138,"quiz":{"q":"기업들의 생산과 주문 전망 응답을 종합해 경기에 대한 심리를 살펴요. 가까운 지표는?","options":["소비자물가지수","원화 현금 발행액","기업심리지수"],"answer":2,"explanation":"기업의 체감과 전망을 조사한 심리 지표이며 실제 생산 증가율과 같지는 않아요.","type":"quiz","lessonCheck":true}},{"id":163,"quiz":{"q":"생산 증가와 함께 환경 훼손 비용도 반영해 경제 성과를 보려 해요. 연결되는 개념은?","options":["녹색GDP","명목환율","주가수익비율"],"answer":0,"explanation":"환경 비용 등을 조정해 기존 생산 지표의 한계를 보완하려는 개념이에요.","type":"quiz","lessonCheck":true}},{"id":287,"quiz":{"q":"판매보다 생산이 많아 창고의 완제품이 늘었어요. 직접 연결되는 통계는?","options":["원화 실효환율","생산자제품재고지수","실업률"],"answer":1,"explanation":"생산자가 보유한 제품 재고의 변화를 보는 지표예요.","type":"quiz","lessonCheck":true}},{"id":470,"quiz":{"q":"같은 양의 자본을 투입해 더 많은 부가가치를 만들었어요. 개선된 것은?","options":["법정 세율","환율 수준","자본생산성"],"answer":2,"explanation":"자본 투입 대비 산출이나 부가가치가 커진 상황이에요.","type":"quiz","lessonCheck":true}},{"id":531,"quiz":{"q":"식당이 음식을 만들려고 식재료를 사서 사용했어요. 국민계정에서 이 투입은?","options":["중간소비","가계 최종소비","고정자본형성"],"answer":0,"explanation":"생산 과정에서 소비되는 재화와 서비스의 가치예요.","type":"quiz","lessonCheck":true}},{"id":639,"quiz":{"q":"회사가 노동의 대가로 임금과 사용자 부담 사회보험료를 지급해요. 국민계정의 관련 항목은?","options":["토지 매각대금","피용자보수","배당소득"],"answer":1,"explanation":"피용자보수는 임금뿐 아니라 고용주가 부담하는 사회기여금 등도 포함해요.","type":"quiz","lessonCheck":true}},{"id":1122,"quiz":{"q":"판매 부진으로 설비가 놀고 있을 때 지출 증가가 생산을 늘린다고 설명해요. 가까운 관점은?","options":["수요는 생산에 아무 영향도 없다는 관점","가격 수준만으로 모든 생산을 설명하는 관점","유효수요를 중시하는 케인스 관점"],"answer":2,"explanation":"유휴 자원이 있는 상황에서 총수요가 실제 생산과 고용에 영향을 준다고 봐요.","type":"quiz","lessonCheck":true}},{"id":1126,"quiz":{"q":"현재 소득이 0이어도 저축을 꺼내 최소한의 식비를 써요. 단순 소비함수에서 이 부분은?","options":["기본소비","유발소비만","기업 투자"],"answer":0,"explanation":"소득과 무관하게 발생하는 소비를 기본소비 또는 독립소비라고 해요.","type":"quiz","lessonCheck":true}},{"id":1177,"quiz":{"q":"경제성장을 노동 증가, 자본 증가, 생산성 향상으로 나누어 설명해요. 어떤 분석인가요?","options":["물가지수 품목 교체","성장회계","복식부기만의 자산 기록"],"answer":1,"explanation":"성장률에 각 생산요소와 생산성이 얼마나 기여했는지 분해하는 분석이에요.","type":"quiz","lessonCheck":true}},{"id":168,"quiz":{"q":"근로자 보수 총액은 10% 늘고 생산량은 그대로예요. 단위노동비용은?","options":["10% 감소","변화 없음","10% 증가"],"answer":2,"explanation":"산출 한 단위에 들어가는 노동비용이 같은 비율로 높아져요.","type":"quiz","lessonCheck":true}},{"id":1104,"quiz":{"q":"소득 하위 40%의 소득을 상위 20% 소득으로 나눈 비율이 높아졌어요. 다른 조건이 같다면?","options":["분배가 더 균등해진 방향","분배가 더 불균등해진 방향","실업자가 반드시 감소"],"answer":0,"explanation":"10분위분배율이 높을수록 하위 집단의 상대적 소득 몫이 커졌음을 뜻해요.","type":"quiz","lessonCheck":true}},{"id":274,"quiz":{"q":"중앙은행이 향후 금리 결정의 조건과 방향을 미리 설명했어요. 어떤 수단인가요?","options":["기업 배당 공시","포워드 가이던스","정부 예산 편성"],"answer":1,"explanation":"앞으로의 정책에 대한 소통으로 시장의 기대 형성에 영향을 줘요.","type":"quiz","lessonCheck":true}},{"id":584,"quiz":{"q":"은행의 일시적 유동성 부족이 시스템 위기로 번지지 않도록 중앙은행이 긴급 자금을 공급해요. 역할은?","options":["기업 주주총회","조세 징수자","최종대부자"],"answer":2,"explanation":"중앙은행은 금융시스템 안정을 위해 최후의 유동성 공급자 역할을 할 수 있어요.","type":"quiz","lessonCheck":true}},{"id":616,"quiz":{"q":"명목 GDP가 500, 통화량이 100이라면 같은 기간 통화유통속도는?","options":["5","0.2","600"],"answer":0,"explanation":"명목 GDP를 통화량으로 나누어 계산해요.","type":"quiz","lessonCheck":true}},{"id":1132,"quiz":{"q":"은행이 지급준비를 위해 중앙은행 계좌에 예치한 돈이에요. 해당 항목은?","options":["기업의 매출채권","지준예치금","가계 보유 현금"],"answer":1,"explanation":"은행이 중앙은행에 보유하는 준비금으로 민간 예금과 구분돼요.","type":"quiz","lessonCheck":true}},{"id":1135,"quiz":{"q":"은행의 실제 준비금은 120억 원, 법정 필요액은 100억 원이에요. 초과준비금은?","options":["100억 원","220억 원","20억 원"],"answer":2,"explanation":"법정 필요액을 넘겨 보유한 준비금 120-100을 계산해요.","type":"quiz","lessonCheck":true}},{"id":1146,"quiz":{"q":"명목통화량은 그대로인데 물가 수준이 두 배가 됐어요. 실질통화량은?","options":["절반이 된다","두 배가 된다","그대로다"],"answer":0,"explanation":"실질통화량은 명목통화량을 물가 수준으로 나눈 값이에요.","type":"quiz","lessonCheck":true}},{"id":1157,"quiz":{"q":"경기 악화를 파악한 뒤 정책 결정까지 몇 달이 걸렸어요. 어떤 시차인가요?","options":["결제 시차","내부시차","외부시차"],"answer":1,"explanation":"문제 인식에서 정책 결정과 실행까지 걸리는 시간이 내부시차예요.","type":"quiz","lessonCheck":true}},{"id":121,"quiz":{"q":"기업이 은행 대출을 줄이고 시장에서 직접 채권을 발행해요. 연결되는 흐름은?","options":["은행 대출 의존 증가","현금 사용 금지","금융의 탈중개화"],"answer":2,"explanation":"은행의 자금 중개를 거치지 않는 직접 자금 조달이 확대되는 흐름이에요.","type":"quiz","lessonCheck":true}},{"id":389,"quiz":{"q":"고객의 예금을 받아 자금을 조달하는 금융기관을 분류해요. 기준에 맞는 분류는?","options":["예금취급기관","비금융 제조기업","일반 소매점"],"answer":0,"explanation":"예금을 수신하는 기능을 기준으로 금융기관을 묶은 분류예요.","type":"quiz","lessonCheck":true}},{"id":392,"quiz":{"q":"대출금 90억 원, 예수금 100억 원인 단순 사례에서 예대율은?","options":["10%","90%","약 111%"],"answer":1,"explanation":"대출금을 예수금으로 나눠 계산해요. 실제 규제에는 별도 산정 범위가 있어요.","type":"quiz","lessonCheck":true}},{"id":746,"quiz":{"q":"월중에는 잔액이 자주 바뀌었지만 월말 마지막 날 잔액만 확인했어요. 어떤 잔액인가요?","options":["평잔","월간 수입 합계","말잔"],"answer":2,"explanation":"말잔은 기간 말 시점의 잔액이고, 평잔은 기간 동안의 평균 잔액이에요.","type":"quiz","lessonCheck":true}},{"id":449,"quiz":{"q":"채권 보유자가 만기 전에도 약정된 날짜마다 이자를 받아요. 가까운 채권 유형은?","options":["이표채","이자가 전혀 없는 영구 주식","무조건 할인채"],"answer":0,"explanation":"이표채는 약정에 따라 이자를 정기적으로 지급하는 채권이에요.","type":"quiz","lessonCheck":true}},{"id":507,"quiz":{"q":"채권자가 약정 조건에 따라 채권을 발행사의 주식으로 바꿀 수 있어요. 어떤 채권인가요?","options":["무조건 상환만 가능한 회사채","전환사채","일반 국채"],"answer":1,"explanation":"전환사채에는 주식으로 전환할 수 있는 권리가 붙어 있어요.","type":"quiz","lessonCheck":true}},{"id":571,"quiz":{"q":"채권시장 경색에 대응하려 공동 자금을 모아 채권 매입에 활용해요. 가까운 장치는?","options":["가계 여행 적금","주식 액면분할","채권시장안정펀드"],"answer":2,"explanation":"채권시장의 자금 흐름과 안정을 지원하려는 펀드예요.","type":"quiz","lessonCheck":true}},{"id":714,"quiz":{"q":"옵션 가격에 반영된 코스피200의 예상 변동성이 커졌어요. 직접 연결되는 지표는?","options":["V-KOSPI","소비자물가지수","주택 전세가율"],"answer":0,"explanation":"V-KOSPI는 옵션에 내재된 변동성 기대를 나타내며 주가 상승 방향을 확정하지 않아요.","type":"quiz","lessonCheck":true}},{"id":777,"quiz":{"q":"미래 현금흐름은 같지만 적용 할인율이 높아졌어요. DCF 평가가치는?","options":["반드시 같다","낮아진다","높아진다"],"answer":1,"explanation":"미래 현금을 더 큰 할인율로 할인하면 현재가치가 줄어들어요.","type":"quiz","lessonCheck":true}},{"id":475,"quiz":{"q":"여러 대출채권을 묶고 그 현금흐름을 바탕으로 증권을 발행해요. 어떤 과정인가요?","options":["예금의 현금 인출","일반 상품 생산","자산유동화"],"answer":2,"explanation":"현금흐름을 만들어 내는 자산을 기초로 거래 가능한 증권을 만드는 방식이에요.","type":"quiz","lessonCheck":true}},{"id":530,"quiz":{"q":"주택담보대출에서 들어오는 원리금을 바탕으로 증권을 만들었어요. 관련 상품은?","options":["MBS","일반 보통주","원자재 현물"],"answer":0,"explanation":"주택저당증권은 주택담보대출 채권 등을 기초로 발행되는 증권이에요.","type":"quiz","lessonCheck":true}},{"id":278,"quiz":{"q":"자유로운 자본 이동과 고정환율을 유지하면서 독립적 통화정책까지 완벽히 추구하려 해요. 삼불원칙의 판단은?","options":["세 목표 중 어느 하나도 달성할 수 없다","세 목표를 동시에 완전히 달성하기 어렵다","세 목표는 언제나 충돌하지 않는다"],"answer":1,"explanation":"세 목표 사이에 제약이 있어 정책 조합에서 선택이 필요해요.","type":"quiz","lessonCheck":true}},{"id":566,"quiz":{"q":"만기 때 통화 원금 전액 대신 약정환율과 기준환율의 차액만 정산해요. 어떤 거래인가요?","options":["현금 환전","일반 예금 인출","NDF"],"answer":2,"explanation":"차액결제선물환은 환율 차이로 생긴 금액을 결제하는 구조예요.","type":"quiz","lessonCheck":true}},{"id":1209,"quiz":{"q":"환율은 주로 시장에서 정해지지만 당국이 급변을 완화하려 개입해요. 가까운 제도는?","options":["관리변동환율제","엄격한 고정환율제","외환거래 전면 금지"],"answer":0,"explanation":"시장 변동을 허용하면서 필요시 당국이 관리하는 방식이에요.","type":"quiz","lessonCheck":true}},{"id":321,"quiz":{"q":"수출기업이 해외 구매자의 대금 미지급 위험에 대비하려 보험에 들어요. 목적에 맞는 제도는?","options":["예금보험","수출보험","화재보험만"],"answer":1,"explanation":"수출대금 회수 등에 따르는 위험을 보험으로 분담하는 장치예요.","type":"quiz","lessonCheck":true}},{"id":533,"quiz":{"q":"상품을 사들여 국내에 반입하거나 가공하지 않고 제3국에 원형 그대로 팔았어요. 가까운 무역 방식은?","options":["단순 중개수수료 거래","국내 최종소비","중계무역"],"answer":2,"explanation":"중계무역은 물품을 사들여 다시 파는 거래이며 거래를 연결만 하는 중개와 구분돼요.","type":"quiz","lessonCheck":true}},{"id":700,"quiz":{"q":"통화가치 하락 후 무역수지가 먼저 나빠졌다가 시간이 지나 개선돼요. 가까운 현상은?","options":["J커브효과","즉시 균형 보장","일물일가의 법칙 자체"],"answer":0,"explanation":"계약과 수출입 물량이 조정되는 데 시간이 걸리면서 나타날 수 있어요.","type":"quiz","lessonCheck":true}},{"id":1194,"quiz":{"q":"역내 관세 철폐 후 비싼 국내 생산을 회원국의 저렴한 수입품이 대체해요. 어떤 효과인가요?","options":["수입 전면 중단","무역창출효과","무역전환효과"],"answer":1,"explanation":"더 낮은 비용의 생산으로 교역이 새로 발생하는 경우예요.","type":"quiz","lessonCheck":true}},{"id":1199,"quiz":{"q":"정부가 한 해 특정 상품 수입량을 1만 톤까지로 제한해요. 어떤 조치인가요?","options":["종가관세만 부과","수입 완전 자유화","수입할당제"],"answer":2,"explanation":"가격에 세금을 붙이는 대신 수입 가능한 물량에 한도를 둬요.","type":"quiz","lessonCheck":true}},{"id":1205,"quiz":{"q":"국제수지 통계의 거래 자료를 집계했는데 대응 항목의 합계가 정확히 맞지 않아요. 통계상 조정 항목은?","options":["오차 및 누락","관세수입","기업 배당"],"answer":0,"explanation":"자료의 포착 범위와 시점 차이 등으로 생긴 불일치를 조정하는 항목이에요.","type":"quiz","lessonCheck":true}},{"id":103,"quiz":{"q":"외화가 급히 필요해질 때 IMF 지원이나 국가 간 통화스왑을 활용하려 해요. 이런 장치들의 묶음은?","options":["기업 생산라인","글로벌금융안전망","국내 소매 결제망"],"answer":1,"explanation":"외화 유동성 위기에 대응하기 위한 국제적 지원 체계예요.","type":"quiz","lessonCheck":true}},{"id":164,"quiz":{"q":"개발도상국의 온실가스 감축과 기후 적응 사업을 지원하려 해요. 관련 국제기금은?","options":["일반 연금기금","예금보험기금","녹색기후기금"],"answer":2,"explanation":"GCF는 개발도상국의 기후변화 대응을 지원하는 기금이에요.","type":"quiz","lessonCheck":true}},{"id":261,"quiz":{"q":"전후 국제통화질서에서 달러를 금과 연결하고 다른 통화를 달러에 연결했어요. 해당 체제는?","options":["브레튼우즈체제","자유변동환율만의 체제","모든 국가의 금화 직접 사용"],"answer":0,"explanation":"달러를 중심으로 고정환율 질서를 만든 역사적 체제예요.","type":"quiz","lessonCheck":true}},{"id":434,"quiz":{"q":"미국 밖 은행에 달러 표시 예금을 맡겼어요. 이 달러 자금의 일반적 명칭은?","options":["엔화 예금","유로달러","유로화 현금"],"answer":1,"explanation":"유로달러의 유로는 통화 유로를 뜻하지 않으며 미국 밖의 달러 예금 등을 가리켜요.","type":"quiz","lessonCheck":true}},{"id":478,"quiz":{"q":"정부가 자국의 광물에 대한 통제를 강화하고 수출을 제한해요. 관련 흐름은?","options":["자원 거래 완전 자유화","무역장벽 철폐","자원민족주의"],"answer":2,"explanation":"자원을 국가의 전략 자산으로 보고 자국 이익을 우선하는 움직임이에요.","type":"quiz","lessonCheck":true}},{"id":596,"quiz":{"q":"해외 거래 상대의 경영은 안정적이지만 그 나라의 정치 혼란으로 송금이 막혔어요. 어떤 위험인가요?","options":["컨트리리스크","상품 재고 부족만의 위험","개별 제품 품질 위험"],"answer":0,"explanation":"상대국의 정치와 경제 환경이 거래 이행에 영향을 주는 국가위험이에요.","type":"quiz","lessonCheck":true}},{"id":1087,"quiz":{"q":"상품 가격과 관계없이 한 병당 100원의 세금을 붙여요. 어떤 세금 방식인가요?","options":["소득세","종량세","종가세"],"answer":1,"explanation":"거래 금액이 아니라 수량 단위를 기준으로 세액을 매겨요.","type":"quiz","lessonCheck":true}},{"id":1125,"quiz":{"q":"단순 케인스 모형에서 정부지출과 정액세를 같은 금액만큼 늘려요. 투자 고정, 수입과 구축효과가 없다면 균형재정승수는?","options":["0","-1","1"],"answer":2,"explanation":"이 단순 모형에서는 지출 증가 효과가 증세에 따른 소비 감소보다 커서 늘린 정부지출만큼 국민소득이 증가해요.","type":"quiz","lessonCheck":true}},{"id":115,"quiz":{"q":"여러 은행이 서로 빌려준 돈이 많아 한 은행의 문제가 다른 은행으로 번져요. 중요한 구조는?","options":["금융시스템 상호연계성","완전한 기관 간 독립","가계 소비계절성"],"answer":0,"explanation":"기관 사이의 자금과 거래 연결이 충격 전파 경로가 될 수 있어요.","type":"quiz","lessonCheck":true}},{"id":339,"quiz":{"q":"은행이 집값 급락과 실업 급증을 가정해 손실을 계산해요. 어떤 점검인가요?","options":["주식 액면분할","스트레스 테스트","지난달 이익만 단순 집계"],"answer":1,"explanation":"불리한 가상 상황에서 자본과 유동성이 버틸 수 있는지 평가해요.","type":"quiz","lessonCheck":true}},{"id":343,"quiz":{"q":"보유 채권의 시장금리가 올라 채권 가격이 떨어졌어요. 직접적인 위험 유형은?","options":["직원 입력 실수만의 위험","단순 배송 지연","시장리스크"],"answer":2,"explanation":"금리 등 시장가격 변화로 자산 가치에 손실이 발생하는 위험이에요.","type":"quiz","lessonCheck":true}},{"id":418,"quiz":{"q":"전산 장애 때문에 결제가 중단되고 손실이 났어요. 주된 위험 유형은?","options":["운영리스크","원자재 가격 위험만","외환 평가절하만"],"answer":0,"explanation":"시스템과 절차의 실패 등으로 발생하는 손실 위험이에요.","type":"quiz","lessonCheck":true}},{"id":663,"quiz":{"q":"현금 결제에 쓰는 지폐와 동전의 금액 종류를 1, 5, 10 등의 조합으로 설계해요. 무엇을 정하나요?","options":["주가수익비율","화폐의 액면체계","통화정책 금리"],"answer":1,"explanation":"화폐 권종과 액면 금액의 구성을 정하는 문제예요.","type":"quiz","lessonCheck":true}},{"id":481,"quiz":{"q":"참여자가 연산 경쟁을 통해 블록 생성에 필요한 조건을 충족해요. 가까운 합의 방식은?","options":["지분증명","중앙은행의 직접 승인만","작업증명"],"answer":2,"explanation":"작업증명은 연산 작업을 수행했다는 증거를 블록 검증 등에 활용해요.","type":"quiz","lessonCheck":true}},{"id":179,"quiz":{"q":"채권자가 대출채권을 주식으로 바꾸어 주주가 됐어요. 이 조치는?","options":["출자전환","단순 만기 연장","원금의 현금 상환"],"answer":0,"explanation":"부채가 지분으로 바뀌는 구조이며 채권자가 주주의 위험을 부담하게 돼요.","type":"quiz","lessonCheck":true}},{"id":565,"quiz":{"q":"시장점유율이 50%, 30%, 20%인 세 기업뿐이에요. 백분율 수치를 제곱해 더한 HHI는?","options":["1,000","3,800","100"],"answer":1,"explanation":"50의 제곱 2,500, 30의 제곱 900, 20의 제곱 400을 더해요.","type":"quiz","lessonCheck":true}},{"id":1057,"quiz":{"q":"소비자가 A보다 B를 좋아한다고 순서를 매기지만 만족의 절대량은 말하지 않아요. 가까운 접근은?","options":["기수적 효용의 정확한 측정","가격만으로 선호 확정","서수적 효용"],"answer":2,"explanation":"서수적 효용은 선호의 순서가 중요하며 만족의 크기를 직접 비교하지 않아요.","type":"quiz","lessonCheck":true}},{"id":1091,"quiz":{"q":"기업들이 한 번만이 아니라 매달 반복해 거래하면서 다음 거래의 대응까지 고려해요. 분석 틀은?","options":["반복 게임","일회성 게임만","완전한 의사결정 부재"],"answer":0,"explanation":"현재 행동이 이후 상대의 행동에 영향을 줄 수 있어 반복 관계가 중요해요.","type":"quiz","lessonCheck":true}},{"id":1099,"quiz":{"q":"비옥한 땅과 척박한 땅에 같은 노동을 들였는데 비옥한 땅의 수확이 더 많아요. 차이에서 생기는 지대는?","options":["임금의 완전 소멸","차액지대","모든 토지의 동일 수확"],"answer":1,"explanation":"토지의 생산성 등 조건 차이가 초과 수익의 원인이 될 수 있어요.","type":"quiz","lessonCheck":true}},{"id":1173,"quiz":{"q":"물가상승률을 낮추는 과정에서 발생한 생산 손실을 낮아진 상승률과 비교해요. 관련 개념은?","options":["예대율","식료품 비중","희생비율"],"answer":2,"explanation":"디스인플레이션에 수반되는 산출 손실을 측정하는 비율이에요.","type":"quiz","lessonCheck":true}},{"id":277,"quiz":{"q":"자동차 생산이 철강과 전기 산업에 얼마나 연결되는지 표로 분석하려 해요. 적합한 자료는?","options":["산업연관표","개별 주식 호가표","가계 출석부"],"answer":0,"explanation":"산업별로 무엇을 투입하고 어디에 산출물을 공급하는지 보여 주는 표예요.","type":"quiz","lessonCheck":true}},{"id":493,"quiz":{"q":"철강 공급 여건 개선이 철강을 쓰는 자동차 산업의 생산을 돕고 있어요. 가까운 효과는?","options":["산업 간 연결 없음","전방연쇄효과","자동차 수요가 철강을 늘리는 후방 효과"],"answer":1,"explanation":"중간재 공급 산업의 변화가 이를 사용하는 하류 산업에 미치는 효과예요.","type":"quiz","lessonCheck":true}},{"id":1149,"quiz":{"q":"전통적인 AD-AS 설명에서 명목통화량이 같은데 물가가 낮아지면 금리를 통한 총수요 경로는?","options":["실질통화량 감소, 금리 상승 방향","통화량과 금리는 전혀 무관","실질통화량 증가, 금리 하락, 투자 확대 방향"],"answer":2,"explanation":"다른 조건이 같다면 실질 화폐 잔액 증가가 금리를 낮추고 투자를 자극하는 이자율 효과예요.","type":"quiz","lessonCheck":true}},{"id":1179,"quiz":{"q":"기술 진보가 없는 솔로 모형에서 노동자 1인당 자본이 더 늘지 않고 일정해졌어요. 가까운 상태는?","options":["균제상태","자본의 무한 가속 성장","모든 생산 중단"],"answer":0,"explanation":"1인당 투자가 감가상각과 인구 증가에 필요한 자본 보충을 상쇄하는 상태예요.","type":"quiz","lessonCheck":true}},{"id":200,"quiz":{"q":"명목 GDP가 500이고 사람들이 보유하려는 화폐가 100이에요. 마샬의 k는?","options":["400","0.2","5"],"answer":1,"explanation":"명목소득 대비 화폐 보유 비율이므로 100을 500으로 나눠요.","type":"quiz","lessonCheck":true}},{"id":607,"quiz":{"q":"물가가 목표보다 높고 생산도 잠재 수준을 웃돌아요. 기본 테일러 준칙이 시사하는 금리 방향은?","options":["무조건 인하","어떤 경우에도 동결","인상 방향"],"answer":2,"explanation":"물가갭과 산출갭이 양수이면 기준금리를 높이는 방향의 신호가 돼요. 실제 결정은 더 많은 요인을 봐요.","type":"quiz","lessonCheck":true}},{"id":614,"quiz":{"q":"중앙은행이 은행들의 여유 자금을 기한부 예금으로 받아 시중 유동성을 흡수해요. 관련 수단은?","options":["통화안정계정","가계 주택담보대출","기업 주식 공모"],"answer":0,"explanation":"중앙은행이 금융기관의 자금을 일정 기간 묶어 유동성을 조절하는 수단이에요.","type":"quiz","lessonCheck":true}},{"id":1144,"quiz":{"q":"저축 공급이 늘고 투자 수요는 같아요. 단순 대부자금시장 모형에서 균형 이자율은?","options":["반드시 변하지 않는다","내린다","오른다"],"answer":1,"explanation":"빌려줄 자금의 공급 증가가 균형 이자율을 낮추는 방향으로 작용해요.","type":"quiz","lessonCheck":true}},{"id":1145,"quiz":{"q":"실질통화량이 일정한 단순 LM 모형에서 소득이 늘어 화폐수요가 커졌어요. 균형 이자율은?","options":["내린다","항상 0이 된다","오른다"],"answer":2,"explanation":"고정된 화폐공급 아래 늘어난 화폐수요를 맞추려면 이자율 상승이 필요해요.","type":"quiz","lessonCheck":true}},{"id":569,"quiz":{"q":"보유 채권의 시장 가격이 떨어져 장부 가치를 현재 시장 가격으로 다시 계산해요. 어떤 평가인가요?","options":["채권시가평가","취득원가만 유지","액면가만 고정 적용"],"answer":0,"explanation":"매입 시 가격이 아니라 평가 시점의 시장 가치를 반영해요.","type":"quiz","lessonCheck":true}},{"id":725,"quiz":{"q":"채권 입찰에서 두 낙찰자가 각각 써낸 금리대로 발행 조건을 적용받아요. 방식은?","options":["입찰 없는 수의계약","복수금리방식","모든 낙찰자에게 같은 금리 적용"],"answer":1,"explanation":"낙찰자마다 자신이 제시한 금리가 적용되는 방식이에요.","type":"quiz","lessonCheck":true}},{"id":344,"quiz":{"q":"같은 날 1,000원에 1달러, 1,200원에 3달러가 거래됐어요. 거래량 가중평균 환율은?","options":["1,100원","1,200원","1,150원"],"answer":2,"explanation":"총 원화 4,600원을 총 거래량 4달러로 나눠요.","type":"quiz","lessonCheck":true}},{"id":403,"quiz":{"q":"외화자산이 100만 달러, 외화부채가 80만 달러예요. 단순 순외화포지션은?","options":["20만 달러 매입초과","20만 달러 매도초과","180만 달러 매입초과"],"answer":0,"explanation":"외화자산에서 외화부채를 빼면 양수이므로 순자산 또는 매입초과 상태예요.","type":"quiz","lessonCheck":true}},{"id":421,"quiz":{"q":"원화와 위안화를 달러로 바꾸는 중간 단계 없이 교환했어요. 어느 시장의 거래인가요?","options":["주식 발행시장","원·위안 직거래시장","원·달러 시장만"],"answer":1,"explanation":"두 통화를 직접 교환해 달러 경유 거래와 구분돼요.","type":"quiz","lessonCheck":true}},{"id":779,"quiz":{"q":"정책 충격 뒤 환율이 새 장기 수준을 넘어 크게 움직였다가 되돌아와요. 가까운 현상은?","options":["항상 고정된 환율","환율 변화 없음","환율 오버슈팅"],"answer":2,"explanation":"단기 반응이 장기 균형 변화보다 커지는 현상이에요.","type":"quiz","lessonCheck":true}},{"id":1189,"quiz":{"q":"수출 생산은 늘었는데 수출가격 하락으로 교역조건이 크게 악화해 후생이 줄었어요. 가능한 현상은?","options":["궁핍화 성장","성장이면 항상 후생 증가","수입 완전 중단"],"answer":0,"explanation":"특정 조건에서는 교역조건 악화가 생산 확대의 이득을 넘어설 수 있어요.","type":"quiz","lessonCheck":true}},{"id":1156,"quiz":{"q":"정부지출이 같은데 감세를 국채로 메워요. 가계가 미래 증세를 완전히 예상하고 추가 소득을 저축한다는 이론은?","options":["화폐수요가 항상 0이라는 이론","리카도 대등정리","현재 감세가 항상 같은 만큼 소비를 늘린다는 이론"],"answer":1,"explanation":"엄격한 가정 아래 조세와 국채 조달의 소비 효과가 같아질 수 있다는 주장으로 현실의 보편 법칙은 아니에요.","type":"quiz","lessonCheck":true}},{"id":133,"quiz":{"q":"은행이 계속 영업하는 상태에서 손실을 흡수할 핵심 자본의 충분성을 봐요. 관련 자본 분류는?","options":["일반 고객 예금","단기 차입금 전부","기본자본(Tier 1)"],"answer":2,"explanation":"기본자본은 영업을 지속하는 동안 손실을 흡수할 수 있는 자본이에요.","type":"quiz","lessonCheck":true}},{"id":225,"quiz":{"q":"여러 나라 감독당국이 은행 자본 규제의 국제 기준을 함께 논의해요. 관련 기구는?","options":["바젤은행감독위원회","세계보건기구","국내 개별 은행 이사회"],"answer":0,"explanation":"BCBS는 은행 감독과 건전성 규제의 국제 기준을 논의하는 기구예요.","type":"quiz","lessonCheck":true}},{"id":326,"quiz":{"q":"은행이 장기 대출을 매우 짧은 차입금에만 의존해 운용해요. 특히 살펴볼 지표는?","options":["실업률","순안정자금조달비율","소비자물가상승률"],"answer":1,"explanation":"NSFR은 자산 구조에 비해 안정적인 자금조달이 충분한지 살펴요.","type":"quiz","lessonCheck":true}},{"id":450,"quiz":{"q":"은행이 특정 기업에 빌려준 돈이 100억 원에서 150억 원으로 늘었어요. 그 기업에 대한 익스포저는?","options":["작아졌다","항상 같다","커졌다"],"answer":2,"explanation":"해당 거래 상대의 위험에 노출된 금액이 늘어난 상황이에요.","type":"quiz","lessonCheck":true}},{"id":472,"quiz":{"q":"같은 위험의 자산을 가진 두 은행 중 손실을 흡수할 자본이 더 많은 은행을 비교해요. 우선 유리한 측면은?","options":["자본적정성","반드시 높은 수익률","반드시 낮은 모든 운영비"],"answer":0,"explanation":"다른 조건이 같다면 손실에 대비한 자본 여력이 더 크다고 볼 수 있어요.","type":"quiz","lessonCheck":true}},{"id":739,"quiz":{"q":"동일한 금액의 두 자산에 서로 다른 위험가중치가 적용돼요. 위험가중자산이 더 큰 것은?","options":["항상 두 자산이 같다","위험가중치가 높은 자산","위험가중치가 낮은 자산"],"answer":1,"explanation":"같은 노출액에 더 높은 가중치를 곱하면 위험가중자산이 더 커져요.","type":"quiz","lessonCheck":true}},{"id":37,"quiz":{"q":"주식을 팔았지만 종이 증서를 옮기지 않고 장부의 계좌 간 기록을 변경했어요. 방식은?","options":["실물 현금 배송","주식 액면분할","계좌대체"],"answer":2,"explanation":"예탁·등록 장부의 계좌 이동으로 권리 이전을 처리하는 방식이에요.","type":"quiz","lessonCheck":true}},{"id":171,"quiz":{"q":"월요일에 외환 거래를 맺고 그 월요일에 결제했어요. 결제 시점 분류는?","options":["당일결제","익일결제","익익일결제"],"answer":0,"explanation":"거래 계약일과 자금 결제일이 같은 방식이에요.","type":"quiz","lessonCheck":true}},{"id":173,"quiz":{"q":"회사가 하나의 계좌에서 직원 100명에게 급여를 한꺼번에 이체해요. 가까운 지급 방식은?","options":["외환 차익거래","대량지급","개별 주식 청약"],"answer":1,"explanation":"한 지급자가 여러 수취인에게 급여나 연금 등을 일괄 지급하는 방식이에요.","type":"quiz","lessonCheck":true}},{"id":361,"quiz":{"q":"은행 간 지급 지시가 들어올 때마다 서로 상계하지 않고 즉시 전액 결제해요. 방식은?","options":["하루 말 차액결제만","한 달 뒤 일괄 결제","실시간총액결제"],"answer":2,"explanation":"각 지급 건을 실시간으로 개별 결제하므로 총액 기준이에요.","type":"quiz","lessonCheck":true}},{"id":462,"quiz":{"q":"학원이 여러 수강생 계좌에서 동의받은 수강료를 일괄 출금하려 해요. 관련 공동망은?","options":["CMS공동망","주식 거래소","신용평가 등급표"],"answer":0,"explanation":"CMS는 다수 계좌의 자금 수납과 지급을 지원하는 서비스예요.","type":"quiz","lessonCheck":true}},{"id":502,"quiz":{"q":"종이 대신 전자문서로 약속어음을 발행하고 온라인으로 이전해요. 해당 수단은?","options":["현물 금 인도","전자어음","종이 수표 배송"],"answer":1,"explanation":"어음의 발행과 유통을 전자적으로 처리하는 지급 수단이에요.","type":"quiz","lessonCheck":true}},{"id":534,"quiz":{"q":"청산기관이 매도자에게는 매수자, 매수자에게는 매도자가 되어 거래 이행을 관리해요. 역할은?","options":["단순 광고 중개인","개별 거래의 구경꾼","중앙거래당사자"],"answer":2,"explanation":"CCP가 거래 사이에 들어가 상대방 위험을 관리하며 위험 자체가 모두 없어지는 것은 아니에요.","type":"quiz","lessonCheck":true}},{"id":540,"quiz":{"q":"증권을 넘길 때 대금도 함께 결제되도록 두 절차를 연결했어요. 방식은?","options":["증권대금동시결제","증권만 먼저 주고 대금은 무조건 나중","단순 현금 보관"],"answer":0,"explanation":"증권 인도와 대금 지급을 연계해 한쪽만 이행되는 원금 위험을 줄여요.","type":"quiz","lessonCheck":true}},{"id":558,"quiz":{"q":"은행들이 결제 건을 모아 정해진 시각에 일괄 처리해요. 시간 처리 방식은?","options":["결제 영구 연기","지정시점처리","모든 건의 즉시 처리"],"answer":1,"explanation":"미리 정한 시각에 묶어서 처리하는 방식으로 실시간 처리와 구분돼요.","type":"quiz","lessonCheck":true}},{"id":567,"quiz":{"q":"A은행이 B은행에 100억 원, B은행이 A은행에 70억 원을 지급해야 해요. 차액결제라면?","options":["B가 A에게 30억 원 지급","A가 B에게 170억 원 지급","A가 B에게 30억 원 지급"],"answer":2,"explanation":"서로의 지급 의무를 상계한 순차액 100-70만 이전해요.","type":"quiz","lessonCheck":true}},{"id":659,"quiz":{"q":"결제 안전성을 확보하면서 상계로 필요한 자금도 절약하려 해요. 두 방식의 장점을 결합한 것은?","options":["혼합형결제시스템","실물 현금 운송만","결제 없는 거래"],"answer":0,"explanation":"총액결제와 차액결제의 장점을 결합해 안전성과 유동성 효율을 추구해요.","type":"quiz","lessonCheck":true}},{"id":695,"quiz":{"q":"외환 거래에서 원화는 보냈지만 상대 은행이 파산해 받을 달러를 못 받았어요. 대표적인 위험은?","options":["주식 희석 위험","Herstatt 리스크","단순 환율 변동만의 위험"],"answer":1,"explanation":"두 통화 결제 시점 차이 등으로 한쪽 원금만 지급되는 외환결제 위험이에요.","type":"quiz","lessonCheck":true}}]$payload$::jsonb) p
), updated AS (
 UPDATE public.words w SET visuals=COALESCE(w.visuals,'[]'::jsonb)||jsonb_build_array(p.quiz)
 FROM payload p WHERE w.id=p.id AND NOT COALESCE(w.visuals,'[]'::jsonb) @> jsonb_build_array(p.quiz)
 RETURNING w.id
)
SELECT count(*) AS added_questions FROM updated;
COMMIT;
